const SALARY_COMMITMENT_PATTERN =
  /\b(?:my\s+)?(?:expected|desired|requested)?\s*(?:salary|hourly rate|compensation)\b|\b(?:usd|php|\$|₱)\s*\d/gi;
const START_DATE_COMMITMENT_PATTERN =
  /\b(?:i\s+can|i'm|i am|available\s+to)\s+(?:start|join)(?:\s+on|\s+from|\s+immediately)?\b/gi;
const COMPLETION_CLAIM_PATTERN =
  /\b(?:(?:i\s+(?:(?:have|already)\s+)?|my\s+)?(?:attached|included)\s+(?:(?:my|the)\s+)?(?:requested\s+)?(?:cv|curriculum vitae|r[ée]sum[ée]|attachment)|(?:(?:my|the)\s+)?(?:requested\s+)?(?:cv|curriculum vitae|r[ée]sum[ée])\s+(?:(?:(?:is|was|has\s+been)\s+)?(?:attached|included)(?:\s+successfully)?|accompanies\s+(?:this|the)\s+application)|you\s+(?:will|can)\s+find\s+(?:(?:my|the)\s+)?(?:requested\s+)?(?:cv|curriculum vitae|r[ée]sum[ée])\s+(?:attached|included)|(?:i\s+(?:have\s+|already\s+)?)?(?:completed|submitted)\s+(?:the|your|this)?\s*(?:assessment|test|form|questionnaire|application)|(?:the|your|this)?\s*(?:assessment|test|form|questionnaire)\s+(?:(?:is|was)\s+(?:complete|completed|submitted)|has\s+been\s+(?:completed|submitted))|recorded\s+(?:a|the)\s+(?:video|recording))\b/gi;
const INTERNAL_CONTEXT_PATTERN =
  /\b(?:requirement gaps?|match tier|application warnings?|ranking score|internal evaluation|selected proof refs?)\b/gi;

function removeMatches(value, patterns) {
  return patterns.reduce(
    (remaining, pattern) => remaining.replace(pattern, " "),
    value
  );
}

const SCREENING_QUESTION_STOP_WORDS = new Set([
  "about", "answer", "been", "built", "could", "describe", "does",
  "have", "most", "please", "tell", "that", "their", "thing", "this",
  "using", "what", "when", "where", "which", "with", "would", "you",
  "your"
]);

function screeningQuestionKeywords(question) {
  return [
    ...normalizeText(question)
      .toLowerCase()
      .matchAll(/[a-z0-9]+/g)
  ]
    .map((match) => match[0])
    .filter(
      (token) =>
        (token.length >= 4 || token === "ai") &&
        !SCREENING_QUESTION_STOP_WORDS.has(token)
    );
}

function screeningAnswerErrors(message, pack) {
  const normalizedMessage = normalizeText(message).toLowerCase();
  const errors = [];
  const questions = (pack?.screening_questions ?? []).filter(
    (question) =>
      question?.answer_status === "answer_in_message" &&
      question?.review_acknowledged === true
  );
  for (const question of questions) {
    const id = String(question?.id || "unknown");
    const keywords = [...new Set(screeningQuestionKeywords(question?.text))];
    const matchedKeywords = keywords.filter((keyword) =>
      new RegExp(`\\b${keyword}\\b`, "i").test(normalizedMessage)
    );
    const requiredMatches = Math.min(2, keywords.length);
    if (requiredMatches > 0 && matchedKeywords.length < requiredMatches) {
      errors.push(
        `screening answer is not woven into natural prose: ${id}`
      );
    }
  }
  return errors;
}

const ADJACENT_QUALIFIER_PATTERN =
  /\b(?:rather than|instead of|not an? exact|different|transfer(?:able|red|s)?|adapt(?:able|ed|ing|s)?|comparable|adjacent|while)\b/i;
const UNSUPPORTED_FREQUENCY_PATTERN =
  /\b(?:routinely|always|daily|consistently|every\s+(?:system|project|client|workflow)|each\s+(?:ai\s+)?system|all\s+(?:systems|projects|workflows))\b/gi;
const MATERIAL_CLAIM_PATTERN =
  /\b(?:hipaa|pci|soc\s*2|gdpr|compliant|patient|billing|evaluation frameworks?|safety evaluations?|safety guardrails?|agent reliability|edge-case behavior|accuracy)\b/gi;
const CLAIM_SCAFFOLD_TOKENS = new Set([
  "adjacent", "also", "are", "aspects", "direct", "draft",
  "drafts", "durable", "gave", "guarded", "integration",
  "incident", "integrations", "involved", "issue", "its", "message", "most", "one",
  "orchestrate", "orchestration", "patterns", "rather", "state",
  "than", "them", "thing", "those", "tools", "track", "tracking", "transferable",
  "use", "used", "uses", "useful", "while"
]);
const CANDIDATE_OWNERSHIP_PATTERN =
  /\bi(?:'ve| have)?\s+(?:build|built|create|created|develop|developed|deliver|delivered|implement|implemented|design|designed|automate|automated|resolve|resolved|fix|fixed|diagnose|diagnosed|write|wrote|author|authored|maintain|maintained|ship|shipped|integrate|integrated|use|used|add|added|rebuild|rebuilt)\b/i;
const NON_MATERIAL_CONVERSATION_PATTERN =
  /^i\s+(?:can|would be happy to)\s+(?:walk through|discuss|share|explain)\b/i;

function groundingRoots(token) {
  const normalized = String(token || "")
    .toLowerCase()
    .replace(/[.]+$/, "");
  const roots = new Set([normalized]);
  const irregular = {
    automation: "automate",
    automations: "automate",
    built: "build",
    fixed: "diagnose",
    fixing: "diagnose",
    generation: "generate",
    resolved: "diagnose",
    wrote: "write",
    written: "write",
    gave: "give",
    won: "win"
  };
  if (irregular[normalized]) roots.add(irregular[normalized]);
  if (normalized.endsWith("ies") && normalized.length > 4) {
    roots.add(`${normalized.slice(0, -3)}y`);
  }
  if (normalized.endsWith("ing") && normalized.length > 5) {
    const base = normalized.slice(0, -3);
    roots.add(base);
    roots.add(`${base}e`);
  }
  if (normalized.endsWith("ed") && normalized.length > 4) {
    const base = normalized.slice(0, -2);
    roots.add(base);
    roots.add(`${base}e`);
  }
  if (normalized.endsWith("es") && normalized.length > 4) {
    roots.add(normalized.slice(0, -1));
    roots.add(normalized.slice(0, -2));
  } else if (normalized.endsWith("s") && normalized.length > 3) {
    roots.add(normalized.slice(0, -1));
  }
  return roots;
}

function groundingRootSet(value) {
  return new Set(
    [...proofTokens(value)].flatMap((token) => [...groundingRoots(token)])
  );
}

function tokenIsGrounded(token, authoritativeRoots, allowedRoots = new Set()) {
  if (CLAIM_SCAFFOLD_TOKENS.has(token)) return true;
  return [...groundingRoots(token)].some(
    (root) => authoritativeRoots.has(root) || allowedRoots.has(root)
  );
}

function adjacentRootsAllowedInSentence(sentence, pack) {
  const allowed = new Set();
  if (!ADJACENT_QUALIFIER_PATTERN.test(sentence)) return allowed;
  for (const coverage of pack?.requirement_coverage ?? []) {
    if (coverage.classification !== "adjacent") continue;
    const elementTokens = [...proofTokens(coverage.element)];
    if (
      elementTokens.some((token) =>
        includesAlias(sentence, [token.toLowerCase()])
      )
    ) {
      const allowedTokens = [
        ...elementTokens,
        ...proofTokens((coverage.material_differences ?? []).join(" "))
      ];
      for (const token of allowedTokens) {
        groundingRoots(token).forEach((root) => allowed.add(root));
      }
    }
  }
  return allowed;
}

function messageBodySentences(message) {
  const lines = String(message || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => {
      const normalized = normalizeText(line);
      if (!/^(?:(?:linkedin|github|portfolio)\s*:\s*)?https?:\/\//i.test(normalized)) {
        return normalized;
      }
      // Contact-only lines are presentation, but prose appended to a contact
      // URL is still application content and must pass claim grounding.
      return normalizeText(
        normalized.replace(
          /^(?:(?:linkedin|github|portfolio)\s*:\s*)?https?:\/\/\S+\s*(?:[-–—:;]\s*)?/i,
          ""
        )
      );
    })
    .filter(Boolean);
  const body = lines
    .slice(1)
    .filter(
      (line) =>
        !/^(?:hi|hello|dear)\b(?:\s+(?:there|hiring team|team|sir|madam)){0,2}[,!]?$/i.test(
          line
        ) &&
        line !== "I would welcome a conversation about how my experience fits this role."
    )
    .join(" ");
  return (
    body.match(/.*?(?:[.!?]+(?:["'’”\)\]]+)?(?=\s|$)|$)/g) ?? []
  )
    .map((sentence) => normalizeText(sentence))
    .filter(Boolean);
}

const CLAIM_CLAUSE_BOUNDARY =
  /\s*;\s*|\bthat\s+(?=(?:collect|collects|generate|generates|archive|archives)\b)|,\s+(?=(?:and|but|while)\s+)|,\s+(?=(?:and\s+)?(?:the\s+)?[A-Za-z0-9.+#-]+(?:\s+[A-Za-z0-9.+#-]+){0,2}\s+API\s+(?:to|for)\b)|\s+(?:and|but)\s+(?=(?:i|we|it|they|this|that|the|is|are|was|were|has|have|build|built|maintain|maintained|diagnose|diagnosed|resolve|resolved|fix|fixed|create|created|develop|developed|deliver|delivered|implement|implemented|design|designed|automate|automated|write|wrote|author|authored|ship|shipped|integrate|integrated|add|added|rebuild|rebuilt|collect|collects|generate|generated|generates|archive|archives|restore|restored|reduce|reduced)\b)/i;

function claimClauses(value) {
  return normalizeText(value)
    .split(CLAIM_CLAUSE_BOUNDARY)
    .map((clause) => normalizeText(clause).replace(/^(?:and|but|while)\s+/i, ""))
    .filter(Boolean);
}

function proofFactClauses(value) {
  return normalizeText(value)
    .replace(
      /\bthat\s+(?=(?:collects?|generates?|archives?|writes?|resolves?|diagnoses?|restores?|reduces?|replaces?|removes?|saves?)\b)/gi,
      "; "
    )
    .replace(
      /,\s+(?:and\s+)?(?=(?:collects?|generates?|archives?|writes?|resolves?|diagnoses?|restores?|reduces?|replaces?|removes?|saves?)\b)/gi,
      "; "
    )
    .split(
      /\s*;\s*|\s+and\s+(?=(?:wrote|authored|resolved|rebuilt|delivered)\b)/i
    )
    .map((clause) => normalizeText(clause).replace(/^and\s+/i, ""))
    .filter(Boolean);
}

function proofGroundingModels(proof, profile) {
  const lines = String(proof?.evidence || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map(normalizeText)
    .filter(Boolean);
  const attributes = [];
  const facts = [];
  for (const line of lines) {
    if ([...proofTokens(line)].length <= 5) {
      attributes.push(line);
      continue;
    }
    facts.push(...proofFactClauses(line));
  }
  const identity = `${proof?.reference || ""} ${proof?.label || ""} ${
    profile.candidate.name
  } ${profile.candidate.location}`;
  const identityRoots = groundingRootSet(identity);
  const model = (kind, text) => {
    const roots = new Set(identityRoots);
    groundingRootSet(text).forEach((root) => roots.add(root));
    return { kind, roots };
  };
  return [
    model("identity", ""),
    model("attributes", attributes.join(" ")),
    ...facts.map((fact) => model("fact", fact)),
    model("overview", `${attributes.join(" ")} ${facts.join(" ")}`)
  ];
}

const ATTRIBUTE_RELATION_PATTERN =
  /\b(?:archive|archived|archives|build|built|collect|collected|collects|create|created|deliver|delivered|diagnose|diagnosed|generate|generated|generates|implement|implemented|rebuild|rebuilt|reduce|reduced|remove|removed|resolve|resolved|restore|restored|save|saved|write|writes|wrote)\b/i;
const OVERVIEW_CLAIM_PATTERN =
  /\b(?:build|built|create|created|develop|developed)\b[^.!?]{0,160}\b(?:application|automation|marketplace|platform|project|system|workflow)\b/i;
const PRECISE_RELATION_PATTERN =
  /\b(?:archive|archived|archives|collect|collected|collects|deliver|delivered|diagnose|diagnosed|generate|generated|generates|rebuild|rebuilt|reduce|reduced|remove|removed|resolve|resolved|restore|restored|save|saved|write|writes|wrote)\b/i;

function groundingModelEligible(model, clause) {
  if (model.kind === "attributes") {
    return !ATTRIBUTE_RELATION_PATTERN.test(clause);
  }
  if (model.kind === "overview") {
    return (
      OVERVIEW_CLAIM_PATTERN.test(clause) &&
      !PRECISE_RELATION_PATTERN.test(
        clause.replace(/\b(?:build|built)\b/i, "")
      )
    );
  }
  return true;
}

const ASSOCIATION_NUMBER_WORDS = new Set([
  "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
  "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
  "sixteen", "seventeen", "eighteen", "nineteen", "twenty", "thirty",
  "forty", "fifty", "sixty", "seventy", "eighty", "ninety", "hundred",
  "thousand", "million", "billion"
]);
const ASSOCIATION_STOP_WORDS = new Set([
  "a", "an", "and", "approximately", "as", "at", "by", "for", "from", "i",
  "in", "into", "my", "of", "on", "or", "the", "to", "using", "with"
]);

function associationTokens(value) {
  return (
    normalizeText(value).toLowerCase().match(/[a-z0-9+#.]+/g) ?? []
  ).filter((token) => !ASSOCIATION_STOP_WORDS.has(token));
}

function isAssociationNumber(token) {
  return /^\d+(?:[.,]\d+)?(?:\+|%|ms)?$/.test(token) ||
    ASSOCIATION_NUMBER_WORDS.has(token);
}

function numericAssociationsGrounded(clause, evidence) {
  const claimTokens = associationTokens(clause);
  const evidenceTokens = associationTokens(evidence);
  for (const [index, token] of claimTokens.entries()) {
    if (!isAssociationNumber(token)) continue;
    if (
      token === "one" &&
      ["example", "issue", "project", "thing"].includes(claimTokens[index + 1])
    ) {
      continue;
    }
    const claimContext = claimTokens
      .slice(Math.max(0, index - 2), index)
      .concat(claimTokens.slice(index + 1, index + 3))
      .filter((entry) => !isAssociationNumber(entry));
    const requiredOverlap = Math.min(1, new Set(claimContext).size);
    if (requiredOverlap === 0) return false;
    const matched = evidenceTokens.some((entry, evidenceIndex) => {
      if (entry !== token) return false;
      const claimDirectional = claimTokens
        .slice(index + 1, index + 4)
        .filter((context) => !isAssociationNumber(context));
      const evidenceDirectional = evidenceTokens
        .slice(evidenceIndex + 1, evidenceIndex + 4)
        .filter((context) => !isAssociationNumber(context));
      const directionalSource =
        claimDirectional.length > 0
          ? claimDirectional
          : claimTokens
              .slice(Math.max(0, index - 3), index)
              .filter((context) => !isAssociationNumber(context));
      const directionalTarget =
        evidenceDirectional.length > 0
          ? evidenceDirectional
          : evidenceTokens
              .slice(Math.max(0, evidenceIndex - 3), evidenceIndex)
              .filter((context) => !isAssociationNumber(context));
      const directionalRoots = groundingRootSet(directionalTarget.join(" "));
      if (
        !directionalSource.some((context) =>
          [...groundingRoots(context)].some((root) =>
            directionalRoots.has(root)
          )
        )
      ) {
        return false;
      }
      const evidenceRoots = groundingRootSet(
        evidenceTokens
          .slice(Math.max(0, evidenceIndex - 2), evidenceIndex)
          .concat(evidenceTokens.slice(evidenceIndex + 1, evidenceIndex + 3))
          .filter((context) => !isAssociationNumber(context))
          .join(" ")
      );
      const overlap = claimContext.filter((context) =>
        [...groundingRoots(context)].some((root) => evidenceRoots.has(root))
      ).length;
      return overlap >= requiredOverlap;
    });
    if (!matched) return false;
  }
  return true;
}

function coverageProofRecords(coverage, pack, profile) {
  const selected = new Map(
    (pack?.selected_proofs ?? []).map((proof) => [
      proof.reference,
      { ...proof, text: proof.text ?? proof.evidence ?? "" }
    ])
  );
  const canonical = new Map(
    proofCandidates(profile).map((proof) => [proof.reference, proof])
  );
  return (coverage.evidence_refs ?? [])
    .map((reference) => selected.get(reference) ?? canonical.get(reference))
    .filter(Boolean);
}

function proofTechnologySignals(coverage, pack, profile) {
  const signals = [];
  for (const reference of coverage.evidence_refs ?? []) {
    const projectId = reference.match(/^projects:(.+)$/)?.[1];
    if (projectId) {
      const project = profile.projects.find((entry) => entry.id === projectId);
      if (project) signals.push(project.name, ...(project.technologies ?? []));
    }
    const experienceId = reference.match(/^experience:(.+)$/)?.[1];
    if (experienceId) {
      const experience = profile.experience.find((entry) => entry.id === experienceId);
      if (experience) {
        signals.push(
          experience.organization,
          ...knownSkillsInText(profileEvidenceText(experience), profile)
        );
      }
    }
  }
  return [...new Set(signals.map(normalizeText).filter(Boolean))];
}

function relevantSummarySentences(message, evidenceRefs, pack, profile) {
  const coverage = { evidence_refs: evidenceRefs };
  const proofs = coverageProofRecords(coverage, pack, profile);
  const proofTokenSet = proofTokens(proofs.map((proof) => proof.text).join(" "));
  const labels = proofs.map((proof) => normalizeText(proof.label).toLowerCase());
  return messageBodySentences(message).filter((sentence) => {
    const normalized = sentence.toLowerCase();
    if (labels.some((label) => label && normalized.includes(label))) return true;
    const overlap = [...proofTokens(sentence)].filter((token) =>
      proofTokenSet.has(token)
    ).length;
    return overlap >= 3;
  });
}

function relevantSummaryParagraphs(message, evidenceRefs, pack, profile) {
  const coverage = { evidence_refs: evidenceRefs };
  const proofs = coverageProofRecords(coverage, pack, profile);
  const proofTokenSet = proofTokens(proofs.map((proof) => proof.text).join(" "));
  const labels = proofs.map((proof) => normalizeText(proof.label).toLowerCase());
  return String(message || "")
    .replace(/\r\n?/g, "\n")
    .split(/\n\s*\n/)
    .map((paragraph) => normalizeText(paragraph))
    .filter(
      (paragraph) =>
        paragraph &&
        !paragraph.startsWith("Subject line:") &&
        !/^(?:hi|hello|dear)\b.*[,!]$/i.test(paragraph) &&
        paragraph !==
          "I would welcome a conversation about how my experience fits this role." &&
        !/^https?:\/\//i.test(paragraph)
    )
    .filter((paragraph) => {
      const normalized = paragraph.toLowerCase();
      if (labels.some((label) => label && normalized.includes(label))) return true;
      const overlap = [...proofTokens(paragraph)].filter((token) =>
        proofTokenSet.has(token)
      ).length;
      return overlap >= 3;
    });
}

function requirementCoverageErrors(message, pack, profile) {
  const errors = [];
  const normalized = normalizeText(message);
  const urls = new Set(extractUrls(normalized));
  const planned = new Map(
    (pack?.message_plan?.requirements ?? []).map((requirement) => [
      requirement.requirement_id,
      requirement
    ])
  );
  const lines = String(message || "")
    .split(/\r?\n/)
    .map((line) => normalizeText(line))
    .filter(Boolean);

  for (const requirement of pack?.message_plan?.requirements ?? []) {
    if (!requirement.required) continue;
    if (requirement.disposition === "missing") {
      errors.push(`mandatory requirement lacks approved evidence: ${requirement.requirement_id}`);
      continue;
    }
    if (requirement.disposition === "manual_action") continue;
    if (
      Array.isArray(requirement.approved_urls) &&
      requirement.approved_urls.length > 0 &&
      !requirement.approved_urls.some((url) => urls.has(url))
    ) {
      errors.push(`required approved link is missing: ${requirement.requirement_id}`);
    }
    if (requirement.format_value) {
      const expected = requirement.format_value.replace(/[.!]+$/, "").toLowerCase();
      const bodyFirstLine = (lines[1] ?? "").replace(/[.!]+$/, "").toLowerCase();
      if (bodyFirstLine !== expected) {
        errors.push(`required message format is missing: ${requirement.format_value}`);
      }
    }
    const relevantSentences = relevantSummarySentences(
      message,
      requirement.evidence_refs,
      pack,
      profile
    );
    const countValues = {
      sentence_count: relevantSentences.length,
      word_count: relevantSentences
        .join(" ")
        .match(/[\p{L}\p{N}+#.]+/gu)?.length ?? 0,
      paragraph_count: relevantSummaryParagraphs(
        message,
        requirement.evidence_refs,
        pack,
        profile
      ).length
    };
    for (const [constraintName, unit] of [
      ["sentence_count", "sentences"],
      ["word_count", "words"],
      ["paragraph_count", "paragraphs"]
    ]) {
      const constraint = requirement.constraints?.[constraintName];
      if (!constraint) continue;
      const count = countValues[constraintName];
      if (count < constraint.minimum || count > constraint.maximum) {
        errors.push(
          `required project summary must contain ${constraint.minimum}-${constraint.maximum} relevant ${unit}; found ${count}`
        );
      }
    }
  }

  for (const coverage of pack?.requirement_coverage ?? []) {
    if (!coverage.required || coverage.classification === "manual_action") continue;
    if (coverage.classification === "missing") continue;
    const requirement = planned.get(coverage.requirement_id);
    if (!requirement) continue;
    const signals = proofTechnologySignals(coverage, pack, profile);
    const proofLabels = coverageProofRecords(coverage, pack, profile).map(
      (proof) => proof.label
    );
    const hasSignal = (signal) =>
      signal && includesAlias(normalized, [signal.toLowerCase()]);
    if (coverage.element_kind === "named_technology") {
      const requested = coverage.element.replace(/^Use of\s+/i, "");
      if (!hasSignal(requested)) {
        errors.push(`mandatory answer element is missing: ${coverage.element_id}`);
      }
      if (coverage.classification === "adjacent") {
        const actualProviders = [
          ...coverageProofRecords(coverage, pack, profile).flatMap((proof) =>
            proofProviders(proof.text)
          ),
          ...signals
        ].filter(
          (provider) => provider.toLowerCase() !== requested.toLowerCase()
        );
        const explicitDifference = messageBodySentences(message).some(
          (sentence) =>
            hasSignal.call(null, requested) &&
            includesAlias(sentence, [requested.toLowerCase()]) &&
            actualProviders.some((provider) =>
              includesAlias(sentence, [provider.toLowerCase()])
            ) &&
            ADJACENT_QUALIFIER_PATTERN.test(sentence)
        );
        if (
          !explicitDifference
        ) {
          errors.push(`adjacent material difference is not explicit: ${coverage.element_id}`);
        }
      }
    } else if (coverage.element_kind === "agentic_workflow") {
      if (
        !/\b(?:workflow|automation|pipeline)\b/i.test(normalized) ||
        !proofLabels.some(hasSignal)
      ) {
        errors.push(`mandatory workflow example is missing: ${coverage.element_id}`);
      }
      if (
        coverage.classification === "adjacent" &&
        !messageBodySentences(message).some(
          (sentence) =>
            /\b(?:workflow|automation|pipeline)\b/i.test(sentence) &&
            /\b(?:not|rather than|instead of)\b[^.!?]{0,80}\b(?:agentic|multi-agent|autonomous agent)\b/i.test(
              sentence
            )
        )
      ) {
        errors.push(`adjacent material difference is not explicit: ${coverage.element_id}`);
      }
    } else if (coverage.element_kind === "tools_integrations") {
      const proofLabelSet = new Set(proofLabels.map((label) => label.toLowerCase()));
      if (
        signals.filter(
          (signal) =>
            !proofLabelSet.has(signal.toLowerCase()) && hasSignal(signal)
        ).length < 2
      ) {
        errors.push(`mandatory tools or integrations are missing: ${coverage.element_id}`);
      }
    } else if (
      ["ai_project", "project_summary"].includes(coverage.element_kind) &&
      !proofLabels.some(hasSignal)
    ) {
      errors.push(`mandatory concrete project is missing: ${coverage.element_id}`);
    } else if (coverage.element_kind === "production_status") {
      if (coverage.classification === "exact" && !/\bproduction\b/i.test(normalized)) {
        errors.push(`mandatory production evidence is missing: ${coverage.element_id}`);
      }
      if (
        coverage.classification === "partial" &&
        !/\bpre-launch\b/i.test(normalized)
      ) {
        errors.push(`partial production status is not explicit: ${coverage.element_id}`);
      }
    } else if (coverage.element_kind === "domain") {
      const requested = coverage.element.replace(/\s+domain$/i, "");
      if (!hasSignal(requested)) {
        errors.push(`mandatory domain element is missing: ${coverage.element_id}`);
      }
      if (
        coverage.classification === "adjacent" &&
        !messageBodySentences(message).some((sentence) => {
          const actualDomains = [...DOMAIN_PATTERNS]
            .filter(
              ([domain, pattern]) => domain !== requested &&
                coverageProofRecords(coverage, pack, profile).some((proof) =>
                  pattern.test(proof.text)
                )
            )
            .map(([domain]) => domain);
          return (
            includesAlias(sentence, [requested.toLowerCase()]) &&
            actualDomains.some((domain) =>
              includesAlias(sentence, [domain.toLowerCase()])
            ) &&
            ADJACENT_QUALIFIER_PATTERN.test(sentence)
          );
        })
      ) {
        errors.push(`adjacent material difference is not explicit: ${coverage.element_id}`);
      }
    } else if (
      coverage.element_kind === "incident_resolution" &&
      !/\b(?:resolved|fixed|diagnosed|restored|reduced)\b/i.test(normalized)
    ) {
      errors.push(`mandatory incident example is missing: ${coverage.element_id}`);
    }
  }
  return errors;
}

function claimGroundingErrors(message, pack, profile) {
  const errors = [];
  if (!pack) return errors;
  if (!Array.isArray(pack?.selected_proofs) || pack.selected_proofs.length === 0) {
    return ["candidate claims require at least one selected approved proof"];
  }
  const selectedText = (pack?.selected_proofs ?? [])
    .map((proof) => proof.evidence)
    .join(" ");
  const proofModels = (pack?.selected_proofs ?? []).map((proof) => ({
    reference: proof.reference,
    evidence: proof.evidence,
    models: proofGroundingModels(proof, profile)
  }));
  for (const sentence of messageBodySentences(message)) {
    if (NON_MATERIAL_CONVERSATION_PATTERN.test(sentence)) {
      continue;
    }
    const allowedAdjacentRoots = adjacentRootsAllowedInSentence(sentence, pack);
    for (const clause of claimClauses(sentence)) {
      const tokens = [...proofTokens(clause)];
      const matchingProof = proofModels.find((proof) =>
        numericAssociationsGrounded(clause, proof.evidence) &&
        proof.models.some(
          (model) =>
            groundingModelEligible(model, clause) &&
            tokens.every((token) =>
              tokenIsGrounded(token, model.roots, allowedAdjacentRoots)
            )
        )
      );
      if (!matchingProof) {
        errors.push(
          `candidate claim contains unsupported terms or a cross-proof association: ${clause.slice(
            0,
            120
          )}`
        );
      }
    }
  }

  const selectedLower = selectedText.toLowerCase();
  for (const match of normalizeText(message).matchAll(MATERIAL_CLAIM_PATTERN)) {
    if (!selectedLower.includes(match[0].toLowerCase())) {
      errors.push(`unsupported material claim: ${match[0]}`);
    }
  }
  MATERIAL_CLAIM_PATTERN.lastIndex = 0;

  for (const match of normalizeText(message).matchAll(UNSUPPORTED_FREQUENCY_PATTERN)) {
    if (!selectedLower.includes(match[0].toLowerCase())) {
      errors.push(`unsupported frequency or universality claim: ${match[0]}`);
    }
  }
  UNSUPPORTED_FREQUENCY_PATTERN.lastIndex = 0;

  for (const provider of proofProviders(message)) {
    if (proofProviders(selectedText).some((value) => value.toLowerCase() === provider.toLowerCase())) {
      continue;
    }
    const adjacent = (pack?.requirement_coverage ?? []).some(
      (coverage) =>
        coverage.classification === "adjacent" &&
        coverage.element.toLowerCase().includes(provider.toLowerCase()) &&
        ADJACENT_QUALIFIER_PATTERN.test(normalizeText(message))
    );
    if (!adjacent) errors.push(`unsupported provider or tool claim: ${provider}`);
  }
  for (const [domain, pattern] of DOMAIN_PATTERNS) {
    if (pattern.test(message) && !pattern.test(selectedText)) {
      const adjacent = (pack?.requirement_coverage ?? []).some(
        (coverage) =>
          coverage.classification === "adjacent" &&
          coverage.element.toLowerCase().includes(domain) &&
          ADJACENT_QUALIFIER_PATTERN.test(normalizeText(message))
      );
      if (!adjacent) errors.push(`unsupported domain claim: ${domain}`);
    }
  }
  return errors;
}

function hasGroundedCandidateContent(message, pack, profile) {
  const canonicalProofs = new Map(
    proofCandidates(profile).map((proof) => [proof.reference, proof])
  );
  const evidence = (pack?.selected_proof_refs ?? [])
    .map((reference) => canonicalProofs.get(reference))
    .filter(Boolean)
    .map((proof) => `${proof.label || ""} ${proof.text || ""}`)
    .join(" ");
  const evidenceRoots = groundingRootSet(evidence);
  return messageBodySentences(message).some((sentence) => {
    if (!CANDIDATE_OWNERSHIP_PATTERN.test(sentence)) return false;
    const tokens = [...proofTokens(sentence)];
    const overlap = tokens.filter((token) =>
      [...groundingRoots(token)].some((root) => evidenceRoots.has(root))
    ).length;
    return tokens.length >= 4 && overlap >= 3;
  });
}

function validateGeneratedMessage(message, { job, profile, policy, pack }) {
  const errors = [];
  const rawMessage = String(message || "");
  const output = normalizeText(rawMessage.slice(0, 100000));
  if (rawMessage.length > 100000) errors.push("message exceeds the processing limit");
  const firstLine =
    String(message || "")
      .split(/\r?\n/)
      .map((line) => normalizeText(line))
      .find(Boolean) ?? "";
  if (!output) return { valid: false, errors: ["message is empty"] };

  const nonEmptyLines = rawMessage
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => normalizeText(line))
    .filter(Boolean);
  const hasFormatOverride = (pack?.message_plan?.requirements ?? []).some(
    (requirement) => requirement.required && requirement.format_value
  );
  if (
    pack?.message_plan &&
    !hasFormatOverride &&
    !/^(?:hi|hello|dear)\b.*[,!]$/i.test(nonEmptyLines[1] ?? "")
  ) {
    errors.push("message must include a greeting after the subject line");
  }
  if (
    pack?.message_plan &&
    !nonEmptyLines.includes(
      "I would welcome a conversation about how my experience fits this role."
    )
  ) {
    errors.push("message must include the required truthful closing");
  }

  if (/\*\*|__|^\s*```|^\s{0,3}#{1,6}\s+/m.test(rawMessage)) {
    errors.push("Markdown formatting is not allowed");
  }
  if (/^\s*(?:Question|Answer)\s*:/im.test(rawMessage)) {
    errors.push("Question/Answer labels are not allowed");
  }

  const words = output.split(/\s+/).filter(Boolean);
  if (words.length > policy.max_body_words) {
    errors.push(`message exceeds ${policy.max_body_words} words`);
  }

  const approvedProjects = new Set(policy.approved_project_ids);
  const approvedUrls = new Set([
    ...policy.approved_candidate_url_keys.map((key) => profile.candidate.links[key]),
    ...profile.projects.filter((project) => approvedProjects.has(project.id)).map((project) => project.url)
  ]);
  for (const url of extractUrls(output)) {
    if (!approvedUrls.has(url)) errors.push(`unapproved URL: ${url}`);
  }

  for (const technology of UNSUPPORTED_TECHNOLOGIES) {
    if (
      includesAlias(output, [technology.toLowerCase()]) &&
      !approvedSkillNames(profile).some((skill) => skill.toLowerCase() === technology.toLowerCase())
    ) {
      errors.push(`unsupported skill: ${technology}`);
    }
  }

  const hasScheduleCommitment = SCHEDULE_COMMITMENT_PATTERNS.some((pattern) => {
    pattern.lastIndex = 0;
    return pattern.test(output);
  });
  if (hasScheduleCommitment) {
    errors.push("unsupported availability or schedule commitment");
  }
  if (SALARY_COMMITMENT_PATTERN.test(output)) {
    errors.push("unsupported salary commitment");
  }
  SALARY_COMMITMENT_PATTERN.lastIndex = 0;
  if (START_DATE_COMMITMENT_PATTERN.test(output)) {
    errors.push("unsupported start-date commitment");
  }
  START_DATE_COMMITMENT_PATTERN.lastIndex = 0;

  const authoritativeNumericEvidence = profileEvidenceText(profile);
  const approvedNumbers = new Set([
    ...numericTokens(authoritativeNumericEvidence),
    ...numberWordTokens(authoritativeNumericEvidence)
  ]);
  const numericClaimText = removeMatches(
    output,
    SCHEDULE_COMMITMENT_PATTERNS
  );
  for (const token of [
    ...numericTokens(numericClaimText),
    ...numberWordTokens(numericClaimText)
  ]) {
    if (!approvedNumbers.has(token)) errors.push(`unsupported numeric claim: ${token}`);
  }

  const messageWithoutUrls = numericClaimText.replace(
    /https?:\/\/\S+/gi,
    ""
  );
  if (/(?:\+?\d[\s().-]*){7,}/.test(messageWithoutUrls)) errors.push("phone numbers are not approved");

  for (const phrase of policy.banned_phrases ?? []) {
    if (output.toLowerCase().includes(phrase.toLowerCase())) {
      errors.push(`banned phrase: ${phrase}`);
    }
  }
  if (COMPLETION_CLAIM_PATTERN.test(output)) {
    errors.push("unsupported completion or submission claim");
  }
  COMPLETION_CLAIM_PATTERN.lastIndex = 0;
  if (INTERNAL_CONTEXT_PATTERN.test(output)) {
    errors.push("internal application context is not allowed");
  }
  INTERNAL_CONTEXT_PATTERN.lastIndex = 0;
  if (!(pack?.requirement_coverage?.length > 0)) {
    errors.push(...screeningAnswerErrors(rawMessage, pack));
  }
  errors.push(...requirementCoverageErrors(rawMessage, pack, profile));
  errors.push(...claimGroundingErrors(rawMessage, pack, profile));
  if (
    (pack?.selected_proofs?.length ?? 0) > 0 &&
    !hasGroundedCandidateContent(rawMessage, pack, profile)
  ) {
    errors.push("message lacks evidence-grounded candidate content");
  }
  if (pack?.application_pack_status === "ready" && pack?.message_plan?.subject_line) {
    if (firstLine !== normalizeText(pack.message_plan.subject_line)) {
      errors.push(
        `required subject value is missing or does not match the complete first line: ${pack.message_plan.subject_line}`
      );
    }
  } else {
    for (const instruction of pack?.application_instructions ?? []) {
      if (
        instruction.type === "subject" &&
        pack.application_pack_status === "ready" &&
        instruction.required &&
        instruction.value &&
        !firstLine
          .toLowerCase()
          .includes(instruction.value.toLowerCase())
      ) {
        errors.push(`required subject value is missing: ${instruction.value}`);
      }
    }
  }
  const uniqueErrors = [...new Set(errors)];
  return {
    valid: uniqueErrors.length === 0,
    errors: uniqueErrors
  };
}

function applyNonReadyApplicationPack(
  record,
  pack,
  profile,
  packPolicy,
  now = new Date().toISOString()
) {
  const packErrors = validateApplicationPack(pack, profile, packPolicy);
  if (
    !["review_required", "blocked"].includes(
      pack?.application_pack_status
    ) ||
    packErrors.length > 0
  ) {
    throw new Error(
      `Invalid non-ready application pack: ${[
        ...(!["review_required", "blocked"].includes(
          pack?.application_pack_status
        )
          ? ["application_pack_status must require review or be blocked"]
          : []),
        ...packErrors
      ].join("; ")}`
    );
  }
  const warningSummary = (pack.application_warnings ?? [])
    .map((warning) => warning.summary)
    .filter(Boolean)
    .join("; ");
  return releaseClaim(
    {
      ...record,
      application_instructions: pack.application_instructions,
      screening_questions: pack.screening_questions,
      requirement_coverage: pack.requirement_coverage,
      application_message_plan: [pack.message_plan],
      selected_proof_refs: pack.selected_proof_refs,
      application_warnings: pack.application_warnings,
      application_pack_status: pack.application_pack_status,
      application_pack_version: packPolicy.pack_version,
      application_pack_profile_version: profile.profile_version,
      application_pack_policy_version: packPolicy.policy_version,
      coverage_contract_version: pack.coverage_contract_version,
      message_plan_version: pack.message_plan.version,
      application_pack_generated_at: pack.application_pack_generated_at || now,
      pipeline_status: "review_required",
      error_category: "application_pack_not_ready",
      error_summary: sanitizeError(
        warningSummary || "Application pack requires manual review."
      ),
      failed_stage: "generation",
      next_retry_at: "",
      manual_action: "",
      updated_at: now
    },
    record.processing_token,
    now
  );
}

function applyGeneratedApplicationPack(
  record,
  pack,
  message,
  profile,
  applicationPolicy,
  packPolicy,
  now = new Date().toISOString()
) {
  const cleanedMessage = cleanGeneratedMessage(message);
  const packErrors = validateApplicationPack(pack, profile, packPolicy);
  const messageValidation = validateGeneratedMessage(cleanedMessage, {
    job: record,
    profile,
    policy: applicationPolicy,
    pack
  });
  if (
    pack.application_pack_status !== "ready" ||
    packErrors.length > 0 ||
    !messageValidation.valid
  ) {
    throw new Error(
      `Invalid application pack: ${[
        ...(pack.application_pack_status === "ready"
          ? []
          : ["application_pack_status must be ready"]),
        ...packErrors,
        ...messageValidation.errors
      ].join("; ")}`
    );
  }
  return releaseClaim(
    {
      ...record,
      application_instructions: pack.application_instructions,
      screening_questions: pack.screening_questions,
      requirement_coverage: pack.requirement_coverage,
      application_message_plan: [pack.message_plan],
      selected_proof_refs: pack.selected_proof_refs,
      application_warnings: pack.application_warnings,
      application_pack_status: pack.application_pack_status,
      application_pack_version: packPolicy.pack_version,
      application_pack_profile_version: profile.profile_version,
      application_pack_policy_version: packPolicy.policy_version,
      coverage_contract_version: pack.coverage_contract_version,
      message_plan_version: pack.message_plan.version,
      application_pack_generated_at: now,
      pipeline_status: "ready",
      generated_message: cleanedMessage,
      message_profile_version: profile.profile_version,
      message_policy_version: applicationPolicy.policy_version,
      message_validation_status: "valid",
      generated_at: now,
      error_category: "",
      error_summary: "",
      failed_stage: "",
      next_retry_at: "",
      manual_action: "",
      updated_at: now
    },
    record.processing_token,
    now
  );
}

function applyGeneratedMessage(
  record,
  message,
  profile,
  now = new Date().toISOString()
) {
  const cleanedMessage = cleanGeneratedMessage(message);
  return releaseClaim(
    {
      ...record,
      pipeline_status: "ready",
      generated_message: cleanedMessage,
      message_profile_version: profile.profile_version,
      message_validation_status: "valid",
      generated_at: now,
      error_category: "",
      error_summary: "",
      failed_stage: "",
      next_retry_at: "",
      manual_action: "",
      updated_at: now
    },
    record.processing_token,
    now
  );
}


function hydratedPersistedPack(record, profile) {
  const planEntries = Array.isArray(record?.application_message_plan)
    ? record.application_message_plan
    : [];
  const messagePlan =
    planEntries.length === 1 &&
    planEntries[0] &&
    typeof planEntries[0] === "object" &&
    !Array.isArray(planEntries[0])
      ? planEntries[0]
      : null;
  const selectedProofs = (record?.selected_proof_refs ?? [])
    .map((reference) => {
      const [kind, id] = String(reference).split(":");
      const entry =
        kind === "projects"
          ? profile.projects?.find((project) => project.id === id)
          : kind === "experience"
            ? profile.experience?.find((experience) => experience.id === id)
            : null;
      if (!entry) return null;
      return {
        reference,
        label:
          kind === "projects"
            ? entry.name
            : `${entry.title} — ${entry.organization}`,
        evidence: profileEvidenceText(entry)
      };
    })
    .filter(Boolean);
  return {
    ...record,
    message_plan: messagePlan,
    selected_proofs: selectedProofs
  };
}

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, stableValue(value[key])])
    );
  }
  return value;
}

function sameContractValue(left, right) {
  return JSON.stringify(stableValue(left)) === JSON.stringify(stableValue(right));
}

function evaluatePersistedMessageSafety(
  record,
  { profile, applicationPolicy, packPolicy } = {}
) {
  if (!profile || !applicationPolicy || !packPolicy) {
    return {
      safe: false,
      reasons: ["message_safety_configuration_missing"]
    };
  }

  const reasons = [];
  if (record?.pipeline_status !== "ready_to_apply") {
    reasons.push("message_owner_not_to_apply");
  }
  if (record?.prep_status !== "message_ready") {
    reasons.push("preparation_not_message_ready");
  }
  const messageProfileVersion = String(
    record?.message_profile_version || ""
  ).trim();
  if (messageProfileVersion === "legacy/unknown") {
    reasons.push("message_profile_legacy");
  } else if (!messageProfileVersion) {
    reasons.push("message_profile_missing");
  } else if (messageProfileVersion !== profile.profile_version) {
    reasons.push("message_profile_mismatch");
  }

  const messagePolicyVersion = String(
    record?.message_policy_version || ""
  ).trim();
  if (!messagePolicyVersion) {
    reasons.push("message_policy_missing");
  } else if (messagePolicyVersion !== applicationPolicy.policy_version) {
    reasons.push("message_policy_mismatch");
  }
  if (record?.message_validation_status !== "valid") {
    reasons.push("message_validation_not_valid");
  }
  if (!String(record?.generated_message || "").trim()) {
    reasons.push("message_missing");
  }

  if (record?.application_pack_status !== "ready") {
    reasons.push("pack_status_not_ready");
  }
  if (record?.application_pack_version !== packPolicy.pack_version) {
    reasons.push("pack_version_mismatch");
  }
  if (
    record?.application_pack_profile_version !== profile.profile_version
  ) {
    reasons.push("pack_profile_mismatch");
  }
  if (
    record?.application_pack_policy_version !== packPolicy.policy_version
  ) {
    reasons.push("pack_policy_mismatch");
  }
  if (record?.coverage_contract_version !== packPolicy.coverage_contract_version) {
    reasons.push("coverage_version_mismatch");
  }
  if (record?.message_plan_version !== packPolicy.message_plan_version) {
    reasons.push("message_plan_version_mismatch");
  }
  if (!Array.isArray(record?.requirement_coverage)) {
    reasons.push("coverage_missing");
  }
  if (
    !Array.isArray(record?.application_message_plan) ||
    record.application_message_plan.length !== 1
  ) {
    reasons.push("message_plan_missing");
  }

  let canonicalPack = null;
  try {
    canonicalPack = buildApplicationPack(
      { ...record, user_action: "" },
      profile,
      applicationPolicy,
      packPolicy,
      record?.application_pack_generated_at || new Date(0).toISOString()
    );
  } catch {
    reasons.push("pack_recomputation_failed");
  }
  if (canonicalPack) {
    const canonicalFields = [
      ["application_instructions", canonicalPack.application_instructions],
      ["screening_questions", canonicalPack.screening_questions],
      ["requirement_coverage", canonicalPack.requirement_coverage],
      ["application_message_plan", [canonicalPack.message_plan]],
      ["selected_proof_refs", canonicalPack.selected_proof_refs],
      ["application_warnings", canonicalPack.application_warnings],
      ["application_pack_status", canonicalPack.application_pack_status],
      ["application_pack_version", canonicalPack.application_pack_version],
      [
        "application_pack_profile_version",
        canonicalPack.application_pack_profile_version
      ],
      [
        "application_pack_policy_version",
        canonicalPack.application_pack_policy_version
      ],
      ["coverage_contract_version", canonicalPack.coverage_contract_version],
      ["message_plan_version", canonicalPack.message_plan.version]
    ];
    if (
      canonicalFields.some(([field, expected]) =>
        !sameContractValue(record?.[field], expected)
      )
    ) {
      reasons.push("pack_not_canonical");
    }
  }

  const hydratedPack = hydratedPersistedPack(record, profile);
  const packErrors = validateApplicationPack(hydratedPack, profile, packPolicy);
  if (packErrors.length > 0) reasons.push("pack_invalid");
  const messageValidation = validateGeneratedMessage(
    record?.generated_message,
    {
      job: record,
      profile,
      policy: applicationPolicy,
      pack: hydratedPack
    }
  );
  if (!messageValidation.valid) reasons.push("message_content_invalid");

  return {
    safe: reasons.length === 0,
    reasons
  };
}


function normalizeClaimKey(value) {
  return String(value || "")
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
}

function validTimestamp(value) {
  return Number.isFinite(Date.parse(value || ""));
}

function createSystemClaim({
  stage,
  canonicalJobId,
  scope = "",
  executionId,
  now,
  leaseMs
}) {
  const normalizedStage = normalizeClaimKey(stage);
  const normalizedId = normalizeClaimKey(canonicalJobId);
  const normalizedScope = normalizeClaimKey(scope);
  const nowMs = Date.parse(now);
  if (
    !normalizedStage ||
    !normalizedId ||
    !String(executionId || "").trim() ||
    !Number.isFinite(nowMs) ||
    !Number.isInteger(leaseMs) ||
    leaseMs < 1
  ) {
    throw new Error(
      "System claim requires stage, identity, execution, timestamp, and lease"
    );
  }
  const claimKey = [normalizedStage, normalizedId, normalizedScope]
    .filter(Boolean)
    .join(":");
  return {
    claim_key: claimKey,
    canonical_job_id: canonicalJobId,
    stage: normalizedStage,
    token: `${executionId}:${claimKey}`,
    created_at: now,
    expires_at: new Date(nowMs + leaseMs).toISOString()
  };
}

function selectWinningSystemClaims(
  proposedClaims,
  persistedClaims,
  now = new Date().toISOString()
) {
  if (!Array.isArray(proposedClaims) || !Array.isArray(persistedClaims)) {
    throw new Error("System claim collections must be arrays");
  }
  const nowMs = Date.parse(now);
  if (!Number.isFinite(nowMs)) throw new Error("System claim time is invalid");
  const winners = new Map();
  for (const claim of persistedClaims) {
    const key = normalizeClaimKey(claim?.claim_key);
    const rowNumber = Number(claim?.row_number);
    if (
      !key ||
      !String(claim?.token || "").trim() ||
      !Number.isInteger(rowNumber) ||
      rowNumber < 2 ||
      !validTimestamp(claim?.expires_at) ||
      Date.parse(claim.expires_at) <= nowMs
    ) {
      continue;
    }
    const current = winners.get(key);
    if (!current || rowNumber < Number(current.row_number)) {
      winners.set(key, claim);
    }
  }
  return proposedClaims.filter((claim) => {
    const winner = winners.get(normalizeClaimKey(claim?.claim_key));
    return winner?.token === claim?.token;
  });
}

function expiredSystemClaimRows(
  persistedClaims,
  now = new Date().toISOString()
) {
  const nowMs = Date.parse(now);
  if (!Number.isFinite(nowMs)) throw new Error("System claim time is invalid");
  return (Array.isArray(persistedClaims) ? persistedClaims : [])
    .filter((claim) => {
      const rowNumber = Number(claim?.row_number);
      return (
        Number.isInteger(rowNumber) &&
        rowNumber >= 2 &&
        validTimestamp(claim?.expires_at) &&
        Date.parse(claim.expires_at) <= nowMs
      );
    })
    .sort((left, right) => Number(right.row_number) - Number(left.row_number))
    .map((claim) => ({ row_number: Number(claim.row_number) }));
}


function identityKey(value) {
  return String(value || "")
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
}

function sanitize(value, maximum = 240) {
  return String(value || "")
    .replace(/https?:\/\/\S+/gi, "[url]")
    .replace(/[\r\n\t]+/g, " ")
    .trim()
    .slice(0, maximum);
}

function permanentSourceUnavailable(record) {
  if (
    record?.source_availability === "unavailable" ||
    record?.error_category === "source_unavailable"
  ) {
    return true;
  }
  if (record?.pipeline_status !== "error") return false;
  const summary = String(record.error_summary || "");
  return (
    /^\s*(?:404|410)(?:\b|\s*[-:])/u.test(summary) ||
    /\b(?:http|status(?:\s+code)?)\s*[:=-]?\s*(?:404|410)\b/iu.test(
      summary
    )
  );
}

function indexStore(rows, name) {
  if (!Array.isArray(rows)) throw new Error(`${name} rows must be an array`);
  const index = new Map();
  for (const row of rows) {
    const key = identityKey(row?.canonical_job_id);
    if (!key) throw new Error(`${name} contains a row with invalid identity`);
    if (index.has(key)) {
      throw new Error(`${name} contains an ambiguous duplicate identity`);
    }
    index.set(key, row);
  }
  return index;
}

function destinationConflict(actual, destination, reason) {
  if (destination === "To Review" && actual.review_decision) return true;
  if (
    destination === "To Apply" &&
    reason === "review_proceeded" &&
    (actual.pipeline_status !== "ready_to_apply" ||
      actual.review_decision !== "proceed")
  ) return true;
  if (
    destination === "Applied Jobs" &&
    (actual.archive_reason || actual.archived_at)
  ) {
    return true;
  }
  if (
    destination === "Archive" &&
    ((actual.archive_reason && actual.archive_reason !== reason) ||
      actual.applied_at)
  ) {
    return true;
  }
  if (
    ["Scraped Jobs", "To Review", "To Apply"].includes(destination) &&
    (actual.applied_at || actual.archived_at || actual.archive_reason)
  ) {
    return true;
  }
  return false;
}

function validExistingDestination(source, actual, destination, reason, schema) {
  if (!actual || destinationConflict(actual, destination, reason)) return false;
  if (validateRecordStoreContract(actual, destination, schema).length > 0) {
    return false;
  }
  if (actual.state_guard !== stateGuard(actual)) return false;
  if (destination === "To Review") {
    const expectedCase = reviewCaseId(source);
    if (
      actual.review_case_id !== expectedCase ||
      actual.review_case_version !== "review-case-v1" ||
      actual.review_decision ||
      actual.review_decided_at
    ) return false;
  }
  if (destination === "To Apply" && reason === "review_proceeded") {
    const expectedCase = source.review_case_id || reviewCaseId(source);
    if (
      actual.pipeline_status !== "ready_to_apply" ||
      actual.user_action ||
      actual.review_case_id !== expectedCase ||
      actual.review_case_version !== "review-case-v1" ||
      actual.review_decision !== "proceed" ||
      !Number.isFinite(Date.parse(actual.review_decided_at || "")) ||
      actual.review_approved_at !== actual.review_decided_at ||
      actual.review_approval_guard !== applicationReviewGuard(source) ||
      !Number.isInteger(actual.preparation_version) ||
      actual.preparation_version < 1 ||
      actual.preparation_input_guard !== preparationInputGuard(actual) ||
      !Number.isFinite(Date.parse(actual.preparation_updated_at || ""))
    ) return false;
    if (actual.prep_status !== "pending") {
      const immutableSourceFields = [
        "source",
        "source_job_id",
        "canonical_job_id",
        "canonical_url",
        "job_title",
        "company",
        "job_description",
        "salary_text",
        "posted_at",
        "discovered_at",
        "created_at"
      ];
      return Boolean(
        actual.record_version > source.record_version + 1 &&
          immutableSourceFields.every(
            (field) =>
              JSON.stringify(actual[field] ?? "") ===
              JSON.stringify(source[field] ?? "")
          )
      );
    }
  }
  if (
    destination === "Applied Jobs" &&
    !Number.isFinite(Date.parse(actual.applied_at || ""))
  ) {
    return false;
  }
  if (
    destination === "Archive" &&
    (!Number.isFinite(Date.parse(actual.archived_at || "")) ||
      actual.archive_reason !== reason)
  ) {
    return false;
  }
  if (
    destination === "Archive" &&
    reason === "review_rejected" &&
    (actual.review_case_id !== (source.review_case_id || reviewCaseId(source)) ||
      actual.review_case_version !== "review-case-v1" ||
      actual.review_decision !== "reject" ||
      !Number.isFinite(Date.parse(actual.review_decided_at || "")))
  ) return false;
  if (
    destination === "Archive" &&
    reason === "source_unavailable" &&
    (actual.pipeline_status !== "unavailable" ||
      actual.source_availability !== "unavailable" ||
      actual.next_retry_at)
  ) {
    return false;
  }
  const destinationOwned = new Set([
    "row_number",
    "record_version",
    "state_guard",
    "user_action",
    "processing_stage",
    "processing_token",
    "processing_started_at",
    "alert_claim_token",
    "alert_status",
    "alert_idempotency_key",
    "alert_attempt_count",
    "alert_last_attempt_at",
    "alert_next_retry_at",
    "alert_sent_at",
    "alert_provider_reference",
    "alert_error_category",
    "alert_error_summary",
    "applied_at",
    "archived_at",
    "archive_reason",
    "outcome",
    "outcome_recorded_value",
    "outcome_at",
    "notes",
    "updated_at"
  ]);
  if (destination === "To Review") {
    for (const field of [
      "review_case_id",
      "review_case_version",
      "review_decision",
      "review_decided_at",
      "review_approved_at",
      "review_approval_note",
      "review_approval_guard"
    ]) destinationOwned.add(field);
  }
  if (destination === "To Apply" && reason === "review_proceeded") {
    for (const field of [
      "pipeline_status",
      "review_case_id",
      "review_case_version",
      "review_decision",
      "review_decided_at",
      "review_approved_at",
      "review_approval_note",
      "review_approval_guard",
      "prep_status",
      "preparation_version",
      "preparation_input_guard",
      "preparation_updated_at",
      "next_retry_at",
      "error_category",
      "error_summary"
    ]) destinationOwned.add(field);
  }
  if (destination === "Archive" && reason === "source_unavailable") {
    destinationOwned.add("pipeline_status");
    destinationOwned.add("source_availability");
    destinationOwned.add("next_retry_at");
  }
  if (destination === "Archive" && reason === "review_rejected") {
    for (const field of [
      "review_case_id",
      "review_case_version",
      "review_decision",
      "review_decided_at"
    ]) destinationOwned.add(field);
  }
  return schema.fields.every((field) => {
    if (destinationOwned.has(field)) return true;
    const sourceValue = source[field];
    if (
      sourceValue === "" ||
      sourceValue === undefined ||
      sourceValue === null
    ) {
      return true;
    }
    return JSON.stringify(actual[field]) === JSON.stringify(sourceValue);
  });
}

function destinationRecord(source, destination, reason, now, existing) {
  const record = {
    ...source,
    row_number: undefined,
    user_action: existing?.user_action || "",
    processing_stage: "",
    processing_token: "",
    processing_started_at: "",
    alert_claim_token: "",
    record_version:
      Math.max(
        Number(source.record_version || 1),
        Number(existing?.record_version || 0)
      ) + 1,
    updated_at: now
  };
  if (destination === "Applied Jobs") {
    record.applied_at = existing?.applied_at || source.applied_at || now;
    record.archived_at = "";
    record.archive_reason = "";
    record.notes = existing ? existing.notes || "" : source.notes || "";
    record.outcome = existing ? existing.outcome || "" : source.outcome || "";
    record.outcome_recorded_value = existing
      ? existing.outcome_recorded_value || ""
      : record.outcome;
    record.outcome_at = existing
      ? existing.outcome_at || ""
      : source.outcome_at || "";
  } else if (destination === "Archive") {
    record.archived_at = existing?.archived_at || source.archived_at || now;
    record.archive_reason = reason;
    record.applied_at = "";
    record.notes = existing ? existing.notes || "" : source.notes || "";
    if (reason === "source_unavailable") {
      record.pipeline_status = "unavailable";
      record.source_availability = "unavailable";
      record.next_retry_at = "";
    }
    if (reason === "review_rejected") {
      record.review_case_id = source.review_case_id || reviewCaseId(source);
      record.review_case_version = "review-case-v1";
      record.review_decision = "reject";
      record.review_decided_at = existing?.review_decided_at || now;
    }
  } else {
    record.applied_at = "";
    record.archived_at = "";
    record.archive_reason = "";
    record.notes = existing ? existing.notes || "" : source.notes || "";
    if (destination === "To Review") {
      record.review_case_id = reviewCaseId(source);
      record.review_case_version = "review-case-v1";
      record.review_decision = "";
      record.review_decided_at = "";
      record.review_approved_at = "";
      record.review_approval_note = "";
      record.review_approval_guard = "";
    }
    if (destination === "To Apply" && reason === "review_proceeded") {
      record.pipeline_status = "ready_to_apply";
      record.review_case_id = source.review_case_id || reviewCaseId(source);
      record.review_case_version = "review-case-v1";
      record.review_decision = "proceed";
      record.review_decided_at = existing?.review_decided_at || now;
      record.review_approved_at = record.review_decided_at;
      record.review_approval_note = sanitize(
        existing?.review_approval_note ||
          source.review_approval_note ||
          source.notes,
        1000
      );
      record.review_approval_guard = applicationReviewGuard(source);
      record.prep_status = "pending";
      record.preparation_version = Math.max(
        1,
        Number(source.preparation_version || 0) + 1,
        Number(existing?.preparation_version || 0)
      );
      record.preparation_updated_at =
        existing?.preparation_updated_at || now;
      record.preparation_input_guard = preparationInputGuard(record);
      record.next_retry_at = "";
      record.error_category = "";
      record.error_summary = "";
    }
  }
  if (existing) {
    for (const field of [
      "user_action",
      "notes",
      "alert_status",
      "alert_idempotency_key",
      "alert_claim_token",
      "alert_attempt_count",
      "alert_last_attempt_at",
      "alert_next_retry_at",
      "alert_sent_at",
      "alert_provider_reference",
      "alert_error_category",
      "alert_error_summary",
      "outcome",
      "outcome_recorded_value",
      "outcome_at"
    ]) {
      if (existing[field] !== undefined && existing[field] !== null) {
        record[field] = existing[field];
      }
    }
  }
  if (["user_applied", "user_skip"].includes(reason)) {
    // An operator terminal action wins over an in-flight or retryable Slack
    // delivery. The destination must never retain `sending` after movement
    // clears the source claim token, otherwise the record fails its own store
    // contract and becomes stranded in To Apply.
    if (["pending", "sending", "retryable_failure"].includes(record.alert_status)) {
      record.alert_status = "suppressed";
      record.alert_error_category = "operator_terminal_action";
      record.alert_error_summary =
        "Slack alert cancelled because the operator completed a terminal queue action.";
    }
    record.alert_claim_token = "";
    record.alert_next_retry_at = "";
  }
  record.state_guard = stateGuard(record);
  return record;
}

function classifyQueueRow(sourceSheet, record, schema) {
  if (
    sourceSheet === "Scraped Jobs" &&
    isGuardedLegacyReviewAction(record, sourceSheet, schema)
  ) {
    return record.user_action === "Proceed"
      ? { destination: "To Apply", reason: "review_proceeded" }
      : { destination: "Archive", reason: "review_rejected" };
  }
  if (
    sourceSheet === "Scraped Jobs" &&
    !record.user_action &&
    permanentSourceUnavailable(record)
  ) {
    return { destination: "Archive", reason: "source_unavailable" };
  }
  if (
    sourceSheet === "Scraped Jobs" &&
    record.pipeline_status === "review_needed" &&
    !record.user_action
  ) {
    const currentCase = reviewCaseId(record);
    if (
      record.review_decision === "proceed" &&
      record.review_case_id === currentCase
    ) {
      return {
        suppressed: true,
        reason: "resolved_review_case_repeated",
        summary:
          "The resolved review case cannot be reopened from unchanged preparation facts"
      };
    }
    if (
      record.review_decision &&
      (!record.review_case_id || record.review_case_id === currentCase)
    ) {
      return {
        suppressed: true,
        reason: "review_reopen_missing_new_case",
        summary:
          "A resolved decision requires a materially different review case before reopening"
      };
    }
    if (
      record.review_decision &&
      (!String(record.decision_reason || "").trim() ||
        !String(record.required_input || "").trim())
    ) {
      return {
        suppressed: true,
        reason: "review_reopen_missing_reason",
        summary:
          "A materially new review case requires an explicit bounded reason and required input"
      };
    }
    return { destination: "To Review", reason: "review_needed" };
  }
  if (
    sourceSheet === "Scraped Jobs" &&
    record.pipeline_status === "ready_to_apply" &&
    !record.user_action
  ) {
    return { destination: "To Apply", reason: "ready_to_apply" };
  }
  if (
    sourceSheet === "Scraped Jobs" &&
    record.pipeline_status === "skip" &&
    !record.user_action
  ) {
    return { destination: "Archive", reason: "automatic_skip" };
  }
  if (
    sourceSheet === "To Apply" &&
    record.pipeline_status === "ready_to_apply" &&
    record.user_action === "I Applied"
  ) {
    // This action records a manual application that already happened. Message
    // safety still gates outbound Slack alerts, but it must not erase or strand
    // the operator's historical fact after an alert failure or context change.
    return { destination: "Applied Jobs", reason: "user_applied" };
  }
  if (
    sourceSheet === "To Apply" &&
    record.pipeline_status === "ready_to_apply" &&
    record.user_action === "Skip"
  ) {
    return { destination: "Archive", reason: "user_skip" };
  }
  if (
    sourceSheet === "To Review" &&
    record.pipeline_status === "review_needed" &&
    record.user_action === "Reject"
  ) {
    return { destination: "Archive", reason: "review_rejected" };
  }
  if (
    sourceSheet === "To Review" &&
    record.pipeline_status === "review_needed" &&
    record.user_action === "Proceed"
  ) {
    return { destination: "To Apply", reason: "review_proceeded" };
  }
  return null;
}

function planQueueActions(
  stores,
  schema,
  now = new Date().toISOString(),
  messageSafetyContext,
  { movementPerRunCap = Number.POSITIVE_INFINITY } = {}
) {
  const expectedStores = schema?.business_stores ?? [];
  if (
    expectedStores.length !== 5 ||
    expectedStores.some((store) => !Array.isArray(stores?.[store]))
  ) {
    throw new Error(
      "Movement requires Scraped Jobs, To Review, To Apply, Applied Jobs, and Archive rows"
    );
  }
  const indexes = Object.fromEntries(
    expectedStores.map((store) => [store, indexStore(stores[store], store)])
  );
  const canonicalUrlOwners = new Map();
  for (const store of expectedStores) {
    for (const row of stores[store]) {
      const urlKey = identityKey(row?.canonical_url);
      const identity = identityKey(row?.canonical_job_id);
      const previous = canonicalUrlOwners.get(urlKey);
      if (previous && previous.identity !== identity) {
        throw new Error(
          `Movement contains an ambiguous canonical URL in ${previous.store} and ${store}`
        );
      }
      canonicalUrlOwners.set(urlKey, { identity, store });
    }
  }
  const moves = [];
  const rejected = [];
  const candidates = [];
  const sourceOrder = ["Scraped Jobs", "To Review", "To Apply"];
  for (const sourceSheet of sourceOrder) {
    for (const source of stores[sourceSheet]) {
      const contractErrors = validateRecordStoreContract(
        source,
        sourceSheet,
        schema
      );
      if (contractErrors.length > 0) {
        rejected.push({
          canonical_job_id: String(source?.canonical_job_id || ""),
          source_sheet: sourceSheet,
          reason: "invalid_source",
          summary: sanitize(contractErrors.join("; "))
        });
        continue;
      }
      if (!stateGuardMatches(source)) {
        rejected.push({
          canonical_job_id: String(source?.canonical_job_id || ""),
          source_sheet: sourceSheet,
          reason: "invalid_source",
          summary: "Source state guard does not match the current row"
        });
        continue;
      }
      let classification;
      try {
        classification = classifyQueueRow(sourceSheet, source, schema);
      } catch (error) {
        rejected.push({
          canonical_job_id: String(source?.canonical_job_id || ""),
          source_sheet: sourceSheet,
          reason: "unsafe_action",
          summary: sanitize(error?.message || error)
        });
        continue;
      }
      if (classification) {
        if (classification.suppressed) {
          rejected.push({
            canonical_job_id: source.canonical_job_id,
            source_sheet: sourceSheet,
            reason: classification.reason,
            summary: sanitize(classification.summary)
          });
        } else {
          candidates.push({ sourceSheet, source, classification });
        }
      }
    }
  }
  candidates.sort((left, right) => {
    const timestamp = (entry) => {
      const parsed = Date.parse(
        entry.source.updated_at || entry.source.created_at || ""
      );
      return Number.isFinite(parsed) ? parsed : Number.POSITIVE_INFINITY;
    };
    return (
      timestamp(left) - timestamp(right) ||
      sourceOrder.indexOf(left.sourceSheet) -
        sourceOrder.indexOf(right.sourceSheet) ||
      String(left.source.canonical_job_id).localeCompare(
        String(right.source.canonical_job_id)
      )
    );
  });

  for (const { sourceSheet, source, classification } of candidates) {
    const key = identityKey(source.canonical_job_id);
    const existing = indexes[classification.destination].get(key);
    const conflictingStores = expectedStores.filter(
      (store) =>
        store !== sourceSheet &&
        store !== classification.destination &&
        indexes[store].has(key)
    );
    if (conflictingStores.length > 0) {
      rejected.push({
        canonical_job_id: source.canonical_job_id,
        source_sheet: sourceSheet,
        reason: "identity_conflict",
        summary: `Identity already exists in ${conflictingStores.join(", ")}`
      });
      continue;
    }
    if (
      existing &&
      destinationConflict(
        existing,
        classification.destination,
        classification.reason
      )
    ) {
      rejected.push({
        canonical_job_id: source.canonical_job_id,
        source_sheet: sourceSheet,
        reason: "destination_conflict",
        summary: "Existing destination record has conflicting terminal state"
      });
      continue;
    }
    if (moves.length >= movementPerRunCap) {
      rejected.push({
        canonical_job_id: source.canonical_job_id,
        source_sheet: sourceSheet,
        reason: "movement_cap_reached",
        summary: "Movement deferred to a later bounded run"
      });
      continue;
    }
    const existingComplete = validExistingDestination(
      source,
      existing,
      classification.destination,
      classification.reason,
      schema
    );
    const destination = existingComplete
      ? { ...existing }
      : destinationRecord(
          source,
          classification.destination,
          classification.reason,
          now,
          existing
        );
    const destinationErrors = validateRecordStoreContract(
      destination,
      classification.destination,
      schema
    );
    if (destinationErrors.length > 0) {
      rejected.push({
        canonical_job_id: source.canonical_job_id,
        source_sheet: sourceSheet,
        reason: "invalid_destination",
        summary: sanitize(destinationErrors.join("; "))
      });
      continue;
    }
    moves.push({
      canonical_job_id: source.canonical_job_id,
      source_sheet: sourceSheet,
      source_row_number: source.row_number,
      source_state_guard: source.state_guard,
      source_record_version: source.record_version,
      source_status: source.pipeline_status,
      source_action: source.user_action,
      source_notes: source.notes || "",
      destination: classification.destination,
      route_reason: classification.reason,
      claim_scope: `${sourceSheet}:${classification.destination}`,
      archive_reason:
        classification.destination === "Archive"
          ? classification.reason
          : "",
      write_required: !existingComplete,
      recovery_required: Boolean(existing),
      source_record: { ...source },
      destination_record: destination
    });
  }
  return { moves, rejected };
}

function destinationWrites(plans) {
  return {
    scraped_jobs: plans.moves
      .filter(
        (plan) => plan.destination === "Scraped Jobs" && plan.write_required
      )
      .map((plan) => ({ ...plan.destination_record })),
    to_review: plans.moves
      .filter(
        (plan) => plan.destination === "To Review" && plan.write_required
      )
      .map((plan) => ({ ...plan.destination_record })),
    to_apply: plans.moves
      .filter(
        (plan) => plan.destination === "To Apply" && plan.write_required
      )
      .map((plan) => ({ ...plan.destination_record })),
    applied: plans.moves
      .filter(
        (plan) => plan.destination === "Applied Jobs" && plan.write_required
      )
      .map((plan) => ({ ...plan.destination_record })),
    archive: plans.moves
      .filter((plan) => plan.destination === "Archive" && plan.write_required)
      .map((plan) => ({ ...plan.destination_record }))
  };
}

function confirmMoveDeletions(
  plans,
  freshStores,
  schema
) {
  const expectedStores = schema?.business_stores ?? [];
  if (expectedStores.some((store) => !Array.isArray(freshStores?.[store]))) {
    throw new Error("Movement confirmation requires every business store");
  }
  const indexes = Object.fromEntries(
    expectedStores.map((store) => [
      store,
      indexStore(freshStores[store], store)
    ])
  );
  const deletions = [];
  const rejected = [];

  for (const plan of plans.moves) {
    const key = identityKey(plan.canonical_job_id);
    const source = indexes[plan.source_sheet]?.get(key);
    if (!source) {
      // A repeated scheduler run after a successful delete is a no-op.
      continue;
    }
    const sourceUnchanged =
      stateGuardMatches(source) &&
      source.state_guard === plan.source_state_guard &&
      source.record_version === plan.source_record_version &&
      source.pipeline_status === plan.source_status &&
      source.user_action === plan.source_action &&
      String(source.notes || "") === String(plan.source_notes || "");
    if (!sourceUnchanged) {
      rejected.push({
        canonical_job_id: plan.canonical_job_id,
        reason: "stale_source"
      });
      continue;
    }
    const destination = indexes[plan.destination]?.get(key);
    if (
      !validExistingDestination(
        plan.source_record,
        destination,
        plan.destination,
        plan.route_reason,
        schema
      )
    ) {
      rejected.push({
        canonical_job_id: plan.canonical_job_id,
        reason: "destination_unconfirmed"
      });
      continue;
    }
    deletions.push({
      row_number: source.row_number,
      canonical_job_id: source.canonical_job_id,
      source_sheet: plan.source_sheet,
      destination: plan.destination
    });
  }

  deletions.sort(
    (left, right) =>
      left.source_sheet.localeCompare(right.source_sheet) ||
      right.row_number - left.row_number
  );
  return { deletions, rejected };
}

function applyOutcomeUpdate(
  appliedRecord,
  outcome,
  expectedStateGuard,
  schema,
  now = new Date().toISOString()
) {
  if (appliedRecord.state_guard !== expectedStateGuard) {
    throw new Error("Outcome update rejected stale Applied Jobs state");
  }
  if (!schema.outcomes.includes(outcome)) {
    throw new Error("Outcome update contains an unsupported value");
  }
  const updated = {
    ...appliedRecord,
    outcome,
    outcome_recorded_value: outcome,
    outcome_at: outcome ? now : "",
    record_version: appliedRecord.record_version + 1,
    updated_at: now
  };
  updated.state_guard = stateGuard(updated);
  const errors = validateRecordStoreContract(
    updated,
    "Applied Jobs",
    schema
  );
  if (errors.length > 0) {
    throw new Error(`Outcome update failed contract validation: ${sanitize(errors.join("; "))}`);
  }
  return updated;
}

function planOutcomeUpdates(
  appliedRows,
  schema,
  now = new Date().toISOString()
) {
  indexStore(appliedRows, "Applied Jobs");
  const updates = [];
  const rejected = [];
  for (const record of appliedRows) {
    const errors = validateRecordStoreContract(
      record,
      "Applied Jobs",
      schema
    );
    if (errors.length > 0) {
      rejected.push({
        canonical_job_id: String(record?.canonical_job_id || ""),
        reason: "invalid_applied_record",
        summary: sanitize(errors.join("; "))
      });
      continue;
    }
    if (
      String(record.outcome || "") ===
      String(record.outcome_recorded_value || "")
    ) {
      continue;
    }
    updates.push(
      applyOutcomeUpdate(
        record,
        String(record.outcome || ""),
        record.state_guard,
        schema,
        now
      )
    );
  }
  return { updates, rejected };
}


function sanitize(value, maximum = 240) {
  return String(value || "")
    .replace(/https?:\/\/\S+/gi, "[url]")
    .replace(/\bauthorization\s*[:=]\s*(?:bearer\s+)?\S+/gi, "authorization=[redacted]")
    .replace(/(?:api[-_ ]?key|token|secret|webhook)\s*[:=]\s*\S+/gi, "$1=[redacted]")
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, maximum);
}

function slackEscape(value) {
  return sanitize(value, 1000)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function listSummary(value, policy, fallback = "None") {
  const items = Array.isArray(value) ? value : [];
  const text = items
    .slice(0, 6)
    .map((item) =>
      sanitize(
        typeof item === "object"
          ? item.summary || item.text || item.requirement || JSON.stringify(item)
          : item,
        policy.summary_item_characters
      )
    )
    .filter(Boolean)
    .join("; ");
  return text || fallback;
}

function stableHash(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function alertIdempotencyKey(record, policy) {
  const category = alertCategory(record, policy) || "ineligible";
  const preparationIdentity = [
    Number(record.preparation_version || 0),
    String(record.preparation_input_guard || "")
  ].join(":");
  return [
    "slack",
    record.canonical_job_id,
    policy.policy_version,
    category,
    preparationIdentity,
    category === "copy_ready" ? record.generated_at : "",
    category === "copy_ready"
      ? stableHash(String(record.generated_message || ""))
      : stableHash(String(record.required_input || ""))
  ].join(":");
}

function alertCategory(record, policy) {
  if (
    record?.pipeline_status !== "ready_to_apply" ||
    record?.user_action
  ) return "";
  if (record.prep_status === "message_ready") return "copy_ready";
  if (
    policy?.preparation_reminders?.enabled === true &&
    policy.preparation_reminders.statuses?.includes(record.prep_status)
  ) {
    return `${record.prep_status}_reminder`;
  }
  return "";
}

function validateAlertPolicy(policy) {
  const errors = [];
  if (policy?.schema_version !== 3) {
    errors.push("alert policy schema_version must be 3");
  }
  if (policy?.channel !== "slack") errors.push("alert channel must be slack");
  for (const field of [
    "schedule_minutes",
    "execution_timeout_seconds",
    "claim_lease_ms",
    "provider_timeout_ms",
    "provider_request_interval_ms",
    "per_run_cap",
    "maximum_message_characters",
    "maximum_action_url_characters",
    "summary_item_characters"
  ]) {
    if (!Number.isInteger(policy?.[field]) || policy[field] < 1) {
      errors.push(`${field} must be a positive integer`);
    }
  }
  if (
    Number.isInteger(policy?.execution_timeout_seconds) &&
    policy.execution_timeout_seconds >= policy.schedule_minutes * 60
  ) {
    errors.push("alert timeout must be shorter than its schedule");
  }
  if (
    Number.isInteger(policy?.provider_timeout_ms) &&
    policy.provider_timeout_ms >= policy.execution_timeout_seconds * 1000
  ) {
    errors.push("Slack timeout must be shorter than workflow timeout");
  }
  if (
    Number.isInteger(policy?.per_run_cap) &&
    Number.isInteger(policy?.provider_timeout_ms) &&
    Number.isInteger(policy?.provider_request_interval_ms) &&
    Number.isInteger(policy?.execution_timeout_seconds) &&
    policy.per_run_cap * policy.provider_timeout_ms +
      Math.max(0, policy.per_run_cap - 1) *
        policy.provider_request_interval_ms >=
      policy.execution_timeout_seconds * 1000
  ) {
    errors.push("serial Slack provider budget must fit workflow timeout");
  }
  if (
    Number.isInteger(policy?.claim_lease_ms) &&
    policy.claim_lease_ms <= policy.execution_timeout_seconds * 1000
  ) {
    errors.push("alert claim lease must outlast workflow timeout");
  }
  if (
    !Number.isInteger(policy?.retry?.max_attempts) ||
    policy.retry.max_attempts < 1 ||
    !Number.isInteger(policy?.retry?.backoff_ms) ||
    policy.retry.backoff_ms < policy.claim_lease_ms
  ) {
    errors.push("alert retry must be bounded and begin after claim expiry");
  }
  if (policy?.retry?.ambiguous_timeout_terminal !== true) {
    errors.push("ambiguous Slack timeouts must be terminal");
  }
  if (
    policy?.eligibility?.pipeline_status !== "ready_to_apply" ||
    policy?.eligibility?.required_prep_status !== "message_ready" ||
    policy?.eligibility?.required_pack_status !== "ready" ||
    policy?.eligibility?.required_message_status !== "valid"
  ) {
    errors.push("alert eligibility must require a fully ready application");
  }
  if (
    policy?.preparation_reminders?.enabled !== true ||
    JSON.stringify(policy?.preparation_reminders?.statuses) !==
      JSON.stringify(["needs_input", "external_steps"]) ||
    !Number.isInteger(
      policy?.preparation_reminders?.maximum_checklist_characters
    ) ||
    policy.preparation_reminders.maximum_checklist_characters < 1 ||
    policy.preparation_reminders.maximum_checklist_characters > 4000
  ) {
    errors.push("preparation reminders must be bounded to the supported states");
  }
  for (const field of ["provider_webhook_url", "review_url"]) {
    if (!/^[A-Z][A-Z0-9_]+$/.test(policy?.environment?.[field] || "")) {
      errors.push(`${field} must name an environment variable`);
    }
  }
  return errors;
}

function validateAlertRuntimeCapacity(policy, runtimeConfig) {
  const errors = [];
  const retry = runtimeConfig?.google_sheets_read_retry;
  const serialProviderBudget =
    Number(policy?.per_run_cap || 0) * Number(policy?.provider_timeout_ms || 0) +
    Math.max(0, Number(policy?.per_run_cap || 0) - 1) *
      Number(policy?.provider_request_interval_ms || 0);
  const requiredHeadroom =
    serialProviderBudget + Number(retry?.quota_window_delay_ms || 0) + 20000;
  if (
    runtimeConfig?.minimum_provider_commit_headroom_ms < requiredHeadroom
  ) {
    errors.push(
      "provider commit headroom must fit the bounded provider phase and persistence"
    );
  }
  if (
    runtimeConfig?.execution_timeout_seconds !== policy?.execution_timeout_seconds ||
    runtimeConfig?.claim_lease_ms !== policy?.claim_lease_ms ||
    runtimeConfig?.schedule_minutes !== policy?.schedule_minutes ||
    runtimeConfig?.schedule_offset_minutes !== policy?.schedule_offset_minutes ||
    runtimeConfig?.alert_per_run_cap !== policy?.per_run_cap
  ) {
    errors.push("alert runtime bounds must match the alert policy");
  }
  return errors;
}

function retryDue(record, policy, nowMs, expectedKey) {
  if (record.alert_status === "sending") {
    return false;
  }
  if (record.alert_idempotency_key !== expectedKey) return true;
  const retryAt = Date.parse(record.alert_next_retry_at || "");
  return !record.alert_next_retry_at || !Number.isFinite(retryAt) || retryAt <= nowMs;
}

function preselectPersistedAlertCandidates(
  rows,
  schema,
  policy,
  now = new Date().toISOString()
) {
  if (!Array.isArray(rows)) {
    throw new Error("Persisted alert preselection requires To Apply rows");
  }
  const nowMs = Date.parse(now);
  if (!Number.isFinite(nowMs)) {
    throw new Error("Persisted alert preselection requires a valid timestamp");
  }
  const candidates = [];
  const rejected = [];
  const identities = new Set();
  for (const record of rows) {
    const errors = validateRecordStoreContract(record, "To Apply", schema);
    if (errors.length > 0) {
      rejected.push({
        canonical_job_id: String(record?.canonical_job_id || ""),
        reason: "invalid_record"
      });
      continue;
    }
    const identity = String(record.canonical_job_id)
      .normalize("NFKC")
      .toLocaleLowerCase("en-US");
    if (identities.has(identity)) {
      throw new Error("Alert preselection rejected ambiguous To Apply identity");
    }
    identities.add(identity);

    if (record.alert_status === "sending") {
      const attemptedAt = Date.parse(record.alert_last_attempt_at || "");
      if (
        !Number.isFinite(attemptedAt) ||
        nowMs - attemptedAt >= policy.claim_lease_ms
      ) {
        candidates.push(record);
      }
      continue;
    }

    const category = alertCategory(record, policy);
    const expectedKey = alertIdempotencyKey(record, policy);
    if (
      !category ||
      (record.alert_status === "sent" &&
        record.alert_idempotency_key === expectedKey) ||
      (["terminal_failure", "suppressed"].includes(record.alert_status) &&
        record.alert_idempotency_key === expectedKey) ||
      !retryDue(record, policy, nowMs, expectedKey)
    ) {
      continue;
    }
    candidates.push(record);
  }
  return { candidates, rejected };
}

function countSnapshot(stores, schema) {
  const storeCounts = {};
  const statusCounts = {};
  const preparationStatusCounts = {};
  for (const store of schema.business_stores) {
    const rows = stores[store];
    storeCounts[store] = rows.length;
    statusCounts[store] = {};
    for (const row of rows) {
      const status = String(row.pipeline_status || "unknown");
      statusCounts[store][status] =
        Number(statusCounts[store][status] || 0) + 1;
      const preparationStatus = String(row.prep_status || "");
      if (preparationStatus) {
        preparationStatusCounts[preparationStatus] =
          Number(preparationStatusCounts[preparationStatus] || 0) + 1;
      }
    }
  }
  return {
    store_counts: storeCounts,
    status_counts: statusCounts,
    preparation_status_counts: preparationStatusCounts
  };
}

function assertRecoverableBusinessOwnership(stores, schema, movement) {
  const owners = new Map();
  for (const store of schema.business_stores) {
    for (const row of stores[store]) {
      const identity = String(row?.canonical_job_id || "")
        .trim()
        .normalize("NFKC")
        .toLocaleLowerCase("en-US");
      if (!identity) continue;
      const list = owners.get(identity) || [];
      list.push(store);
      owners.set(identity, list);
    }
  }
  for (const [identity, storesForIdentity] of owners) {
    if (storesForIdentity.length < 2) continue;
    const uniqueStores = [...new Set(storesForIdentity)];
    const recoverable =
      storesForIdentity.length === 2 &&
      uniqueStores.length === 2 &&
      movement.moves.some(
        (move) =>
          String(move.canonical_job_id || "")
            .trim()
            .normalize("NFKC")
            .toLocaleLowerCase("en-US") === identity &&
          move.recovery_required === true &&
          uniqueStores.includes(move.source_sheet) &&
          uniqueStores.includes(move.destination)
      );
    if (!recoverable) {
      throw new Error(
        `Alerter & Mover rejected ambiguous business ownership for ${sanitize(identity, 120)}`
      );
    }
  }
}

function planAlerterMoverPhases(
  stores,
  schema,
  policy,
  now = new Date().toISOString(),
  movementOptions
) {
  // A destination copy may legitimately coexist with its source when the
  // prior delete failed. Queue planning recognizes that recoverable pair,
  // rejects identities in unrelated stores, and keeps the normal
  // copy-confirm-delete verification boundary intact.
  const movement = planQueueActions(
    stores,
    schema,
    now,
    undefined,
    movementOptions
  );
  assertRecoverableBusinessOwnership(stores, schema, movement);
  const outcome = planOutcomeUpdates(stores["Applied Jobs"], schema, now);
  const potentialAlerts = preselectPersistedAlertCandidates(
    stores["To Apply"],
    schema,
    policy,
    now
  );
  const touched = new Set();
  for (const plan of movement.moves) {
    touched.add(plan.source_sheet);
    touched.add(plan.destination);
  }
  const touchedSheets = schema.business_stores.filter((store) =>
    touched.has(store)
  );
  const counts = countSnapshot(stores, schema);
  const hasMovementWork = movement.moves.length > 0;
  const hasPotentialAlerts = potentialAlerts.candidates.length > 0;
  const hasOutcomeWork = outcome.updates.length > 0;
  return {
    movement,
    outcome,
    potential_alerts: potentialAlerts,
    touched_sheets: touchedSheets,
    has_movement_work: hasMovementWork,
    has_potential_alerts: hasPotentialAlerts,
    has_outcome_work: hasOutcomeWork,
    has_work: hasMovementWork || hasPotentialAlerts || hasOutcomeWork,
    execution_classification:
      hasMovementWork || hasPotentialAlerts || hasOutcomeWork
        ? "eligible_work"
        : "no_eligible_work",
    ...counts
  };
}

function summarizeAlerterMoverRun({
  plan,
  sheetReadRequests = 0,
  quotaRetries = 0,
  alerts = {},
  errorCategories = [],
  providerClassifications = []
}) {
  const movementCount = Number(plan?.movement?.moves?.length || 0);
  const outcomeCount = Number(plan?.outcome?.updates?.length || 0);
  const selected = Number(alerts.selected || 0);
  const delivered = Number(alerts.delivered || 0);
  const reconciled = Number(alerts.reconciled || 0);
  const retryable = Number(alerts.retryable || 0);
  const terminal = Number(alerts.terminal || 0);
  const copyReadyAlerts = Number(alerts.copy_ready || 0);
  const preparationReminders = Number(alerts.preparation_reminders || 0);
  const routes = (plan?.movement?.moves || []).map((move) => move.route_reason);
  const rejections = plan?.movement?.rejected || [];
  const hasErrors = errorCategories.length > 0;
  const classification = hasErrors
    ? "completed_with_errors"
    : movementCount + outcomeCount + selected + reconciled > 0
      ? "completed_with_work"
      : "no_eligible_work";
  return {
    execution_classification: classification,
    store_counts: plan?.store_counts || {},
    status_counts: plan?.status_counts || {},
    preparation_status_counts: plan?.preparation_status_counts || {},
    movement_count: movementCount,
    movement: {
      proceeded: routes.filter((value) => value === "review_proceeded").length,
      rejected: routes.filter((value) => value === "review_rejected").length,
      applied: routes.filter((value) => value === "user_applied").length,
      skipped: routes.filter((value) =>
        ["user_skip", "automatic_skip"].includes(value)
      ).length,
      repeated_case_suppressions: rejections.filter((entry) =>
        [
          "resolved_review_case_repeated",
          "review_reopen_missing_new_case",
          "review_reopen_missing_reason"
        ].includes(entry.reason)
      ).length,
      partial_recoveries: (plan?.movement?.moves || []).filter(
        (move) => move.recovery_required === true
      ).length,
      failures: rejections.filter(
        (entry) => entry.reason !== "movement_cap_reached"
      ).length
    },
    outcome_update_count: outcomeCount,
    alerts: {
      selected,
      delivered,
      reconciled,
      retryable,
      terminal,
      copy_ready: copyReadyAlerts,
      preparation_reminders: preparationReminders
    },
    provider_classifications: [...new Set(
      providerClassifications.map((value) => sanitize(value, 80))
    )].filter(Boolean),
    sheet_read_request_count: Number(sheetReadRequests || 0),
    quota_retry_count: Number(quotaRetries || 0),
    error_categories: [...new Set(errorCategories.map((value) => sanitize(value, 80)))]
      .filter(Boolean)
      .slice(0, 20)
  };
}

function evaluateProviderCommitHeadroom({
  executionStartedAt,
  now = new Date().toISOString(),
  executionTimeoutSeconds,
  minimumHeadroomMs
}) {
  const startedMs = Date.parse(executionStartedAt || "");
  const nowMs = Date.parse(now || "");
  if (!Number.isFinite(startedMs) || !Number.isFinite(nowMs) || nowMs < startedMs) {
    throw new Error("Provider headroom requires ordered ISO timestamps");
  }
  if (
    !Number.isInteger(executionTimeoutSeconds) ||
    executionTimeoutSeconds < 1 ||
    !Number.isInteger(minimumHeadroomMs) ||
    minimumHeadroomMs < 1
  ) {
    throw new Error("Provider headroom requires positive integer runtime bounds");
  }
  const deadlineMs = startedMs + executionTimeoutSeconds * 1000;
  const remainingMs = Math.max(0, deadlineMs - nowMs);
  return {
    eligible: remainingMs >= minimumHeadroomMs,
    remaining_ms: remainingMs,
    required_ms: minimumHeadroomMs,
    deadline_at: new Date(deadlineMs).toISOString(),
    classification:
      remainingMs >= minimumHeadroomMs
        ? "provider_headroom_available"
        : "insufficient_provider_headroom"
  };
}

function evaluateAlertEligibility(
  record,
  policy,
  now,
  messageSafetyContext
) {
  const reasons = [];
  if (record.pipeline_status !== "ready_to_apply") reasons.push("status_not_ready");
  if (record.user_action) reasons.push("operator_action_pending");
  const category = alertCategory(record, policy);
  if (!category) reasons.push("preparation_not_alertable");
  if (category === "copy_ready") {
    if (record.prep_status !== "message_ready") {
      reasons.push("preparation_not_message_ready");
    }
    if (record.application_pack_status !== "ready") reasons.push("pack_not_ready");
    if (record.message_validation_status !== "valid") reasons.push("message_not_valid");
    const safety = evaluatePersistedMessageSafety(record, messageSafetyContext);
    if (!safety.safe) reasons.push(...safety.reasons);
  } else if (category) {
    const checklist = String(record.required_input || "");
    const maximum = Number(
      policy?.preparation_reminders?.maximum_checklist_characters || 0
    );
    if (!checklist.trim()) reasons.push("reminder_checklist_missing");
    if (!maximum || checklist.length > maximum) {
      reasons.push("reminder_checklist_oversized");
    }
    if (
      /[\u0000-\u001f\u007f-\u009f\u200b-\u200d\u202a-\u202e\u2060\u2066-\u2069\ufeff]/u.test(
        checklist
      )
    ) reasons.push("reminder_checklist_unsafe");
  }
  const expectedKey = alertIdempotencyKey(record, policy);
  if (
    record.alert_status === "sent" &&
    record.alert_idempotency_key === expectedKey
  ) {
    reasons.push("already_sent");
  }
  if (
    ["terminal_failure", "suppressed"].includes(record.alert_status) &&
    record.alert_idempotency_key === expectedKey
  ) {
    reasons.push("alert_terminal");
  }
  if (!retryDue(record, policy, Date.parse(now), expectedKey)) {
    reasons.push("retry_not_due");
  }
  return {
    eligible: reasons.length === 0,
    reasons: [...new Set(reasons)],
    idempotency_key: expectedKey,
    category
  };
}

function selectFreshAlertCandidates(
  freshToApplyRows,
  schema,
  policy,
  now,
  messageSafetyContext
) {
  const candidates = [];
  const rejected = [];
  const stateUpdates = [];
  const identities = new Set();
  for (const record of freshToApplyRows) {
    const contractErrors = validateRecordStoreContract(
      record,
      "To Apply",
      schema
    );
    if (contractErrors.length > 0) {
      rejected.push({
        canonical_job_id: String(record?.canonical_job_id || ""),
        reasons: ["invalid_record"]
      });
      continue;
    }
    if (record.state_guard !== stateGuard(record)) {
      rejected.push({
        canonical_job_id: String(record?.canonical_job_id || ""),
        reasons: ["stale_state_guard"]
      });
      continue;
    }
    const identity = String(record.canonical_job_id)
      .normalize("NFKC")
      .toLocaleLowerCase("en-US");
    if (identities.has(identity)) {
      throw new Error("Alert selection rejected ambiguous duplicate To Apply identity");
    }
    identities.add(identity);
    if (record.alert_status === "sending") {
      const attemptedAt = Date.parse(record.alert_last_attempt_at || "");
      const expired =
        !Number.isFinite(attemptedAt) ||
        Date.parse(now) - attemptedAt >= policy.claim_lease_ms;
      if (expired) {
        const updated = {
          ...record,
          alert_status: "terminal_failure",
          alert_claim_token: "",
          alert_next_retry_at: "",
          alert_error_category: "ambiguous_delivery",
          alert_error_summary:
            "A prior Slack send did not reach a confirmed commit; delivery is ambiguous and will not be replayed.",
          record_version: record.record_version + 1,
          updated_at: now
        };
        updated.state_guard = stateGuard(updated);
        stateUpdates.push(updated);
        rejected.push({
          canonical_job_id: record.canonical_job_id,
          reasons: ["ambiguous_delivery"]
        });
        continue;
      }
    }
    const eligibility = evaluateAlertEligibility(
      record,
      policy,
      now,
      messageSafetyContext
    );
    if (eligibility.eligible) {
      candidates.push({ record, ...eligibility });
    } else if (record.pipeline_status === "ready_to_apply") {
      rejected.push({
        canonical_job_id: record.canonical_job_id,
        reasons: eligibility.reasons
      });
    }
  }
  candidates.sort(
    (left, right) =>
      Date.parse(
        left.record.preparation_updated_at ||
          left.record.generated_at ||
          left.record.created_at ||
          ""
      ) -
        Date.parse(
          right.record.preparation_updated_at ||
            right.record.generated_at ||
            right.record.created_at ||
            ""
        ) ||
      left.record.canonical_job_id.localeCompare(right.record.canonical_job_id)
  );
  return {
    candidates: candidates.slice(0, policy.per_run_cap),
    rejected,
    state_updates: stateUpdates
  };
}

function markAlertSending(
  record,
  policy,
  executionId,
  now = new Date().toISOString()
) {
  const idempotencyKey = alertIdempotencyKey(record, policy);
  const sameAttemptSeries = record.alert_idempotency_key === idempotencyKey;
  const marked = {
    ...record,
    alert_status: "sending",
    alert_idempotency_key: idempotencyKey,
    alert_attempt_count:
      (sameAttemptSeries ? Number(record.alert_attempt_count || 0) : 0) + 1,
    alert_last_attempt_at: now,
    alert_next_retry_at: "",
    alert_error_category: "",
    alert_error_summary: "",
    alert_provider_reference: "",
    alert_claim_token: `${sanitize(executionId, 120)}:alert:${stableHash(
      `${record.canonical_job_id}:${idempotencyKey}`
    )}`,
    record_version: record.record_version + 1,
    updated_at: now
  };
  marked.state_guard = stateGuard(marked);
  return marked;
}

function safeHttpsUrl(value, maximum) {
  const parsed = parseHttpUrl(value);
  if (
    parsed?.protocol !== "https:" ||
    parsed.username ||
    parsed.password ||
    parsed.href.length > maximum
  ) {
    return "";
  }
  return parsed.href;
}

function renderSlackAlert(
  record,
  policy,
  { reviewUrl, messageSafetyContext }
) {
  const eligibility = evaluateAlertEligibility(
    { ...record, alert_status: "", alert_idempotency_key: "" },
    policy,
    record.alert_last_attempt_at || new Date().toISOString(),
    messageSafetyContext
  );
  if (!eligibility.eligible) {
    throw new Error(`Slack alert rejected unsafe record: ${eligibility.reasons.join(",")}`);
  }
  const message = String(record.generated_message || "");
  if (
    message.includes("```") ||
    /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f\u200b-\u200d\u2060\ufeff]/u.test(
      message
    )
  ) {
    throw new Error("Slack alert rejected unsafe message framing");
  }
  const sourceUrl = safeHttpsUrl(
    normalizeCanonicalUrl(record.canonical_url),
    policy.maximum_action_url_characters
  );
  const safeReviewUrl = safeHttpsUrl(
    reviewUrl,
    policy.maximum_action_url_characters
  );
  const links = [
    safeReviewUrl
      ? `<${safeReviewUrl}|Open To Apply>`
      : "To Apply: unavailable",
    sourceUrl
      ? `<${sourceUrl}|Open OnlineJobs.ph>`
      : "Source: unavailable"
  ].join(" · ");
  if (eligibility.category !== "copy_ready") {
    const external = eligibility.category === "external_steps_reminder";
    const title = external
      ? "*External application steps — not submitted:*"
      : "*Candidate input needed — preparation paused:*";
    const checklist = slackEscape(record.required_input);
    const text = [
      title,
      `Role: ${slackEscape(record.job_title) || "Untitled role"}`,
      `Checklist: ${checklist}`,
      external
        ? "These steps must be completed by you outside the pipeline. No application was submitted."
        : "Provide the requested facts through the supported preparation update path. No application was submitted.",
      links
    ].join("\n");
    if (text.length > policy.maximum_message_characters) {
      throw new Error("Slack preparation reminder exceeds configured length");
    }
    return {
      channel: "slack",
      category: eligibility.category,
      preparation_version: record.preparation_version,
      preparation_input_guard: record.preparation_input_guard,
      idempotency_key: eligibility.idempotency_key,
      text,
      review_action: { mode: "open_only", url: safeReviewUrl },
      source_action: { mode: "open_only", url: sourceUrl }
    };
  }
  const context = [
    `*Ready to apply:* ${slackEscape(record.job_title) || "Untitled role"}`,
    `Company: ${slackEscape(record.company) || "Unknown"} · Salary: ${slackEscape(record.salary_text) || "Unknown"}`,
    `Qualification: ${record.qualification_score || "Unknown"}/100 · Opportunity: ${record.opportunity_score || "Unknown"}/100 · Confidence: ${slackEscape(record.ranking_confidence) || "Unknown"}`,
    `Why: ${slackEscape(record.decision_reason) || "Validated match"}`,
    `Gaps: ${slackEscape(listSummary(record.requirement_gaps, policy))}`,
    `Instructions: ${slackEscape(listSummary(record.application_instructions, policy))}`,
    `Questions: ${slackEscape(listSummary(record.screening_questions, policy))}`,
    `Proofs: ${slackEscape(listSummary(record.selected_proof_refs, policy))}`,
    `Warnings: ${slackEscape(listSummary(record.application_warnings, policy))}`
  ].join("\n");
  const applicationBlock =
    `*Application message — copy exactly:*\n\`\`\`${message}\`\`\``;
  const text = `${context}\n${applicationBlock}\n${links}`;
  if (text.length > policy.maximum_message_characters) {
    throw new Error("Slack alert exceeds configured message length");
  }
  return {
    channel: "slack",
    category: "copy_ready",
    preparation_version: record.preparation_version,
    preparation_input_guard: record.preparation_input_guard,
    idempotency_key: eligibility.idempotency_key,
    text,
    review_action: { mode: "open_only", url: safeReviewUrl },
    source_action: { mode: "open_only", url: sourceUrl }
  };
}

function providerClassification(result, policy) {
  const status = Number(result?.statusCode || result?.status || 0);
  const message = String(
    result?.error?.message || result?.error || result?.message || ""
  );
  if (result?.ok === true || (status >= 200 && status < 300)) {
    return { success: true };
  }
  if (/timeout|timed out/i.test(message)) {
    return {
      success: false,
      retryable: !policy.retry.ambiguous_timeout_terminal,
      category: "ambiguous_timeout"
    };
  }
  if (status === 429 || status >= 500 || /rate.?limit|temporar/i.test(message)) {
    return { success: false, retryable: true, category: "provider_retryable" };
  }
  return { success: false, retryable: false, category: "provider_rejected" };
}

function applySlackProviderResult(
  freshRecord,
  sendingRecord,
  result,
  policy,
  now = new Date().toISOString()
) {
  if (
    !freshRecord ||
    !sendingRecord ||
    freshRecord.canonical_job_id !== sendingRecord.canonical_job_id ||
    freshRecord.record_version !== sendingRecord.record_version ||
    freshRecord.state_guard !== stateGuard(freshRecord) ||
    sendingRecord.state_guard !== stateGuard(sendingRecord) ||
    freshRecord.state_guard !== sendingRecord.state_guard ||
    freshRecord.user_action !== sendingRecord.user_action ||
    freshRecord.prep_status !== sendingRecord.prep_status ||
    freshRecord.preparation_version !== sendingRecord.preparation_version ||
    freshRecord.preparation_input_guard !==
      sendingRecord.preparation_input_guard ||
    freshRecord.alert_status !== "sending" ||
    freshRecord.alert_idempotency_key !== sendingRecord.alert_idempotency_key ||
    !freshRecord.alert_claim_token ||
    freshRecord.alert_claim_token !== sendingRecord.alert_claim_token
  ) {
    throw new Error("Slack result rejected stale To Apply state");
  }
  const classification = providerClassification(result, policy);
  const attempts = Number(freshRecord.alert_attempt_count || 0);
  const retryable =
    !classification.success &&
    classification.retryable &&
    attempts < policy.retry.max_attempts;
  const updated = {
    ...freshRecord,
    alert_status: classification.success
      ? "sent"
      : retryable
        ? "retryable_failure"
        : "terminal_failure",
    alert_sent_at: classification.success ? now : "",
    alert_provider_reference: classification.success
      ? sanitize(result?.reference || result?.ts || "accepted", 120)
      : "",
    alert_error_category: classification.success
      ? ""
      : classification.category,
    alert_error_summary: classification.success
      ? ""
      : sanitize(
          result?.error?.message || result?.error || result?.message || "Slack request failed"
        ),
    alert_next_retry_at: retryable
      ? new Date(Date.parse(now) + policy.retry.backoff_ms).toISOString()
      : "",
    alert_claim_token: "",
    record_version: freshRecord.record_version + 1,
    updated_at: now
  };
  updated.state_guard = stateGuard(updated);
  return updated;
}

function planAlerterMoverRun(
  stores,
  schema,
  policy,
  now,
  messageSafetyContext,
  movementOptions
) {
  // Movement is planned first and remains usable even if an individual alert
  // is unsafe or the Slack provider later fails.
  const movement = planQueueActions(
    stores,
    schema,
    now,
    messageSafetyContext,
    movementOptions
  );
  const alerts = selectFreshAlertCandidates(
    stores["To Apply"],
    schema,
    policy,
    now,
    messageSafetyContext
  );
  return {
    movement,
    writes: destinationWrites(movement),
    alerts
  };
}

const ALERT_RECEIPT_PERSISTED_FIELDS = [
  "schema_version",
  "receipt_id",
  "idempotency_key",
  "canonical_job_id",
  "status",
  "provider_classification",
  "provider_status",
  "provider_reference",
  "error_category",
  "error_summary",
  "execution_id",
  "attempt_count",
  "receipt_version",
  "created_at",
  "updated_at",
  "attempt_started_at",
  "delivered_at",
  "reconciled_at",
  "next_retry_at",
  "terminal_at"
];

const NUMBER_FIELDS = new Set([
  "schema_version",
  "provider_status",
  "attempt_count",
  "receipt_version"
]);

const TIMESTAMP_FIELDS = [
  "created_at",
  "updated_at",
  "attempt_started_at",
  "delivered_at",
  "reconciled_at",
  "next_retry_at",
  "terminal_at"
];

const REQUIRED_STATUSES = [
  "pending",
  "sending",
  "delivered",
  "reconciled",
  "retryable_rejection",
  "terminal_rejection",
  "terminal_ambiguity"
];

const REQUIRED_PROVIDER_CLASSIFICATIONS = [
  "not_attempted",
  "accepted",
  "retryable_rejection",
  "definite_rejection",
  "ambiguous"
];

const RECEIPT_ERROR_SUMMARIES = {
  provider_retryable: "Provider rejected the delivery attempt temporarily",
  provider_rejected: "Provider rejected the delivery attempt",
  ambiguous_delivery: "Provider delivery outcome is ambiguous"
};

function sanitizeAlertReceiptValue(value, maximum = 240) {
  return String(value || "")
    .replace(/https?:\/\/\S+/gi, "[url]")
    .replace(/\bauthorization\s*[:=]\s*(?:bearer\s+)?\S+/gi, "authorization=[redacted]")
    .replace(/\bbearer\s+\S+/gi, "bearer [redacted]")
    .replace(/(?:api[-_ ]?key|token|secret|webhook)\s*[:=]\s*\S+/gi, "$1=[redacted]")
    .replace(/\b(?:xox[baprs]-[A-Za-z0-9-]+|gh[pousr]_[A-Za-z0-9]+|sk-[A-Za-z0-9_-]{8,})\b/gi, "[credential]")
    .replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200d\u2060\ufeff]/gu, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, maximum);
}

function validAlertReceiptTimestamp(value, maximum) {
  return (
    typeof value === "string" &&
    value.length <= maximum &&
    Number.isFinite(Date.parse(value)) &&
    new Date(value).toISOString() === value
  );
}

function alertReceiptIdentityKey(value) {
  return String(value || "")
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
}

function sanitizeProviderReference(value, maximum) {
  const candidate = sanitizeAlertReceiptValue(value || "accepted", maximum);
  return /^[A-Za-z0-9][A-Za-z0-9._:-]*$/.test(candidate)
    ? candidate
    : "accepted";
}

function exactStringSetErrors(values, required, label) {
  if (!Array.isArray(values)) return [`${label} must be an array`];
  const unique = new Set(values);
  if (
    unique.size !== values.length ||
    unique.size !== required.length ||
    required.some((value) => !unique.has(value))
  ) {
    return [`${label} must contain each supported value exactly once`];
  }
  return [];
}

function validateAlertReceiptPolicy(policy) {
  const errors = [];
  if (policy?.schema_version !== 1) {
    errors.push("alert receipt policy schema_version must be 1");
  }
  if (policy?.store?.kind !== "n8n_data_table") {
    errors.push("alert receipt store must be an n8n Data Table");
  }
  if (!/^[A-Za-z0-9][A-Za-z0-9 _-]{0,127}$/.test(policy?.store?.table_name || "")) {
    errors.push("alert receipt Data Table name is missing or invalid");
  }
  if (!/^[A-Z][A-Z0-9_]+$/.test(policy?.store?.environment_variable || "")) {
    errors.push("alert receipt Data Table environment variable is invalid");
  }
  errors.push(
    ...exactStringSetErrors(
      policy?.statuses,
      REQUIRED_STATUSES,
      "alert receipt statuses"
    ),
    ...exactStringSetErrors(
      policy?.provider_classifications,
      REQUIRED_PROVIDER_CLASSIFICATIONS,
      "alert receipt provider classifications"
    )
  );
  if (!/^\d{4}-\d{2}-\d{2}\/v\d+$/.test(policy?.policy_version || "")) {
    errors.push("alert receipt policy_version is invalid");
  }
  if (
    !Number.isInteger(policy?.maximum_attempts) ||
    policy.maximum_attempts < 1 ||
    policy.maximum_attempts > 10
  ) {
    errors.push("alert receipt maximum_attempts must be between 1 and 10");
  }
  if (
    Number.isInteger(policy?.bounds?.receipt_id) &&
    Number.isInteger(policy?.bounds?.idempotency_key) &&
    policy.bounds.receipt_id < policy.bounds.idempotency_key
  ) {
    errors.push("receipt_id bound must fit the complete idempotency key");
  }
  if (
    Number.isInteger(policy?.bounds?.timestamp) &&
    policy.bounds.timestamp < 24
  ) {
    errors.push("timestamp bound is too small for an ISO timestamp");
  }
  for (const field of [
    "receipt_id",
    "idempotency_key",
    "canonical_job_id",
    "execution_id",
    "provider_reference",
    "error_category",
    "error_summary",
    "timestamp"
  ]) {
    if (!Number.isInteger(policy?.bounds?.[field]) || policy.bounds[field] < 1) {
      errors.push(`alert receipt bound ${field} must be a positive integer`);
    }
  }
  if (policy?.retention?.prune_delivered_before_reconciliation !== false) {
    errors.push("delivered receipts must not be pruned before reconciliation");
  }
  if (policy?.retention?.backup_required !== true) {
    errors.push("alert receipt store backup must be required");
  }
  return errors;
}

function validateAlertReceiptCompatibility(policy, alertPolicy) {
  const errors = [];
  if (
    policy?.maximum_attempts !== alertPolicy?.retry?.max_attempts
  ) {
    errors.push("alert receipt and Slack retry caps must match");
  }
  if (
    policy?.store?.environment_variable ===
    alertPolicy?.environment?.provider_webhook_url
  ) {
    errors.push("alert receipt and Slack webhook bindings must be separate");
  }
  return errors;
}

function alertReceiptId(idempotencyKey, policy) {
  const key = String(idempotencyKey || "").trim();
  const maximum = policy?.bounds?.idempotency_key;
  if (!Number.isInteger(maximum) || !key || key.length > maximum) {
    throw new Error("Alert receipt requires a bounded idempotency key");
  }
  return key;
}

function normalizeAlertReceipt(input, policy) {
  const receipt = {};
  for (const field of ALERT_RECEIPT_PERSISTED_FIELDS) {
    const value = input?.[field];
    if (NUMBER_FIELDS.has(field)) {
      receipt[field] = value === "" || value === undefined || value === null
        ? 0
        : Number(value);
    } else {
      receipt[field] = String(value ?? "").trim();
    }
  }
  receipt.schema_version = Number(receipt.schema_version || policy?.schema_version || 0);
  return receipt;
}

function validateAlertReceipt(receipt, policy) {
  const policyErrors = validateAlertReceiptPolicy(policy);
  if (policyErrors.length > 0) return policyErrors;
  const errors = [];
  const bounds = policy.bounds;
  if (receipt?.schema_version !== policy.schema_version) {
    errors.push("receipt schema_version is invalid");
  }
  for (const [field, maximum] of [
    ["receipt_id", bounds.receipt_id],
    ["idempotency_key", bounds.idempotency_key],
    ["canonical_job_id", bounds.canonical_job_id],
    ["execution_id", bounds.execution_id]
  ]) {
    const value = String(receipt?.[field] || "");
    if (
      !value ||
      value.length > maximum ||
      value.normalize("NFKC") !== value ||
      sanitizeAlertReceiptValue(value, maximum) !== value
    ) {
      errors.push(`${field} is missing, oversized, or unsafe`);
    }
  }
  let expectedReceiptId = null;
  try {
    expectedReceiptId = alertReceiptId(receipt?.idempotency_key, policy);
  } catch {
    // The bounded-field validation above owns the detailed identity error.
  }
  if (
    receipt?.receipt_id !== receipt?.idempotency_key ||
    receipt?.receipt_id !== expectedReceiptId
  ) {
    errors.push("receipt identity must equal the alert idempotency key");
  }
  if (!policy.statuses.includes(receipt?.status)) {
    errors.push("receipt status is invalid");
  }
  if (!policy.provider_classifications.includes(receipt?.provider_classification)) {
    errors.push("receipt provider classification is invalid");
  }
  if (
    !Number.isInteger(receipt?.attempt_count) ||
    receipt.attempt_count < 1 ||
    receipt.attempt_count > policy.maximum_attempts
  ) {
    errors.push("receipt attempt_count is invalid");
  }
  if (
    !Number.isSafeInteger(receipt?.receipt_version) ||
    receipt.receipt_version < 1
  ) {
    errors.push("receipt receipt_version is invalid");
  }
  if (
    !Number.isInteger(receipt?.provider_status) ||
    receipt.provider_status < 0 ||
    receipt.provider_status > 599
  ) {
    errors.push("receipt provider_status is invalid");
  }
  for (const field of TIMESTAMP_FIELDS) {
    if (
      receipt?.[field] &&
      !validAlertReceiptTimestamp(receipt[field], bounds.timestamp)
    ) {
      errors.push(`${field} is invalid`);
    }
  }
  if (!receipt?.created_at || !receipt?.updated_at) {
    errors.push("receipt created_at and updated_at are required");
  } else if (Date.parse(receipt.updated_at) < Date.parse(receipt.created_at)) {
    errors.push("receipt updated_at cannot precede created_at");
  }
  const createdMs = Date.parse(receipt?.created_at || "");
  const updatedMs = Date.parse(receipt?.updated_at || "");
  for (const field of [
    "attempt_started_at",
    "delivered_at",
    "reconciled_at",
    "terminal_at"
  ]) {
    const valueMs = Date.parse(receipt?.[field] || "");
    if (
      receipt?.[field] &&
      Number.isFinite(createdMs) &&
      Number.isFinite(updatedMs) &&
      (valueMs < createdMs || valueMs > updatedMs)
    ) {
      errors.push(`${field} must be within the receipt lifetime`);
    }
  }
  if (
    receipt?.delivered_at &&
    receipt?.attempt_started_at &&
    Date.parse(receipt.delivered_at) < Date.parse(receipt.attempt_started_at)
  ) {
    errors.push("receipt delivered_at cannot precede attempt_started_at");
  }
  if (
    receipt?.reconciled_at &&
    receipt?.delivered_at &&
    Date.parse(receipt.reconciled_at) < Date.parse(receipt.delivered_at)
  ) {
    errors.push("receipt reconciled_at cannot precede delivered_at");
  }
  if (
    receipt?.terminal_at &&
    receipt?.attempt_started_at &&
    Date.parse(receipt.terminal_at) < Date.parse(receipt.attempt_started_at)
  ) {
    errors.push("receipt terminal_at cannot precede attempt_started_at");
  }
  if (
    receipt?.next_retry_at &&
    Number.isFinite(updatedMs) &&
    Date.parse(receipt.next_retry_at) <= updatedMs
  ) {
    errors.push("receipt next_retry_at must follow updated_at");
  }
  const reference = String(receipt?.provider_reference || "");
  const category = String(receipt?.error_category || "");
  const summary = String(receipt?.error_summary || "");
  if (
    reference.length > bounds.provider_reference ||
    sanitizeAlertReceiptValue(reference, bounds.provider_reference) !== reference ||
    (reference && !/^[A-Za-z0-9][A-Za-z0-9._:-]*$/.test(reference))
  ) {
    errors.push("receipt provider_reference is oversized or unsafe");
  }
  if (
    category.length > bounds.error_category ||
    sanitizeAlertReceiptValue(category, bounds.error_category) !== category ||
    (category && !Object.hasOwn(RECEIPT_ERROR_SUMMARIES, category))
  ) {
    errors.push("receipt error_category is oversized or unsafe");
  }
  if (
    summary.length > bounds.error_summary ||
    sanitizeAlertReceiptValue(summary, bounds.error_summary) !== summary ||
    (summary && summary !== RECEIPT_ERROR_SUMMARIES[category])
  ) {
    errors.push("receipt error_summary is oversized or unsafe");
  }

  if (["pending", "sending"].includes(receipt?.status)) {
    if (receipt.provider_classification !== "not_attempted") {
      errors.push("unsent receipt cannot contain a provider outcome");
    }
    if (receipt.provider_status || reference || category || summary) {
      errors.push("unsent receipt contains provider result metadata");
    }
  }
  if (receipt?.status === "pending") {
    if (
      receipt?.attempt_started_at ||
      receipt?.delivered_at ||
      receipt?.reconciled_at ||
      receipt?.next_retry_at ||
      receipt?.terminal_at
    ) {
      errors.push("pending receipt cannot contain attempt or outcome timestamps");
    }
  }
  if (receipt?.status === "sending") {
    if (!receipt?.attempt_started_at) {
      errors.push("sending receipt requires attempt_started_at");
    }
    if (
      receipt?.delivered_at ||
      receipt?.reconciled_at ||
      receipt?.next_retry_at ||
      receipt?.terminal_at
    ) {
      errors.push("sending receipt cannot contain provider outcome timestamps");
    }
  }
  if (["delivered", "reconciled"].includes(receipt?.status)) {
    if (
      receipt.provider_classification !== "accepted" ||
      receipt.provider_status < 200 ||
      receipt.provider_status >= 300 ||
      !receipt.attempt_started_at ||
      !receipt.delivered_at ||
      category ||
      summary
    ) {
      errors.push("delivered receipt requires a confirmed bounded provider success");
    }
  }
  if (receipt?.status === "delivered") {
    if (receipt?.reconciled_at || receipt?.next_retry_at || receipt?.terminal_at) {
      errors.push("delivered receipt cannot contain later outcome timestamps");
    }
  }
  if (receipt?.status === "reconciled") {
    if (!receipt?.reconciled_at) {
      errors.push("reconciled receipt requires reconciled_at");
    }
    if (receipt?.next_retry_at || receipt?.terminal_at) {
      errors.push("reconciled receipt cannot contain retry or terminal timestamps");
    }
  }
  if (receipt?.status === "retryable_rejection") {
    if (
      receipt.provider_classification !== "retryable_rejection" ||
      !receipt.attempt_started_at ||
      !receipt.next_retry_at ||
      receipt.attempt_count >= policy.maximum_attempts ||
      !category ||
      receipt.delivered_at ||
      receipt.reconciled_at ||
      receipt.terminal_at
    ) {
      errors.push("retryable receipt outcome is invalid or exceeds its cap");
    }
  }
  if (receipt?.status === "terminal_rejection") {
    if (
      !["retryable_rejection", "definite_rejection"].includes(
        receipt.provider_classification
      ) ||
      !receipt.attempt_started_at ||
      !receipt.terminal_at ||
      !category ||
      receipt.next_retry_at ||
      receipt.delivered_at ||
      receipt.reconciled_at
    ) {
      errors.push("terminal rejection receipt is invalid");
    }
  }
  if (receipt?.status === "terminal_ambiguity") {
    if (
      receipt.provider_classification !== "ambiguous" ||
      !receipt.attempt_started_at ||
      !receipt.terminal_at ||
      !category ||
      receipt.next_retry_at ||
      receipt.delivered_at ||
      receipt.reconciled_at
    ) {
      errors.push("terminal ambiguous receipt is invalid");
    }
  }
  return [...new Set(errors)];
}

function assertValidReceipt(receipt, policy, prefix) {
  const errors = validateAlertReceipt(receipt, policy);
  if (errors.length > 0) {
    throw new Error(`${prefix}: ${errors.join("; ")}`);
  }
}

function createPendingAlertReceipt(
  {
    idempotencyKey,
    canonicalJobId,
    executionId,
    attemptCount = 1,
    now = new Date().toISOString()
  },
  policy
) {
  const receipt = normalizeAlertReceipt(
    {
      schema_version: policy.schema_version,
      receipt_id: alertReceiptId(idempotencyKey, policy),
      idempotency_key: idempotencyKey,
      canonical_job_id: canonicalJobId,
      status: "pending",
      provider_classification: "not_attempted",
      execution_id: executionId,
      attempt_count: attemptCount,
      receipt_version: 1,
      created_at: now,
      updated_at: now
    },
    policy
  );
  assertValidReceipt(receipt, policy, "Invalid pending alert receipt");
  return receipt;
}

const ALLOWED_TRANSITIONS = new Map([
  ["pending", new Set(["sending"])],
  [
    "sending",
    new Set([
      "delivered",
      "retryable_rejection",
      "terminal_rejection",
      "terminal_ambiguity"
    ])
  ],
  ["retryable_rejection", new Set(["pending"])],
  ["delivered", new Set(["reconciled"])]
]);

function transitionAlertReceipt(
  currentInput,
  {
    expectedVersion,
    status,
    executionId,
    providerStatus,
    providerClassification,
    providerReference,
    errorCategory,
    nextRetryAt,
    now = new Date().toISOString()
  },
  policy
) {
  const current = normalizeAlertReceipt(currentInput, policy);
  assertValidReceipt(current, policy, "Cannot transition invalid alert receipt");
  if (current.receipt_version !== expectedVersion) {
    throw new Error("Alert receipt transition rejected stale receipt_version");
  }
  if (current.status === status) {
    throw new Error("Alert receipt transition rejected duplicate status");
  }
  if (!ALLOWED_TRANSITIONS.get(current.status)?.has(status)) {
    throw new Error(`Alert receipt transition rejected ${current.status} -> ${status}`);
  }
  if (!validAlertReceiptTimestamp(now, policy.bounds.timestamp)) {
    throw new Error("Alert receipt transition requires a valid timestamp");
  }
  if (Date.parse(now) < Date.parse(current.updated_at)) {
    throw new Error("Alert receipt transition timestamp is stale");
  }
  const receipt = { ...current, status, updated_at: now };
  receipt.receipt_version += 1;

  if (status === "pending") {
    if (current.status !== "retryable_rejection") {
      throw new Error("Only a retryable rejection can start another receipt attempt");
    }
    if (current.attempt_count >= policy.maximum_attempts) {
      throw new Error("Alert receipt retry exceeds maximum_attempts");
    }
    if (current.next_retry_at && Date.parse(now) < Date.parse(current.next_retry_at)) {
      throw new Error("Alert receipt retry is not due");
    }
    receipt.attempt_count += 1;
    const nextExecutionId = String(executionId || "").trim();
    if (
      !nextExecutionId ||
      nextExecutionId.length > policy.bounds.execution_id ||
      sanitizeAlertReceiptValue(nextExecutionId, policy.bounds.execution_id) !==
        nextExecutionId
    ) {
      throw new Error("Alert receipt retry requires a bounded safe execution ID");
    }
    receipt.execution_id = nextExecutionId;
    receipt.provider_classification = "not_attempted";
    receipt.provider_status = 0;
    receipt.provider_reference = "";
    receipt.error_category = "";
    receipt.error_summary = "";
    receipt.attempt_started_at = "";
    receipt.next_retry_at = "";
    receipt.terminal_at = "";
  } else if (status === "sending") {
    receipt.attempt_started_at = now;
  } else if (status === "delivered") {
    receipt.provider_classification = "accepted";
    receipt.provider_status = Number(providerStatus || 0);
    receipt.provider_reference = sanitizeProviderReference(
      providerReference,
      policy.bounds.provider_reference
    );
    receipt.error_category = "";
    receipt.error_summary = "";
    receipt.delivered_at = now;
    receipt.next_retry_at = "";
  } else if (status === "retryable_rejection") {
    if (current.attempt_count >= policy.maximum_attempts) {
      throw new Error("Alert receipt retryable outcome exceeds maximum_attempts");
    }
    receipt.provider_classification = "retryable_rejection";
    receipt.provider_status = Number(providerStatus || 0);
    receipt.provider_reference = "";
    receipt.error_category = sanitizeAlertReceiptValue(
      errorCategory || "provider_retryable",
      policy.bounds.error_category
    );
    receipt.error_summary = RECEIPT_ERROR_SUMMARIES.provider_retryable;
    receipt.next_retry_at = String(nextRetryAt || "");
  } else if (status === "terminal_rejection") {
    if (
      !["retryable_rejection", "definite_rejection"].includes(
        providerClassification
      )
    ) {
      throw new Error("Terminal rejection requires a definite provider classification");
    }
    receipt.provider_classification = providerClassification;
    receipt.provider_status = Number(providerStatus || 0);
    receipt.provider_reference = "";
    receipt.error_category = sanitizeAlertReceiptValue(
      errorCategory || "provider_rejected",
      policy.bounds.error_category
    );
    receipt.error_summary = RECEIPT_ERROR_SUMMARIES[receipt.error_category] ||
      RECEIPT_ERROR_SUMMARIES.provider_rejected;
    receipt.next_retry_at = "";
    receipt.terminal_at = now;
  } else if (status === "terminal_ambiguity") {
    receipt.provider_classification = "ambiguous";
    receipt.provider_status = Number(providerStatus || 0);
    receipt.provider_reference = "";
    receipt.error_category = sanitizeAlertReceiptValue(
      errorCategory || "ambiguous_delivery",
      policy.bounds.error_category
    );
    receipt.error_summary = RECEIPT_ERROR_SUMMARIES.ambiguous_delivery;
    receipt.next_retry_at = "";
    receipt.terminal_at = now;
  } else if (status === "reconciled") {
    receipt.reconciled_at = now;
  }

  assertValidReceipt(receipt, policy, "Invalid alert receipt transition");
  return receipt;
}

function classifyAlertReceiptProviderResult(result) {
  const rawStatus = Number(
    result?.statusCode ||
      result?.status ||
      result?.error?.statusCode ||
      result?.error?.status ||
      0
  );
  const status = Number.isInteger(rawStatus) && rawStatus >= 0 && rawStatus <= 599
    ? rawStatus
    : 0;
  if ((status >= 200 && status < 300) || (result?.ok === true && status === 0)) {
    return { classification: "accepted", provider_status: status || 200 };
  }
  if (status === 429 || status >= 500) {
    return {
      classification: "retryable_rejection",
      provider_status: status,
      error_category: "provider_retryable",
      error_summary: RECEIPT_ERROR_SUMMARIES.provider_retryable
    };
  }
  if (status >= 300) {
    return {
      classification: "definite_rejection",
      provider_status: status,
      error_category: "provider_rejected",
      error_summary: RECEIPT_ERROR_SUMMARIES.provider_rejected
    };
  }
  return {
    classification: "ambiguous",
    provider_status: status,
    error_category: "ambiguous_delivery",
    error_summary: RECEIPT_ERROR_SUMMARIES.ambiguous_delivery
  };
}

function applyProviderResultToAlertReceipt(
  current,
  result,
  { expectedVersion, retryAt, now = new Date().toISOString() },
  policy
) {
  const outcome = classifyAlertReceiptProviderResult(result);
  const status = outcome.classification === "accepted"
    ? "delivered"
    : outcome.classification === "ambiguous"
      ? "terminal_ambiguity"
      : outcome.classification === "retryable_rejection" &&
          current.attempt_count < policy.maximum_attempts
        ? "retryable_rejection"
        : "terminal_rejection";
  return transitionAlertReceipt(
    current,
    {
      expectedVersion,
      status,
      providerStatus: outcome.provider_status,
      providerClassification: outcome.classification,
      providerReference: result?.reference || result?.ts || "accepted",
      errorCategory: outcome.error_category,
      nextRetryAt: status === "retryable_rejection" ? retryAt : "",
      now
    },
    policy
  );
}

function alertReceiptPersistenceRow(receiptInput, policy) {
  const receipt = normalizeAlertReceipt(receiptInput, policy);
  assertValidReceipt(receipt, policy, "Refusing to persist invalid alert receipt");
  return Object.fromEntries(
    ALERT_RECEIPT_PERSISTED_FIELDS.map((field) => [field, receipt[field]])
  );
}

function alertReceiptDataTableSchema() {
  return ALERT_RECEIPT_PERSISTED_FIELDS.map((field) => ({
    name: field,
    type: NUMBER_FIELDS.has(field) ? "number" : "string"
  }));
}

function planAlertReceiptBusinessReconciliation(
  receiptInput,
  stores,
  schema,
  policy,
  now = new Date().toISOString()
) {
  const receipt = normalizeAlertReceipt(receiptInput, policy);
  assertValidReceipt(receipt, policy, "Cannot reconcile invalid alert receipt");
  if (receipt.status === "reconciled") {
    return {
      classification: "already_reconciled",
      provider_send: false,
      business_update: null,
      receipt_update: null
    };
  }
  const supported = new Set([
    "delivered",
    "retryable_rejection",
    "terminal_rejection",
    "terminal_ambiguity"
  ]);
  if (!supported.has(receipt.status)) {
    return {
      classification: "provider_outcome_not_available",
      provider_send: false,
      business_update: null,
      receipt_update: null
    };
  }

  const targetStores = ["To Apply", "Applied Jobs", "Archive"];
  const matches = [];
  const expectedIdentity = alertReceiptIdentityKey(receipt.canonical_job_id);
  for (const store of targetStores) {
    if (!Array.isArray(stores?.[store])) {
      throw new Error(`Receipt reconciliation requires ${store} rows`);
    }
    for (const record of stores[store]) {
      if (alertReceiptIdentityKey(record?.canonical_job_id) === expectedIdentity) {
        matches.push({ store, record });
      }
    }
  }
  if (matches.length > 1) {
    throw new Error("Receipt reconciliation rejected ambiguous canonical ownership");
  }
  if (matches.length === 0) {
    return {
      classification: "owner_not_found",
      provider_send: false,
      business_update: null,
      receipt_update: null
    };
  }
  const { store, record } = matches[0];
  const contractErrors = validateRecordStoreContract(record, store, schema);
  if (contractErrors.length > 0) {
    throw new Error(
      `Receipt reconciliation rejected invalid ${store} record: ${contractErrors.join("; ")}`
    );
  }
  if (record.alert_idempotency_key !== receipt.idempotency_key) {
    throw new Error("Receipt reconciliation rejected a stale idempotency key");
  }
  if (record.state_guard !== stateGuard(record)) {
    throw new Error("Receipt reconciliation rejected a stale state guard");
  }

  const desired = receipt.status === "delivered"
    ? {
        alert_status: "sent",
        alert_sent_at: receipt.delivered_at,
        alert_provider_reference: receipt.provider_reference,
        alert_error_category: "",
        alert_error_summary: "",
        alert_next_retry_at: ""
      }
    : receipt.status === "retryable_rejection"
      ? {
          alert_status: "retryable_failure",
          alert_sent_at: "",
          alert_provider_reference: "",
          alert_error_category: receipt.error_category,
          alert_error_summary: receipt.error_summary,
          alert_next_retry_at: receipt.next_retry_at
        }
      : {
          alert_status: "terminal_failure",
          alert_sent_at: "",
          alert_provider_reference: "",
          alert_error_category: receipt.error_category,
          alert_error_summary: receipt.error_summary,
          alert_next_retry_at: ""
        };
  const common = {
    alert_idempotency_key: receipt.idempotency_key,
    alert_claim_token: "",
    alert_attempt_count: receipt.attempt_count,
    alert_last_attempt_at: receipt.attempt_started_at
  };
  const expectedFields = { ...common, ...desired };
  const alreadyPersisted = Object.entries(expectedFields).every(
    ([field, value]) => String(record[field] ?? "") === String(value ?? "")
  );
  let businessUpdate = null;
  if (!alreadyPersisted) {
    businessUpdate = {
      ...record,
      ...expectedFields,
      record_version: Number(record.record_version || 0) + 1,
      updated_at: now
    };
    businessUpdate.state_guard = stateGuard(businessUpdate);
    const updateErrors = validateRecordStoreContract(
      businessUpdate,
      store,
      schema
    );
    if (updateErrors.length > 0) {
      throw new Error(
        `Receipt reconciliation produced an invalid ${store} update: ${updateErrors.join("; ")}`
      );
    }
  }
  return {
    classification: businessUpdate
      ? "reconcile_business_record"
      : receipt.status === "delivered"
        ? "mark_receipt_reconciled"
        : "business_record_already_reconciled",
    provider_send: false,
    owner_store: store,
    business_update: businessUpdate,
    receipt_update:
      receipt.status === "delivered"
        ? transitionAlertReceipt(
            receipt,
            {
              expectedVersion: receipt.receipt_version,
              status: "reconciled",
              now
            },
            policy
          )
        : null
  };
}

function planDeliveredReceiptReconciliation(
  receiptInput,
  stores,
  schema,
  policy,
  now = new Date().toISOString()
) {
  if (!receiptInput) {
    return {
      classification: "legacy_no_receipt",
      provider_send: false,
      business_update: null,
      receipt_update: null
    };
  }
  const receipt = normalizeAlertReceipt(receiptInput, policy);
  assertValidReceipt(receipt, policy, "Cannot reconcile invalid alert receipt");
  if (receipt.status === "reconciled") {
    return {
      classification: "already_reconciled",
      provider_send: false,
      business_update: null,
      receipt_update: null
    };
  }
  if (receipt.status !== "delivered") {
    return {
      classification: "not_delivered",
      provider_send: false,
      business_update: null,
      receipt_update: null
    };
  }
  return planAlertReceiptBusinessReconciliation(
    receipt,
    stores,
    schema,
    policy,
    now
  );
}

