const SALARY_COMMITMENT_PATTERN =
  /\b(?:my\s+)?(?:expected|desired|requested)?\s*(?:salary|hourly rate|compensation)\b|\b(?:usd|php|\$|₱)\s*\d/gi;
const START_DATE_COMMITMENT_PATTERN =
  /\b(?:i\s+can|i'm|i am|available\s+to)\s+(?:start|join)(?:\s+on|\s+from|\s+immediately)?\b/gi;
const COMPLETION_CLAIM_PATTERN =
  /\b(?:(?:i\s+(?:(?:have|already)\s+)?|my\s+)?(?:attached|included)\s+(?:(?:my|the)\s+)?(?:requested\s+)?(?:cv|curriculum vitae|r[ée]sum[ée]|attachment)|(?:(?:my|the)\s+)?(?:requested\s+)?(?:cv|curriculum vitae|r[ée]sum[ée])\s+(?:(?:(?:is|was|has\s+been)\s+)?(?:attached|included)(?:\s+successfully)?|accompanies\s+(?:this|the)\s+application)|you\s+(?:will|can)\s+find\s+(?:(?:my|the)\s+)?(?:requested\s+)?(?:cv|curriculum vitae|r[ée]sum[ée])\s+(?:attached|included)|(?:i\s+(?:have\s+|already\s+)?)?(?:completed|submitted)\s+(?:the|your|this)?\s*(?:assessment|test|form|questionnaire|application)|(?:the|your|this)?\s*(?:assessment|test|form|questionnaire)\s+(?:(?:is|was)\s+(?:complete|completed|submitted)|has\s+been\s+(?:completed|submitted))|recorded\s+(?:a|the)\s+(?:video|recording))\b/gi;
const INTERNAL_CONTEXT_PATTERN =
  /\b(?:requirement gaps?|match tier|application warnings?|ranking score|internal evaluation|selected proof refs?)\b/gi;

function removeMatches(value, patterns) {
  return patterns.reduce(
    (remaining, pattern) => remaining.replace(pattern, " "),
    value
  );
}

const SCREENING_QUESTION_STOP_WORDS = new Set([
  "about", "answer", "been", "built", "could", "describe", "does",
  "have", "most", "please", "tell", "that", "their", "thing", "this",
  "using", "what", "when", "where", "which", "with", "would", "you",
  "your"
]);

function screeningQuestionKeywords(question) {
  return [
    ...normalizeText(question)
      .toLowerCase()
      .matchAll(/[a-z0-9]+/g)
  ]
    .map((match) => match[0])
    .filter(
      (token) =>
        (token.length >= 4 || token === "ai") &&
        !SCREENING_QUESTION_STOP_WORDS.has(token)
    );
}

function screeningAnswerErrors(message, pack) {
  const normalizedMessage = normalizeText(message).toLowerCase();
  const errors = [];
  const questions = (pack?.screening_questions ?? []).filter(
    (question) =>
      question?.answer_status === "answer_in_message" &&
      question?.review_acknowledged === true
  );
  for (const question of questions) {
    const id = String(question?.id || "unknown");
    const keywords = [...new Set(screeningQuestionKeywords(question?.text))];
    const matchedKeywords = keywords.filter((keyword) =>
      new RegExp(`\\b${keyword}\\b`, "i").test(normalizedMessage)
    );
    const requiredMatches = Math.min(2, keywords.length);
    if (requiredMatches > 0 && matchedKeywords.length < requiredMatches) {
      errors.push(
        `screening answer is not woven into natural prose: ${id}`
      );
    }
  }
  return errors;
}

const ADJACENT_QUALIFIER_PATTERN =
  /\b(?:rather than|instead of|not an? exact|different|transfer(?:able|red|s)?|adapt(?:able|ed|ing|s)?|comparable|adjacent|while)\b/i;
const UNSUPPORTED_FREQUENCY_PATTERN =
  /\b(?:routinely|always|daily|consistently|every\s+(?:system|project|client|workflow)|each\s+(?:ai\s+)?system|all\s+(?:systems|projects|workflows))\b/gi;
const MATERIAL_CLAIM_PATTERN =
  /\b(?:hipaa|pci|soc\s*2|gdpr|compliant|patient|billing|evaluation frameworks?|safety evaluations?|safety guardrails?|agent reliability|edge-case behavior|accuracy)\b/gi;
const CLAIM_SCAFFOLD_TOKENS = new Set([
  "adjacent", "also", "are", "aspects", "direct", "draft",
  "drafts", "durable", "gave", "guarded", "integration",
  "incident", "integrations", "involved", "issue", "its", "message", "most", "one",
  "orchestrate", "orchestration", "patterns", "rather", "state",
  "than", "them", "thing", "those", "tools", "track", "tracking", "transferable",
  "use", "used", "uses", "useful", "while"
]);
const CANDIDATE_OWNERSHIP_PATTERN =
  /\bi(?:'ve| have)?\s+(?:build|built|create|created|develop|developed|deliver|delivered|implement|implemented|design|designed|automate|automated|resolve|resolved|fix|fixed|diagnose|diagnosed|write|wrote|author|authored|maintain|maintained|ship|shipped|integrate|integrated|use|used|add|added|rebuild|rebuilt)\b/i;
const NON_MATERIAL_CONVERSATION_PATTERN =
  /^i\s+(?:can|would be happy to)\s+(?:walk through|discuss|share|explain)\b/i;

function groundingRoots(token) {
  const normalized = String(token || "")
    .toLowerCase()
    .replace(/[.]+$/, "");
  const roots = new Set([normalized]);
  const irregular = {
    automation: "automate",
    automations: "automate",
    built: "build",
    fixed: "diagnose",
    fixing: "diagnose",
    generation: "generate",
    resolved: "diagnose",
    wrote: "write",
    written: "write",
    gave: "give",
    won: "win"
  };
  if (irregular[normalized]) roots.add(irregular[normalized]);
  if (normalized.endsWith("ies") && normalized.length > 4) {
    roots.add(`${normalized.slice(0, -3)}y`);
  }
  if (normalized.endsWith("ing") && normalized.length > 5) {
    const base = normalized.slice(0, -3);
    roots.add(base);
    roots.add(`${base}e`);
  }
  if (normalized.endsWith("ed") && normalized.length > 4) {
    const base = normalized.slice(0, -2);
    roots.add(base);
    roots.add(`${base}e`);
  }
  if (normalized.endsWith("es") && normalized.length > 4) {
    roots.add(normalized.slice(0, -1));
    roots.add(normalized.slice(0, -2));
  } else if (normalized.endsWith("s") && normalized.length > 3) {
    roots.add(normalized.slice(0, -1));
  }
  return roots;
}

function groundingRootSet(value) {
  return new Set(
    [...proofTokens(value)].flatMap((token) => [...groundingRoots(token)])
  );
}

function tokenIsGrounded(token, authoritativeRoots, allowedRoots = new Set()) {
  if (CLAIM_SCAFFOLD_TOKENS.has(token)) return true;
  return [...groundingRoots(token)].some(
    (root) => authoritativeRoots.has(root) || allowedRoots.has(root)
  );
}

function adjacentRootsAllowedInSentence(sentence, pack) {
  const allowed = new Set();
  if (!ADJACENT_QUALIFIER_PATTERN.test(sentence)) return allowed;
  for (const coverage of pack?.requirement_coverage ?? []) {
    if (coverage.classification !== "adjacent") continue;
    const elementTokens = [...proofTokens(coverage.element)];
    if (
      elementTokens.some((token) =>
        includesAlias(sentence, [token.toLowerCase()])
      )
    ) {
      const allowedTokens = [
        ...elementTokens,
        ...proofTokens((coverage.material_differences ?? []).join(" "))
      ];
      for (const token of allowedTokens) {
        groundingRoots(token).forEach((root) => allowed.add(root));
      }
    }
  }
  return allowed;
}

function messageBodySentences(message) {
  const lines = String(message || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => {
      const normalized = normalizeText(line);
      if (!/^(?:(?:linkedin|github|portfolio)\s*:\s*)?https?:\/\//i.test(normalized)) {
        return normalized;
      }
      // Contact-only lines are presentation, but prose appended to a contact
      // URL is still application content and must pass claim grounding.
      return normalizeText(
        normalized.replace(
          /^(?:(?:linkedin|github|portfolio)\s*:\s*)?https?:\/\/\S+\s*(?:[-–—:;]\s*)?/i,
          ""
        )
      );
    })
    .filter(Boolean);
  const body = lines
    .slice(1)
    .filter(
      (line) =>
        !/^(?:hi|hello|dear)\b(?:\s+(?:there|hiring team|team|sir|madam)){0,2}[,!]?$/i.test(
          line
        ) &&
        line !== "I would welcome a conversation about how my experience fits this role."
    )
    .join(" ");
  return (
    body.match(/.*?(?:[.!?]+(?:["'’”\)\]]+)?(?=\s|$)|$)/g) ?? []
  )
    .map((sentence) => normalizeText(sentence))
    .filter(Boolean);
}

const CLAIM_CLAUSE_BOUNDARY =
  /\s*;\s*|\bthat\s+(?=(?:collect|collects|generate|generates|archive|archives)\b)|,\s+(?=(?:and|but|while)\s+)|,\s+(?=(?:and\s+)?(?:the\s+)?[A-Za-z0-9.+#-]+(?:\s+[A-Za-z0-9.+#-]+){0,2}\s+API\s+(?:to|for)\b)|\s+(?:and|but)\s+(?=(?:i|we|it|they|this|that|the|is|are|was|were|has|have|build|built|maintain|maintained|diagnose|diagnosed|resolve|resolved|fix|fixed|create|created|develop|developed|deliver|delivered|implement|implemented|design|designed|automate|automated|write|wrote|author|authored|ship|shipped|integrate|integrated|add|added|rebuild|rebuilt|collect|collects|generate|generated|generates|archive|archives|restore|restored|reduce|reduced)\b)/i;

function claimClauses(value) {
  return normalizeText(value)
    .split(CLAIM_CLAUSE_BOUNDARY)
    .map((clause) => normalizeText(clause).replace(/^(?:and|but|while)\s+/i, ""))
    .filter(Boolean);
}

function proofFactClauses(value) {
  return normalizeText(value)
    .replace(
      /\bthat\s+(?=(?:collects?|generates?|archives?|writes?|resolves?|diagnoses?|restores?|reduces?|replaces?|removes?|saves?)\b)/gi,
      "; "
    )
    .replace(
      /,\s+(?:and\s+)?(?=(?:collects?|generates?|archives?|writes?|resolves?|diagnoses?|restores?|reduces?|replaces?|removes?|saves?)\b)/gi,
      "; "
    )
    .split(
      /\s*;\s*|\s+and\s+(?=(?:wrote|authored|resolved|rebuilt|delivered)\b)/i
    )
    .map((clause) => normalizeText(clause).replace(/^and\s+/i, ""))
    .filter(Boolean);
}

function proofGroundingModels(proof, profile) {
  const lines = String(proof?.evidence || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map(normalizeText)
    .filter(Boolean);
  const attributes = [];
  const facts = [];
  for (const line of lines) {
    if ([...proofTokens(line)].length <= 5) {
      attributes.push(line);
      continue;
    }
    facts.push(...proofFactClauses(line));
  }
  const identity = `${proof?.reference || ""} ${proof?.label || ""} ${
    profile.candidate.name
  } ${profile.candidate.location}`;
  const identityRoots = groundingRootSet(identity);
  const model = (kind, text) => {
    const roots = new Set(identityRoots);
    groundingRootSet(text).forEach((root) => roots.add(root));
    return { kind, roots };
  };
  return [
    model("identity", ""),
    model("attributes", attributes.join(" ")),
    ...facts.map((fact) => model("fact", fact)),
    model("overview", `${attributes.join(" ")} ${facts.join(" ")}`)
  ];
}

const ATTRIBUTE_RELATION_PATTERN =
  /\b(?:archive|archived|archives|build|built|collect|collected|collects|create|created|deliver|delivered|diagnose|diagnosed|generate|generated|generates|implement|implemented|rebuild|rebuilt|reduce|reduced|remove|removed|resolve|resolved|restore|restored|save|saved|write|writes|wrote)\b/i;
const OVERVIEW_CLAIM_PATTERN =
  /\b(?:build|built|create|created|develop|developed)\b[^.!?]{0,160}\b(?:application|automation|marketplace|platform|project|system|workflow)\b/i;
const PRECISE_RELATION_PATTERN =
  /\b(?:archive|archived|archives|collect|collected|collects|deliver|delivered|diagnose|diagnosed|generate|generated|generates|rebuild|rebuilt|reduce|reduced|remove|removed|resolve|resolved|restore|restored|save|saved|write|writes|wrote)\b/i;

function groundingModelEligible(model, clause) {
  if (model.kind === "attributes") {
    return !ATTRIBUTE_RELATION_PATTERN.test(clause);
  }
  if (model.kind === "overview") {
    return (
      OVERVIEW_CLAIM_PATTERN.test(clause) &&
      !PRECISE_RELATION_PATTERN.test(
        clause.replace(/\b(?:build|built)\b/i, "")
      )
    );
  }
  return true;
}

const ASSOCIATION_NUMBER_WORDS = new Set([
  "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
  "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
  "sixteen", "seventeen", "eighteen", "nineteen", "twenty", "thirty",
  "forty", "fifty", "sixty", "seventy", "eighty", "ninety", "hundred",
  "thousand", "million", "billion"
]);
const ASSOCIATION_STOP_WORDS = new Set([
  "a", "an", "and", "approximately", "as", "at", "by", "for", "from", "i",
  "in", "into", "my", "of", "on", "or", "the", "to", "using", "with"
]);

function associationTokens(value) {
  return (
    normalizeText(value).toLowerCase().match(/[a-z0-9+#.]+/g) ?? []
  ).filter((token) => !ASSOCIATION_STOP_WORDS.has(token));
}

function isAssociationNumber(token) {
  return /^\d+(?:[.,]\d+)?(?:\+|%|ms)?$/.test(token) ||
    ASSOCIATION_NUMBER_WORDS.has(token);
}

function numericAssociationsGrounded(clause, evidence) {
  const claimTokens = associationTokens(clause);
  const evidenceTokens = associationTokens(evidence);
  for (const [index, token] of claimTokens.entries()) {
    if (!isAssociationNumber(token)) continue;
    if (
      token === "one" &&
      ["example", "issue", "project", "thing"].includes(claimTokens[index + 1])
    ) {
      continue;
    }
    const claimContext = claimTokens
      .slice(Math.max(0, index - 2), index)
      .concat(claimTokens.slice(index + 1, index + 3))
      .filter((entry) => !isAssociationNumber(entry));
    const requiredOverlap = Math.min(1, new Set(claimContext).size);
    if (requiredOverlap === 0) return false;
    const matched = evidenceTokens.some((entry, evidenceIndex) => {
      if (entry !== token) return false;
      const claimDirectional = claimTokens
        .slice(index + 1, index + 4)
        .filter((context) => !isAssociationNumber(context));
      const evidenceDirectional = evidenceTokens
        .slice(evidenceIndex + 1, evidenceIndex + 4)
        .filter((context) => !isAssociationNumber(context));
      const directionalSource =
        claimDirectional.length > 0
          ? claimDirectional
          : claimTokens
              .slice(Math.max(0, index - 3), index)
              .filter((context) => !isAssociationNumber(context));
      const directionalTarget =
        evidenceDirectional.length > 0
          ? evidenceDirectional
          : evidenceTokens
              .slice(Math.max(0, evidenceIndex - 3), evidenceIndex)
              .filter((context) => !isAssociationNumber(context));
      const directionalRoots = groundingRootSet(directionalTarget.join(" "));
      if (
        !directionalSource.some((context) =>
          [...groundingRoots(context)].some((root) =>
            directionalRoots.has(root)
          )
        )
      ) {
        return false;
      }
      const evidenceRoots = groundingRootSet(
        evidenceTokens
          .slice(Math.max(0, evidenceIndex - 2), evidenceIndex)
          .concat(evidenceTokens.slice(evidenceIndex + 1, evidenceIndex + 3))
          .filter((context) => !isAssociationNumber(context))
          .join(" ")
      );
      const overlap = claimContext.filter((context) =>
        [...groundingRoots(context)].some((root) => evidenceRoots.has(root))
      ).length;
      return overlap >= requiredOverlap;
    });
    if (!matched) return false;
  }
  return true;
}

function coverageProofRecords(coverage, pack, profile) {
  const selected = new Map(
    (pack?.selected_proofs ?? []).map((proof) => [
      proof.reference,
      { ...proof, text: proof.text ?? proof.evidence ?? "" }
    ])
  );
  const canonical = new Map(
    proofCandidates(profile).map((proof) => [proof.reference, proof])
  );
  return (coverage.evidence_refs ?? [])
    .map((reference) => selected.get(reference) ?? canonical.get(reference))
    .filter(Boolean);
}

function proofTechnologySignals(coverage, pack, profile) {
  const signals = [];
  for (const reference of coverage.evidence_refs ?? []) {
    const projectId = reference.match(/^projects:(.+)$/)?.[1];
    if (projectId) {
      const project = profile.projects.find((entry) => entry.id === projectId);
      if (project) signals.push(project.name, ...(project.technologies ?? []));
    }
    const experienceId = reference.match(/^experience:(.+)$/)?.[1];
    if (experienceId) {
      const experience = profile.experience.find((entry) => entry.id === experienceId);
      if (experience) {
        signals.push(
          experience.organization,
          ...knownSkillsInText(profileEvidenceText(experience), profile)
        );
      }
    }
  }
  return [...new Set(signals.map(normalizeText).filter(Boolean))];
}

function relevantSummarySentences(message, evidenceRefs, pack, profile) {
  const coverage = { evidence_refs: evidenceRefs };
  const proofs = coverageProofRecords(coverage, pack, profile);
  const proofTokenSet = proofTokens(proofs.map((proof) => proof.text).join(" "));
  const labels = proofs.map((proof) => normalizeText(proof.label).toLowerCase());
  return messageBodySentences(message).filter((sentence) => {
    const normalized = sentence.toLowerCase();
    if (labels.some((label) => label && normalized.includes(label))) return true;
    const overlap = [...proofTokens(sentence)].filter((token) =>
      proofTokenSet.has(token)
    ).length;
    return overlap >= 3;
  });
}

function relevantSummaryParagraphs(message, evidenceRefs, pack, profile) {
  const coverage = { evidence_refs: evidenceRefs };
  const proofs = coverageProofRecords(coverage, pack, profile);
  const proofTokenSet = proofTokens(proofs.map((proof) => proof.text).join(" "));
  const labels = proofs.map((proof) => normalizeText(proof.label).toLowerCase());
  return String(message || "")
    .replace(/\r\n?/g, "\n")
    .split(/\n\s*\n/)
    .map((paragraph) => normalizeText(paragraph))
    .filter(
      (paragraph) =>
        paragraph &&
        !paragraph.startsWith("Subject line:") &&
        !/^(?:hi|hello|dear)\b.*[,!]$/i.test(paragraph) &&
        paragraph !==
          "I would welcome a conversation about how my experience fits this role." &&
        !/^https?:\/\//i.test(paragraph)
    )
    .filter((paragraph) => {
      const normalized = paragraph.toLowerCase();
      if (labels.some((label) => label && normalized.includes(label))) return true;
      const overlap = [...proofTokens(paragraph)].filter((token) =>
        proofTokenSet.has(token)
      ).length;
      return overlap >= 3;
    });
}

function requirementCoverageErrors(message, pack, profile) {
  const errors = [];
  const normalized = normalizeText(message);
  const urls = new Set(extractUrls(normalized));
  const planned = new Map(
    (pack?.message_plan?.requirements ?? []).map((requirement) => [
      requirement.requirement_id,
      requirement
    ])
  );
  const lines = String(message || "")
    .split(/\r?\n/)
    .map((line) => normalizeText(line))
    .filter(Boolean);

  for (const requirement of pack?.message_plan?.requirements ?? []) {
    if (!requirement.required) continue;
    if (requirement.disposition === "missing") {
      errors.push(`mandatory requirement lacks approved evidence: ${requirement.requirement_id}`);
      continue;
    }
    if (requirement.disposition === "manual_action") continue;
    if (
      Array.isArray(requirement.approved_urls) &&
      requirement.approved_urls.length > 0 &&
      !requirement.approved_urls.some((url) => urls.has(url))
    ) {
      errors.push(`required approved link is missing: ${requirement.requirement_id}`);
    }
    if (requirement.format_value) {
      const expected = requirement.format_value.replace(/[.!]+$/, "").toLowerCase();
      const bodyFirstLine = (lines[1] ?? "").replace(/[.!]+$/, "").toLowerCase();
      if (bodyFirstLine !== expected) {
        errors.push(`required message format is missing: ${requirement.format_value}`);
      }
    }
    const relevantSentences = relevantSummarySentences(
      message,
      requirement.evidence_refs,
      pack,
      profile
    );
    const countValues = {
      sentence_count: relevantSentences.length,
      word_count: relevantSentences
        .join(" ")
        .match(/[\p{L}\p{N}+#.]+/gu)?.length ?? 0,
      paragraph_count: relevantSummaryParagraphs(
        message,
        requirement.evidence_refs,
        pack,
        profile
      ).length
    };
    for (const [constraintName, unit] of [
      ["sentence_count", "sentences"],
      ["word_count", "words"],
      ["paragraph_count", "paragraphs"]
    ]) {
      const constraint = requirement.constraints?.[constraintName];
      if (!constraint) continue;
      const count = countValues[constraintName];
      if (count < constraint.minimum || count > constraint.maximum) {
        errors.push(
          `required project summary must contain ${constraint.minimum}-${constraint.maximum} relevant ${unit}; found ${count}`
        );
      }
    }
  }

  for (const coverage of pack?.requirement_coverage ?? []) {
    if (!coverage.required || coverage.classification === "manual_action") continue;
    if (coverage.classification === "missing") continue;
    const requirement = planned.get(coverage.requirement_id);
    if (!requirement) continue;
    const signals = proofTechnologySignals(coverage, pack, profile);
    const proofLabels = coverageProofRecords(coverage, pack, profile).map(
      (proof) => proof.label
    );
    const hasSignal = (signal) =>
      signal && includesAlias(normalized, [signal.toLowerCase()]);
    if (coverage.element_kind === "named_technology") {
      const requested = coverage.element.replace(/^Use of\s+/i, "");
      if (!hasSignal(requested)) {
        errors.push(`mandatory answer element is missing: ${coverage.element_id}`);
      }
      if (coverage.classification === "adjacent") {
        const actualProviders = [
          ...coverageProofRecords(coverage, pack, profile).flatMap((proof) =>
            proofProviders(proof.text)
          ),
          ...signals
        ].filter(
          (provider) => provider.toLowerCase() !== requested.toLowerCase()
        );
        const explicitDifference = messageBodySentences(message).some(
          (sentence) =>
            hasSignal.call(null, requested) &&
            includesAlias(sentence, [requested.toLowerCase()]) &&
            actualProviders.some((provider) =>
              includesAlias(sentence, [provider.toLowerCase()])
            ) &&
            ADJACENT_QUALIFIER_PATTERN.test(sentence)
        );
        if (
          !explicitDifference
        ) {
          errors.push(`adjacent material difference is not explicit: ${coverage.element_id}`);
        }
      }
    } else if (coverage.element_kind === "agentic_workflow") {
      if (
        !/\b(?:workflow|automation|pipeline)\b/i.test(normalized) ||
        !proofLabels.some(hasSignal)
      ) {
        errors.push(`mandatory workflow example is missing: ${coverage.element_id}`);
      }
      if (
        coverage.classification === "adjacent" &&
        !messageBodySentences(message).some(
          (sentence) =>
            /\b(?:workflow|automation|pipeline)\b/i.test(sentence) &&
            /\b(?:not|rather than|instead of)\b[^.!?]{0,80}\b(?:agentic|multi-agent|autonomous agent)\b/i.test(
              sentence
            )
        )
      ) {
        errors.push(`adjacent material difference is not explicit: ${coverage.element_id}`);
      }
    } else if (coverage.element_kind === "tools_integrations") {
      const proofLabelSet = new Set(proofLabels.map((label) => label.toLowerCase()));
      if (
        signals.filter(
          (signal) =>
            !proofLabelSet.has(signal.toLowerCase()) && hasSignal(signal)
        ).length < 2
      ) {
        errors.push(`mandatory tools or integrations are missing: ${coverage.element_id}`);
      }
    } else if (
      ["ai_project", "project_summary"].includes(coverage.element_kind) &&
      !proofLabels.some(hasSignal)
    ) {
      errors.push(`mandatory concrete project is missing: ${coverage.element_id}`);
    } else if (coverage.element_kind === "production_status") {
      if (coverage.classification === "exact" && !/\bproduction\b/i.test(normalized)) {
        errors.push(`mandatory production evidence is missing: ${coverage.element_id}`);
      }
      if (
        coverage.classification === "partial" &&
        !/\bpre-launch\b/i.test(normalized)
      ) {
        errors.push(`partial production status is not explicit: ${coverage.element_id}`);
      }
    } else if (coverage.element_kind === "domain") {
      const requested = coverage.element.replace(/\s+domain$/i, "");
      if (!hasSignal(requested)) {
        errors.push(`mandatory domain element is missing: ${coverage.element_id}`);
      }
      if (
        coverage.classification === "adjacent" &&
        !messageBodySentences(message).some((sentence) => {
          const actualDomains = [...DOMAIN_PATTERNS]
            .filter(
              ([domain, pattern]) => domain !== requested &&
                coverageProofRecords(coverage, pack, profile).some((proof) =>
                  pattern.test(proof.text)
                )
            )
            .map(([domain]) => domain);
          return (
            includesAlias(sentence, [requested.toLowerCase()]) &&
            actualDomains.some((domain) =>
              includesAlias(sentence, [domain.toLowerCase()])
            ) &&
            ADJACENT_QUALIFIER_PATTERN.test(sentence)
          );
        })
      ) {
        errors.push(`adjacent material difference is not explicit: ${coverage.element_id}`);
      }
    } else if (
      coverage.element_kind === "incident_resolution" &&
      !/\b(?:resolved|fixed|diagnosed|restored|reduced)\b/i.test(normalized)
    ) {
      errors.push(`mandatory incident example is missing: ${coverage.element_id}`);
    }
  }
  return errors;
}

function claimGroundingErrors(message, pack, profile) {
  const errors = [];
  if (!pack) return errors;
  if (!Array.isArray(pack?.selected_proofs) || pack.selected_proofs.length === 0) {
    return ["candidate claims require at least one selected approved proof"];
  }
  const selectedText = (pack?.selected_proofs ?? [])
    .map((proof) => proof.evidence)
    .join(" ");
  const proofModels = (pack?.selected_proofs ?? []).map((proof) => ({
    reference: proof.reference,
    evidence: proof.evidence,
    models: proofGroundingModels(proof, profile)
  }));
  for (const sentence of messageBodySentences(message)) {
    if (NON_MATERIAL_CONVERSATION_PATTERN.test(sentence)) {
      continue;
    }
    const allowedAdjacentRoots = adjacentRootsAllowedInSentence(sentence, pack);
    for (const clause of claimClauses(sentence)) {
      const tokens = [...proofTokens(clause)];
      const matchingProof = proofModels.find((proof) =>
        numericAssociationsGrounded(clause, proof.evidence) &&
        proof.models.some(
          (model) =>
            groundingModelEligible(model, clause) &&
            tokens.every((token) =>
              tokenIsGrounded(token, model.roots, allowedAdjacentRoots)
            )
        )
      );
      if (!matchingProof) {
        errors.push(
          `candidate claim contains unsupported terms or a cross-proof association: ${clause.slice(
            0,
            120
          )}`
        );
      }
    }
  }

  const selectedLower = selectedText.toLowerCase();
  for (const match of normalizeText(message).matchAll(MATERIAL_CLAIM_PATTERN)) {
    if (!selectedLower.includes(match[0].toLowerCase())) {
      errors.push(`unsupported material claim: ${match[0]}`);
    }
  }
  MATERIAL_CLAIM_PATTERN.lastIndex = 0;

  for (const match of normalizeText(message).matchAll(UNSUPPORTED_FREQUENCY_PATTERN)) {
    if (!selectedLower.includes(match[0].toLowerCase())) {
      errors.push(`unsupported frequency or universality claim: ${match[0]}`);
    }
  }
  UNSUPPORTED_FREQUENCY_PATTERN.lastIndex = 0;

  for (const provider of proofProviders(message)) {
    if (proofProviders(selectedText).some((value) => value.toLowerCase() === provider.toLowerCase())) {
      continue;
    }
    const adjacent = (pack?.requirement_coverage ?? []).some(
      (coverage) =>
        coverage.classification === "adjacent" &&
        coverage.element.toLowerCase().includes(provider.toLowerCase()) &&
        ADJACENT_QUALIFIER_PATTERN.test(normalizeText(message))
    );
    if (!adjacent) errors.push(`unsupported provider or tool claim: ${provider}`);
  }
  for (const [domain, pattern] of DOMAIN_PATTERNS) {
    if (pattern.test(message) && !pattern.test(selectedText)) {
      const adjacent = (pack?.requirement_coverage ?? []).some(
        (coverage) =>
          coverage.classification === "adjacent" &&
          coverage.element.toLowerCase().includes(domain) &&
          ADJACENT_QUALIFIER_PATTERN.test(normalizeText(message))
      );
      if (!adjacent) errors.push(`unsupported domain claim: ${domain}`);
    }
  }
  return errors;
}

function hasGroundedCandidateContent(message, pack, profile) {
  const canonicalProofs = new Map(
    proofCandidates(profile).map((proof) => [proof.reference, proof])
  );
  const evidence = (pack?.selected_proof_refs ?? [])
    .map((reference) => canonicalProofs.get(reference))
    .filter(Boolean)
    .map((proof) => `${proof.label || ""} ${proof.text || ""}`)
    .join(" ");
  const evidenceRoots = groundingRootSet(evidence);
  return messageBodySentences(message).some((sentence) => {
    if (!CANDIDATE_OWNERSHIP_PATTERN.test(sentence)) return false;
    const tokens = [...proofTokens(sentence)];
    const overlap = tokens.filter((token) =>
      [...groundingRoots(token)].some((root) => evidenceRoots.has(root))
    ).length;
    return tokens.length >= 4 && overlap >= 3;
  });
}

function validateGeneratedMessage(message, { job, profile, policy, pack }) {
  const errors = [];
  const rawMessage = String(message || "");
  const output = normalizeText(rawMessage.slice(0, 100000));
  if (rawMessage.length > 100000) errors.push("message exceeds the processing limit");
  const firstLine =
    String(message || "")
      .split(/\r?\n/)
      .map((line) => normalizeText(line))
      .find(Boolean) ?? "";
  if (!output) return { valid: false, errors: ["message is empty"] };

  const nonEmptyLines = rawMessage
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => normalizeText(line))
    .filter(Boolean);
  const hasFormatOverride = (pack?.message_plan?.requirements ?? []).some(
    (requirement) => requirement.required && requirement.format_value
  );
  if (
    pack?.message_plan &&
    !hasFormatOverride &&
    !/^(?:hi|hello|dear)\b.*[,!]$/i.test(nonEmptyLines[1] ?? "")
  ) {
    errors.push("message must include a greeting after the subject line");
  }
  if (
    pack?.message_plan &&
    !nonEmptyLines.includes(
      "I would welcome a conversation about how my experience fits this role."
    )
  ) {
    errors.push("message must include the required truthful closing");
  }

  if (/\*\*|__|^\s*```|^\s{0,3}#{1,6}\s+/m.test(rawMessage)) {
    errors.push("Markdown formatting is not allowed");
  }
  if (/^\s*(?:Question|Answer)\s*:/im.test(rawMessage)) {
    errors.push("Question/Answer labels are not allowed");
  }

  const words = output.split(/\s+/).filter(Boolean);
  if (words.length > policy.max_body_words) {
    errors.push(`message exceeds ${policy.max_body_words} words`);
  }

  const approvedProjects = new Set(policy.approved_project_ids);
  const approvedUrls = new Set([
    ...policy.approved_candidate_url_keys.map((key) => profile.candidate.links[key]),
    ...profile.projects.filter((project) => approvedProjects.has(project.id)).map((project) => project.url)
  ]);
  for (const url of extractUrls(output)) {
    if (!approvedUrls.has(url)) errors.push(`unapproved URL: ${url}`);
  }

  for (const technology of UNSUPPORTED_TECHNOLOGIES) {
    if (
      includesAlias(output, [technology.toLowerCase()]) &&
      !approvedSkillNames(profile).some((skill) => skill.toLowerCase() === technology.toLowerCase())
    ) {
      errors.push(`unsupported skill: ${technology}`);
    }
  }

  const hasScheduleCommitment = SCHEDULE_COMMITMENT_PATTERNS.some((pattern) => {
    pattern.lastIndex = 0;
    return pattern.test(output);
  });
  if (hasScheduleCommitment) {
    errors.push("unsupported availability or schedule commitment");
  }
  if (SALARY_COMMITMENT_PATTERN.test(output)) {
    errors.push("unsupported salary commitment");
  }
  SALARY_COMMITMENT_PATTERN.lastIndex = 0;
  if (START_DATE_COMMITMENT_PATTERN.test(output)) {
    errors.push("unsupported start-date commitment");
  }
  START_DATE_COMMITMENT_PATTERN.lastIndex = 0;

  const authoritativeNumericEvidence = profileEvidenceText(profile);
  const approvedNumbers = new Set([
    ...numericTokens(authoritativeNumericEvidence),
    ...numberWordTokens(authoritativeNumericEvidence)
  ]);
  const numericClaimText = removeMatches(
    output,
    SCHEDULE_COMMITMENT_PATTERNS
  );
  for (const token of [
    ...numericTokens(numericClaimText),
    ...numberWordTokens(numericClaimText)
  ]) {
    if (!approvedNumbers.has(token)) errors.push(`unsupported numeric claim: ${token}`);
  }

  const messageWithoutUrls = numericClaimText.replace(
    /https?:\/\/\S+/gi,
    ""
  );
  if (/(?:\+?\d[\s().-]*){7,}/.test(messageWithoutUrls)) errors.push("phone numbers are not approved");

  for (const phrase of policy.banned_phrases ?? []) {
    if (output.toLowerCase().includes(phrase.toLowerCase())) {
      errors.push(`banned phrase: ${phrase}`);
    }
  }
  if (COMPLETION_CLAIM_PATTERN.test(output)) {
    errors.push("unsupported completion or submission claim");
  }
  COMPLETION_CLAIM_PATTERN.lastIndex = 0;
  if (INTERNAL_CONTEXT_PATTERN.test(output)) {
    errors.push("internal application context is not allowed");
  }
  INTERNAL_CONTEXT_PATTERN.lastIndex = 0;
  if (!(pack?.requirement_coverage?.length > 0)) {
    errors.push(...screeningAnswerErrors(rawMessage, pack));
  }
  errors.push(...requirementCoverageErrors(rawMessage, pack, profile));
  errors.push(...claimGroundingErrors(rawMessage, pack, profile));
  if (
    (pack?.selected_proofs?.length ?? 0) > 0 &&
    !hasGroundedCandidateContent(rawMessage, pack, profile)
  ) {
    errors.push("message lacks evidence-grounded candidate content");
  }
  if (pack?.application_pack_status === "ready" && pack?.message_plan?.subject_line) {
    if (firstLine !== normalizeText(pack.message_plan.subject_line)) {
      errors.push(
        `required subject value is missing or does not match the complete first line: ${pack.message_plan.subject_line}`
      );
    }
  } else {
    for (const instruction of pack?.application_instructions ?? []) {
      if (
        instruction.type === "subject" &&
        pack.application_pack_status === "ready" &&
        instruction.required &&
        instruction.value &&
        !firstLine
          .toLowerCase()
          .includes(instruction.value.toLowerCase())
      ) {
        errors.push(`required subject value is missing: ${instruction.value}`);
      }
    }
  }
  const uniqueErrors = [...new Set(errors)];
  return {
    valid: uniqueErrors.length === 0,
    errors: uniqueErrors
  };
}

function applyNonReadyApplicationPack(
  record,
  pack,
  profile,
  packPolicy,
  now = new Date().toISOString()
) {
  const packErrors = validateApplicationPack(pack, profile, packPolicy);
  if (
    !["review_required", "blocked"].includes(
      pack?.application_pack_status
    ) ||
    packErrors.length > 0
  ) {
    throw new Error(
      `Invalid non-ready application pack: ${[
        ...(!["review_required", "blocked"].includes(
          pack?.application_pack_status
        )
          ? ["application_pack_status must require review or be blocked"]
          : []),
        ...packErrors
      ].join("; ")}`
    );
  }
  const warningSummary = (pack.application_warnings ?? [])
    .map((warning) => warning.summary)
    .filter(Boolean)
    .join("; ");
  return releaseClaim(
    {
      ...record,
      application_instructions: pack.application_instructions,
      screening_questions: pack.screening_questions,
      requirement_coverage: pack.requirement_coverage,
      application_message_plan: [pack.message_plan],
      selected_proof_refs: pack.selected_proof_refs,
      application_warnings: pack.application_warnings,
      application_pack_status: pack.application_pack_status,
      application_pack_version: packPolicy.pack_version,
      application_pack_profile_version: profile.profile_version,
      application_pack_policy_version: packPolicy.policy_version,
      coverage_contract_version: pack.coverage_contract_version,
      message_plan_version: pack.message_plan.version,
      application_pack_generated_at: pack.application_pack_generated_at || now,
      pipeline_status: "review_required",
      error_category: "application_pack_not_ready",
      error_summary: sanitizeError(
        warningSummary || "Application pack requires manual review."
      ),
      failed_stage: "generation",
      next_retry_at: "",
      manual_action: "",
      updated_at: now
    },
    record.processing_token,
    now
  );
}

function applyGeneratedApplicationPack(
  record,
  pack,
  message,
  profile,
  applicationPolicy,
  packPolicy,
  now = new Date().toISOString()
) {
  const cleanedMessage = cleanGeneratedMessage(message);
  const packErrors = validateApplicationPack(pack, profile, packPolicy);
  const messageValidation = validateGeneratedMessage(cleanedMessage, {
    job: record,
    profile,
    policy: applicationPolicy,
    pack
  });
  if (
    pack.application_pack_status !== "ready" ||
    packErrors.length > 0 ||
    !messageValidation.valid
  ) {
    throw new Error(
      `Invalid application pack: ${[
        ...(pack.application_pack_status === "ready"
          ? []
          : ["application_pack_status must be ready"]),
        ...packErrors,
        ...messageValidation.errors
      ].join("; ")}`
    );
  }
  return releaseClaim(
    {
      ...record,
      application_instructions: pack.application_instructions,
      screening_questions: pack.screening_questions,
      requirement_coverage: pack.requirement_coverage,
      application_message_plan: [pack.message_plan],
      selected_proof_refs: pack.selected_proof_refs,
      application_warnings: pack.application_warnings,
      application_pack_status: pack.application_pack_status,
      application_pack_version: packPolicy.pack_version,
      application_pack_profile_version: profile.profile_version,
      application_pack_policy_version: packPolicy.policy_version,
      coverage_contract_version: pack.coverage_contract_version,
      message_plan_version: pack.message_plan.version,
      application_pack_generated_at: now,
      pipeline_status: "ready",
      generated_message: cleanedMessage,
      message_profile_version: profile.profile_version,
      message_policy_version: applicationPolicy.policy_version,
      message_validation_status: "valid",
      generated_at: now,
      error_category: "",
      error_summary: "",
      failed_stage: "",
      next_retry_at: "",
      manual_action: "",
      updated_at: now
    },
    record.processing_token,
    now
  );
}

function applyGeneratedMessage(
  record,
  message,
  profile,
  now = new Date().toISOString()
) {
  const cleanedMessage = cleanGeneratedMessage(message);
  return releaseClaim(
    {
      ...record,
      pipeline_status: "ready",
      generated_message: cleanedMessage,
      message_profile_version: profile.profile_version,
      message_validation_status: "valid",
      generated_at: now,
      error_category: "",
      error_summary: "",
      failed_stage: "",
      next_retry_at: "",
      manual_action: "",
      updated_at: now
    },
    record.processing_token,
    now
  );
}


function hydratedPersistedPack(record, profile) {
  const planEntries = Array.isArray(record?.application_message_plan)
    ? record.application_message_plan
    : [];
  const messagePlan =
    planEntries.length === 1 &&
    planEntries[0] &&
    typeof planEntries[0] === "object" &&
    !Array.isArray(planEntries[0])
      ? planEntries[0]
      : null;
  const selectedProofs = (record?.selected_proof_refs ?? [])
    .map((reference) => {
      const [kind, id] = String(reference).split(":");
      const entry =
        kind === "projects"
          ? profile.projects?.find((project) => project.id === id)
          : kind === "experience"
            ? profile.experience?.find((experience) => experience.id === id)
            : null;
      if (!entry) return null;
      return {
        reference,
        label:
          kind === "projects"
            ? entry.name
            : `${entry.title} — ${entry.organization}`,
        evidence: profileEvidenceText(entry)
      };
    })
    .filter(Boolean);
  return {
    ...record,
    message_plan: messagePlan,
    selected_proofs: selectedProofs
  };
}

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, stableValue(value[key])])
    );
  }
  return value;
}

function sameContractValue(left, right) {
  return JSON.stringify(stableValue(left)) === JSON.stringify(stableValue(right));
}

function evaluatePersistedMessageSafety(
  record,
  { profile, applicationPolicy, packPolicy } = {}
) {
  if (!profile || !applicationPolicy || !packPolicy) {
    return {
      safe: false,
      reasons: ["message_safety_configuration_missing"]
    };
  }

  const reasons = [];
  if (record?.pipeline_status !== "ready_to_apply") {
    reasons.push("message_owner_not_to_apply");
  }
  if (record?.prep_status !== "message_ready") {
    reasons.push("preparation_not_message_ready");
  }
  const messageProfileVersion = String(
    record?.message_profile_version || ""
  ).trim();
  if (messageProfileVersion === "legacy/unknown") {
    reasons.push("message_profile_legacy");
  } else if (!messageProfileVersion) {
    reasons.push("message_profile_missing");
  } else if (messageProfileVersion !== profile.profile_version) {
    reasons.push("message_profile_mismatch");
  }

  const messagePolicyVersion = String(
    record?.message_policy_version || ""
  ).trim();
  if (!messagePolicyVersion) {
    reasons.push("message_policy_missing");
  } else if (messagePolicyVersion !== applicationPolicy.policy_version) {
    reasons.push("message_policy_mismatch");
  }
  if (record?.message_validation_status !== "valid") {
    reasons.push("message_validation_not_valid");
  }
  if (!String(record?.generated_message || "").trim()) {
    reasons.push("message_missing");
  }

  if (record?.application_pack_status !== "ready") {
    reasons.push("pack_status_not_ready");
  }
  if (record?.application_pack_version !== packPolicy.pack_version) {
    reasons.push("pack_version_mismatch");
  }
  if (
    record?.application_pack_profile_version !== profile.profile_version
  ) {
    reasons.push("pack_profile_mismatch");
  }
  if (
    record?.application_pack_policy_version !== packPolicy.policy_version
  ) {
    reasons.push("pack_policy_mismatch");
  }
  if (record?.coverage_contract_version !== packPolicy.coverage_contract_version) {
    reasons.push("coverage_version_mismatch");
  }
  if (record?.message_plan_version !== packPolicy.message_plan_version) {
    reasons.push("message_plan_version_mismatch");
  }
  if (!Array.isArray(record?.requirement_coverage)) {
    reasons.push("coverage_missing");
  }
  if (
    !Array.isArray(record?.application_message_plan) ||
    record.application_message_plan.length !== 1
  ) {
    reasons.push("message_plan_missing");
  }

  let canonicalPack = null;
  try {
    canonicalPack = buildApplicationPack(
      { ...record, user_action: "" },
      profile,
      applicationPolicy,
      packPolicy,
      record?.application_pack_generated_at || new Date(0).toISOString()
    );
  } catch {
    reasons.push("pack_recomputation_failed");
  }
  if (canonicalPack) {
    const canonicalFields = [
      ["application_instructions", canonicalPack.application_instructions],
      ["screening_questions", canonicalPack.screening_questions],
      ["requirement_coverage", canonicalPack.requirement_coverage],
      ["application_message_plan", [canonicalPack.message_plan]],
      ["selected_proof_refs", canonicalPack.selected_proof_refs],
      ["application_warnings", canonicalPack.application_warnings],
      ["application_pack_status", canonicalPack.application_pack_status],
      ["application_pack_version", canonicalPack.application_pack_version],
      [
        "application_pack_profile_version",
        canonicalPack.application_pack_profile_version
      ],
      [
        "application_pack_policy_version",
        canonicalPack.application_pack_policy_version
      ],
      ["coverage_contract_version", canonicalPack.coverage_contract_version],
      ["message_plan_version", canonicalPack.message_plan.version]
    ];
    if (
      canonicalFields.some(([field, expected]) =>
        !sameContractValue(record?.[field], expected)
      )
    ) {
      reasons.push("pack_not_canonical");
    }
  }

  const hydratedPack = hydratedPersistedPack(record, profile);
  const packErrors = validateApplicationPack(hydratedPack, profile, packPolicy);
  if (packErrors.length > 0) reasons.push("pack_invalid");
  const messageValidation = validateGeneratedMessage(
    record?.generated_message,
    {
      job: record,
      profile,
      policy: applicationPolicy,
      pack: hydratedPack
    }
  );
  if (!messageValidation.valid) reasons.push("message_content_invalid");

  return {
    safe: reasons.length === 0,
    reasons
  };
}


function normalizeClaimKey(value) {
  return String(value || "")
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
}

function validTimestamp(value) {
  return Number.isFinite(Date.parse(value || ""));
}

function createSystemClaim({
  stage,
  canonicalJobId,
  scope = "",
  executionId,
  now,
  leaseMs
}) {
  const normalizedStage = normalizeClaimKey(stage);
  const normalizedId = normalizeClaimKey(canonicalJobId);
  const normalizedScope = normalizeClaimKey(scope);
  const nowMs = Date.parse(now);
  if (
    !normalizedStage ||
    !normalizedId ||
    !String(executionId || "").trim() ||
    !Number.isFinite(nowMs) ||
    !Number.isInteger(leaseMs) ||
    leaseMs < 1
  ) {
    throw new Error(
      "System claim requires stage, identity, execution, timestamp, and lease"
    );
  }
  const claimKey = [normalizedStage, normalizedId, normalizedScope]
    .filter(Boolean)
    .join(":");
  return {
    claim_key: claimKey,
    canonical_job_id: canonicalJobId,
    stage: normalizedStage,
    token: `${executionId}:${claimKey}`,
    created_at: now,
    expires_at: new Date(nowMs + leaseMs).toISOString()
  };
}

function selectWinningSystemClaims(
  proposedClaims,
  persistedClaims,
  now = new Date().toISOString()
) {
  if (!Array.isArray(proposedClaims) || !Array.isArray(persistedClaims)) {
    throw new Error("System claim collections must be arrays");
  }
  const nowMs = Date.parse(now);
  if (!Number.isFinite(nowMs)) throw new Error("System claim time is invalid");
  const winners = new Map();
  for (const claim of persistedClaims) {
    const key = normalizeClaimKey(claim?.claim_key);
    const rowNumber = Number(claim?.row_number);
    if (
      !key ||
      !String(claim?.token || "").trim() ||
      !Number.isInteger(rowNumber) ||
      rowNumber < 2 ||
      !validTimestamp(claim?.expires_at) ||
      Date.parse(claim.expires_at) <= nowMs
    ) {
      continue;
    }
    const current = winners.get(key);
    if (!current || rowNumber < Number(current.row_number)) {
      winners.set(key, claim);
    }
  }
  return proposedClaims.filter((claim) => {
    const winner = winners.get(normalizeClaimKey(claim?.claim_key));
    return winner?.token === claim?.token;
  });
}

function expiredSystemClaimRows(
  persistedClaims,
  now = new Date().toISOString()
) {
  const nowMs = Date.parse(now);
  if (!Number.isFinite(nowMs)) throw new Error("System claim time is invalid");
  return (Array.isArray(persistedClaims) ? persistedClaims : [])
    .filter((claim) => {
      const rowNumber = Number(claim?.row_number);
      return (
        Number.isInteger(rowNumber) &&
        rowNumber >= 2 &&
        validTimestamp(claim?.expires_at) &&
        Date.parse(claim.expires_at) <= nowMs
      );
    })
    .sort((left, right) => Number(right.row_number) - Number(left.row_number))
    .map((claim) => ({ row_number: Number(claim.row_number) }));
}


function identityKey(value) {
  return String(value || "")
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
}

function sanitize(value, maximum = 240) {
  return String(value || "")
    .replace(/https?:\/\/\S+/gi, "[url]")
    .replace(/[\r\n\t]+/g, " ")
    .trim()
    .slice(0, maximum);
}

function permanentSourceUnavailable(record) {
  if (
    record?.source_availability === "unavailable" ||
    record?.error_category === "source_unavailable"
  ) {
    return true;
  }
  if (record?.pipeline_status !== "error") return false;
  const summary = String(record.error_summary || "");
  return (
    /^\s*(?:404|410)(?:\b|\s*[-:])/u.test(summary) ||
    /\b(?:http|status(?:\s+code)?)\s*[:=-]?\s*(?:404|410)\b/iu.test(
      summary
    )
  );
}

function indexStore(rows, name) {
  if (!Array.isArray(rows)) throw new Error(`${name} rows must be an array`);
  const index = new Map();
  for (const row of rows) {
    const key = identityKey(row?.canonical_job_id);
    if (!key) throw new Error(`${name} contains a row with invalid identity`);
    if (index.has(key)) {
      throw new Error(`${name} contains an ambiguous duplicate identity`);
    }
    index.set(key, row);
  }
  return index;
}

function destinationConflict(actual, destination, reason) {
  if (destination === "To Review" && actual.review_decision) return true;
  if (
    destination === "To Apply" &&
    reason === "review_proceeded" &&
    (actual.pipeline_status !== "ready_to_apply" ||
      actual.review_decision !== "proceed")
  ) return true;
  if (
    destination === "Applied Jobs" &&
    (actual.archive_reason || actual.archived_at)
  ) {
    return true;
  }
  if (
    destination === "Archive" &&
    ((actual.archive_reason && actual.archive_reason !== reason) ||
      actual.applied_at)
  ) {
    return true;
  }
  if (
    ["Scraped Jobs", "To Review", "To Apply"].includes(destination) &&
    (actual.applied_at || actual.archived_at || actual.archive_reason)
  ) {
    return true;
  }
  return false;
}

function validExistingDestination(source, actual, destination, reason, schema) {
  if (!actual || destinationConflict(actual, destination, reason)) return false;
  if (validateRecordStoreContract(actual, destination, schema).length > 0) {
    return false;
  }
  if (actual.state_guard !== stateGuard(actual)) return false;
  if (destination === "To Review") {
    const expectedCase = reviewCaseId(source);
    if (
      actual.review_case_id !== expectedCase ||
      actual.review_case_version !== "review-case-v1" ||
      actual.review_decision ||
      actual.review_decided_at
    ) return false;
  }
  if (destination === "To Apply" && reason === "review_proceeded") {
    const expectedCase = source.review_case_id || reviewCaseId(source);
    if (
      actual.pipeline_status !== "ready_to_apply" ||
      actual.user_action ||
      actual.review_case_id !== expectedCase ||
      actual.review_case_version !== "review-case-v1" ||
      actual.review_decision !== "proceed" ||
      !Number.isFinite(Date.parse(actual.review_decided_at || "")) ||
      actual.review_approved_at !== actual.review_decided_at ||
      actual.review_approval_guard !== applicationReviewGuard(source) ||
      !Number.isInteger(actual.preparation_version) ||
      actual.preparation_version < 1 ||
      actual.preparation_input_guard !== preparationInputGuard(actual) ||
      !Number.isFinite(Date.parse(actual.preparation_updated_at || ""))
    ) return false;
    if (actual.prep_status !== "pending") {
      const immutableSourceFields = [
        "source",
        "source_job_id",
        "canonical_job_id",
        "canonical_url",
        "job_title",
        "company",
        "job_description",
        "salary_text",
        "posted_at",
        "discovered_at",
        "created_at"
      ];
      return Boolean(
        actual.record_version > source.record_version + 1 &&
          immutableSourceFields.every(
            (field) =>
              JSON.stringify(actual[field] ?? "") ===
              JSON.stringify(source[field] ?? "")
          )
      );
    }
  }
  if (
    destination === "Applied Jobs" &&
    !Number.isFinite(Date.parse(actual.applied_at || ""))
  ) {
    return false;
  }
  if (
    destination === "Archive" &&
    (!Number.isFinite(Date.parse(actual.archived_at || "")) ||
      actual.archive_reason !== reason)
  ) {
    return false;
  }
  if (
    destination === "Archive" &&
    reason === "review_rejected" &&
    (actual.review_case_id !== (source.review_case_id || reviewCaseId(source)) ||
      actual.review_case_version !== "review-case-v1" ||
      actual.review_decision !== "reject" ||
      !Number.isFinite(Date.parse(actual.review_decided_at || "")))
  ) return false;
  if (
    destination === "Archive" &&
    reason === "source_unavailable" &&
    (actual.pipeline_status !== "unavailable" ||
      actual.source_availability !== "unavailable" ||
      actual.next_retry_at)
  ) {
    return false;
  }
  const destinationOwned = new Set([
    "row_number",
    "record_version",
    "state_guard",
    "user_action",
    "processing_stage",
    "processing_token",
    "processing_started_at",
    "alert_claim_token",
    "alert_status",
    "alert_idempotency_key",
    "alert_attempt_count",
    "alert_last_attempt_at",
    "alert_next_retry_at",
    "alert_sent_at",
    "alert_provider_reference",
    "alert_error_category",
    "alert_error_summary",
    "applied_at",
    "archived_at",
    "archive_reason",
    "outcome",
    "outcome_recorded_value",
    "outcome_at",
    "notes",
    "updated_at"
  ]);
  if (destination === "To Review") {
    for (const field of [
      "review_case_id",
      "review_case_version",
      "review_decision",
      "review_decided_at",
      "review_approved_at",
      "review_approval_note",
      "review_approval_guard"
    ]) destinationOwned.add(field);
  }
  if (destination === "To Apply" && reason === "review_proceeded") {
    for (const field of [
      "pipeline_status",
      "review_case_id",
      "review_case_version",
      "review_decision",
      "review_decided_at",
      "review_approved_at",
      "review_approval_note",
      "review_approval_guard",
      "prep_status",
      "preparation_version",
      "preparation_input_guard",
      "preparation_updated_at",
      "next_retry_at",
      "error_category",
      "error_summary"
    ]) destinationOwned.add(field);
  }
  if (destination === "Archive" && reason === "source_unavailable") {
    destinationOwned.add("pipeline_status");
    destinationOwned.add("source_availability");
    destinationOwned.add("next_retry_at");
  }
  if (destination === "Archive" && reason === "review_rejected") {
    for (const field of [
      "review_case_id",
      "review_case_version",
      "review_decision",
      "review_decided_at"
    ]) destinationOwned.add(field);
  }
  return schema.fields.every((field) => {
    if (destinationOwned.has(field)) return true;
    const sourceValue = source[field];
    if (
      sourceValue === "" ||
      sourceValue === undefined ||
      sourceValue === null
    ) {
      return true;
    }
    return JSON.stringify(actual[field]) === JSON.stringify(sourceValue);
  });
}

function destinationRecord(source, destination, reason, now, existing) {
  const record = {
    ...source,
    row_number: undefined,
    user_action: existing?.user_action || "",
    processing_stage: "",
    processing_token: "",
    processing_started_at: "",
    alert_claim_token: "",
    record_version:
      Math.max(
        Number(source.record_version || 1),
        Number(existing?.record_version || 0)
      ) + 1,
    updated_at: now
  };
  if (destination === "Applied Jobs") {
    record.applied_at = existing?.applied_at || source.applied_at || now;
    record.archived_at = "";
    record.archive_reason = "";
    record.notes = existing ? existing.notes || "" : source.notes || "";
    record.outcome = existing ? existing.outcome || "" : source.outcome || "";
    record.outcome_recorded_value = existing
      ? existing.outcome_recorded_value || ""
      : record.outcome;
    record.outcome_at = existing
      ? existing.outcome_at || ""
      : source.outcome_at || "";
  } else if (destination === "Archive") {
    record.archived_at = existing?.archived_at || source.archived_at || now;
    record.archive_reason = reason;
    record.applied_at = "";
    record.notes = existing ? existing.notes || "" : source.notes || "";
    if (reason === "source_unavailable") {
      record.pipeline_status = "unavailable";
      record.source_availability = "unavailable";
      record.next_retry_at = "";
    }
    if (reason === "review_rejected") {
      record.review_case_id = source.review_case_id || reviewCaseId(source);
      record.review_case_version = "review-case-v1";
      record.review_decision = "reject";
      record.review_decided_at = existing?.review_decided_at || now;
    }
  } else {
    record.applied_at = "";
    record.archived_at = "";
    record.archive_reason = "";
    record.notes = existing ? existing.notes || "" : source.notes || "";
    if (destination === "To Review") {
      record.review_case_id = reviewCaseId(source);
      record.review_case_version = "review-case-v1";
      record.review_decision = "";
      record.review_decided_at = "";
      record.review_approved_at = "";
      record.review_approval_note = "";
      record.review_approval_guard = "";
    }
    if (destination === "To Apply" && reason === "review_proceeded") {
      record.pipeline_status = "ready_to_apply";
      record.review_case_id = source.review_case_id || reviewCaseId(source);
      record.review_case_version = "review-case-v1";
      record.review_decision = "proceed";
      record.review_decided_at = existing?.review_decided_at || now;
      record.review_approved_at = record.review_decided_at;
      record.review_approval_note = sanitize(
        existing?.review_approval_note ||
          source.review_approval_note ||
          source.notes,
        1000
      );
      record.review_approval_guard = applicationReviewGuard(source);
      record.prep_status = "pending";
      record.preparation_version = Math.max(
        1,
        Number(source.preparation_version || 0) + 1,
        Number(existing?.preparation_version || 0)
      );
      record.preparation_updated_at =
        existing?.preparation_updated_at || now;
      record.preparation_input_guard = preparationInputGuard(record);
      record.next_retry_at = "";
      record.error_category = "";
      record.error_summary = "";
    }
  }
  if (existing) {
    for (const field of [
      "user_action",
      "notes",
      "alert_status",
      "alert_idempotency_key",
      "alert_claim_token",
      "alert_attempt_count",
      "alert_last_attempt_at",
      "alert_next_retry_at",
      "alert_sent_at",
      "alert_provider_reference",
      "alert_error_category",
      "alert_error_summary",
      "outcome",
      "outcome_recorded_value",
      "outcome_at"
    ]) {
      if (existing[field] !== undefined && existing[field] !== null) {
        record[field] = existing[field];
      }
    }
  }
  if (["user_applied", "user_skip"].includes(reason)) {
    // An operator terminal action wins over an in-flight or retryable Slack
    // delivery. The destination must never retain `sending` after movement
    // clears the source claim token, otherwise the record fails its own store
    // contract and becomes stranded in To Apply.
    if (["pending", "sending", "retryable_failure"].includes(record.alert_status)) {
      record.alert_status = "suppressed";
      record.alert_error_category = "operator_terminal_action";
      record.alert_error_summary =
        "Slack alert cancelled because the operator completed a terminal queue action.";
    }
    record.alert_claim_token = "";
    record.alert_next_retry_at = "";
  }
  record.state_guard = stateGuard(record);
  return record;
}

function classifyQueueRow(sourceSheet, record, schema) {
  if (
    sourceSheet === "Scraped Jobs" &&
    isGuardedLegacyReviewAction(record, sourceSheet, schema)
  ) {
    return record.user_action === "Proceed"
      ? { destination: "To Apply", reason: "review_proceeded" }
      : { destination: "Archive", reason: "review_rejected" };
  }
  if (
    sourceSheet === "Scraped Jobs" &&
    !record.user_action &&
    permanentSourceUnavailable(record)
  ) {
    return { destination: "Archive", reason: "source_unavailable" };
  }
  if (
    sourceSheet === "Scraped Jobs" &&
    record.pipeline_status === "review_needed" &&
    !record.user_action
  ) {
    const currentCase = reviewCaseId(record);
    if (
      record.review_decision === "proceed" &&
      record.review_case_id === currentCase
    ) {
      return {
        suppressed: true,
        reason: "resolved_review_case_repeated",
        summary:
          "The resolved review case cannot be reopened from unchanged preparation facts"
      };
    }
    if (
      record.review_decision &&
      (!record.review_case_id || record.review_case_id === currentCase)
    ) {
      return {
        suppressed: true,
        reason: "review_reopen_missing_new_case",
        summary:
          "A resolved decision requires a materially different review case before reopening"
      };
    }
    if (
      record.review_decision &&
      (!String(record.decision_reason || "").trim() ||
        !String(record.required_input || "").trim())
    ) {
      return {
        suppressed: true,
        reason: "review_reopen_missing_reason",
        summary:
          "A materially new review case requires an explicit bounded reason and required input"
      };
    }
    return { destination: "To Review", reason: "review_needed" };
  }
  if (
    sourceSheet === "Scraped Jobs" &&
    record.pipeline_status === "ready_to_apply" &&
    !record.user_action
  ) {
    return { destination: "To Apply", reason: "ready_to_apply" };
  }
  if (
    sourceSheet === "Scraped Jobs" &&
    record.pipeline_status === "skip" &&
    !record.user_action
  ) {
    return { destination: "Archive", reason: "automatic_skip" };
  }
  if (
    sourceSheet === "To Apply" &&
    record.pipeline_status === "ready_to_apply" &&
    record.user_action === "I Applied"
  ) {
    // This action records a manual application that already happened. Message
    // safety still gates outbound Slack alerts, but it must not erase or strand
    // the operator's historical fact after an alert failure or context change.
    return { destination: "Applied Jobs", reason: "user_applied" };
  }
  if (
    sourceSheet === "To Apply" &&
    record.pipeline_status === "ready_to_apply" &&
    record.user_action === "Skip"
  ) {
    return { destination: "Archive", reason: "user_skip" };
  }
  if (
    sourceSheet === "To Review" &&
    record.pipeline_status === "review_needed" &&
    record.user_action === "Reject"
  ) {
    return { destination: "Archive", reason: "review_rejected" };
  }
  if (
    sourceSheet === "To Review" &&
    record.pipeline_status === "review_needed" &&
    record.user_action === "Proceed"
  ) {
    return { destination: "To Apply", reason: "review_proceeded" };
  }
  return null;
}

function planQueueActions(
  stores,
  schema,
  now = new Date().toISOString(),
  messageSafetyContext,
  { movementPerRunCap = Number.POSITIVE_INFINITY } = {}
) {
  const expectedStores = schema?.business_stores ?? [];
  if (
    expectedStores.length !== 5 ||
    expectedStores.some((store) => !Array.isArray(stores?.[store]))
  ) {
    throw new Error(
      "Movement requires Scraped Jobs, To Review, To Apply, Applied Jobs, and Archive rows"
    );
  }
  const indexes = Object.fromEntries(
    expectedStores.map((store) => [store, indexStore(stores[store], store)])
  );
  const canonicalUrlOwners = new Map();
  for (const store of expectedStores) {
    for (const row of stores[store]) {
      const urlKey = identityKey(row?.canonical_url);
      const identity = identityKey(row?.canonical_job_id);
      const previous = canonicalUrlOwners.get(urlKey);
      if (previous && previous.identity !== identity) {
        throw new Error(
          `Movement contains an ambiguous canonical URL in ${previous.store} and ${store}`
        );
      }
      canonicalUrlOwners.set(urlKey, { identity, store });
    }
  }
  const moves = [];
  const rejected = [];
  const candidates = [];
  const sourceOrder = ["Scraped Jobs", "To Review", "To Apply"];
  for (const sourceSheet of sourceOrder) {
    for (const source of stores[sourceSheet]) {
      const contractErrors = validateRecordStoreContract(
        source,
        sourceSheet,
        schema
      );
      if (contractErrors.length > 0) {
        rejected.push({
          canonical_job_id: String(source?.canonical_job_id || ""),
          source_sheet: sourceSheet,
          reason: "invalid_source",
          summary: sanitize(contractErrors.join("; "))
        });
        continue;
      }
      if (!stateGuardMatches(source)) {
        rejected.push({
          canonical_job_id: String(source?.canonical_job_id || ""),
          source_sheet: sourceSheet,
          reason: "invalid_source",
          summary: "Source state guard does not match the current row"
        });
        continue;
      }
      let classification;
      try {
        classification = classifyQueueRow(sourceSheet, source, schema);
      } catch (error) {
        rejected.push({
          canonical_job_id: String(source?.canonical_job_id || ""),
          source_sheet: sourceSheet,
          reason: "unsafe_action",
          summary: sanitize(error?.message || error)
        });
        continue;
      }
      if (classification) {
        if (classification.suppressed) {
          rejected.push({
            canonical_job_id: source.canonical_job_id,
            source_sheet: sourceSheet,
            reason: classification.reason,
            summary: sanitize(classification.summary)
          });
        } else {
          candidates.push({ sourceSheet, source, classification });
        }
      }
    }
  }
  candidates.sort((left, right) => {
    const timestamp = (entry) => {
      const parsed = Date.parse(
        entry.source.updated_at || entry.source.created_at || ""
      );
      return Number.isFinite(parsed) ? parsed : Number.POSITIVE_INFINITY;
    };
    return (
      timestamp(left) - timestamp(right) ||
      sourceOrder.indexOf(left.sourceSheet) -
        sourceOrder.indexOf(right.sourceSheet) ||
      String(left.source.canonical_job_id).localeCompare(
        String(right.source.canonical_job_id)
      )
    );
  });

  for (const { sourceSheet, source, classification } of candidates) {
    const key = identityKey(source.canonical_job_id);
    const existing = indexes[classification.destination].get(key);
    const conflictingStores = expectedStores.filter(
      (store) =>
        store !== sourceSheet &&
        store !== classification.destination &&
        indexes[store].has(key)
    );
    if (conflictingStores.length > 0) {
      rejected.push({
        canonical_job_id: source.canonical_job_id,
        source_sheet: sourceSheet,
        reason: "identity_conflict",
        summary: `Identity already exists in ${conflictingStores.join(", ")}`
      });
      continue;
    }
    if (
      existing &&
      destinationConflict(
        existing,
        classification.destination,
        classification.reason
      )
    ) {
      rejected.push({
        canonical_job_id: source.canonical_job_id,
        source_sheet: sourceSheet,
        reason: "destination_conflict",
        summary: "Existing destination record has conflicting terminal state"
      });
      continue;
    }
    if (moves.length >= movementPerRunCap) {
      rejected.push({
        canonical_job_id: source.canonical_job_id,
        source_sheet: sourceSheet,
        reason: "movement_cap_reached",
        summary: "Movement deferred to a later bounded run"
      });
      continue;
    }
    const existingComplete = validExistingDestination(
      source,
      existing,
      classification.destination,
      classification.reason,
      schema
    );
    const destination = existingComplete
      ? { ...existing }
      : destinationRecord(
          source,
          classification.destination,
          classification.reason,
          now,
          existing
        );
    const destinationErrors = validateRecordStoreContract(
      destination,
      classification.destination,
      schema
    );
    if (destinationErrors.length > 0) {
      rejected.push({
        canonical_job_id: source.canonical_job_id,
        source_sheet: sourceSheet,
        reason: "invalid_destination",
        summary: sanitize(destinationErrors.join("; "))
      });
      continue;
    }
    moves.push({
      canonical_job_id: source.canonical_job_id,
      source_sheet: sourceSheet,
      source_row_number: source.row_number,
      source_state_guard: source.state_guard,
      source_record_version: source.record_version,
      source_status: source.pipeline_status,
      source_action: source.user_action,
      source_notes: source.notes || "",
      destination: classification.destination,
      route_reason: classification.reason,
      claim_scope: `${sourceSheet}:${classification.destination}`,
      archive_reason:
        classification.destination === "Archive"
          ? classification.reason
          : "",
      write_required: !existingComplete,
      recovery_required: Boolean(existing),
      source_record: { ...source },
      destination_record: destination
    });
  }
  return { moves, rejected };
}

function destinationWrites(plans) {
  return {
    scraped_jobs: plans.moves
      .filter(
        (plan) => plan.destination === "Scraped Jobs" && plan.write_required
      )
      .map((plan) => ({ ...plan.destination_record })),
    to_review: plans.moves
      .filter(
        (plan) => plan.destination === "To Review" && plan.write_required
      )
      .map((plan) => ({ ...plan.destination_record })),
    to_apply: plans.moves
      .filter(
        (plan) => plan.destination === "To Apply" && plan.write_required
      )
      .map((plan) => ({ ...plan.destination_record })),
    applied: plans.moves
      .filter(
        (plan) => plan.destination === "Applied Jobs" && plan.write_required
      )
      .map((plan) => ({ ...plan.destination_record })),
    archive: plans.moves
      .filter((plan) => plan.destination === "Archive" && plan.write_required)
      .map((plan) => ({ ...plan.destination_record }))
  };
}

function confirmMoveDeletions(
  plans,
  freshStores,
  schema
) {
  const expectedStores = schema?.business_stores ?? [];
  if (expectedStores.some((store) => !Array.isArray(freshStores?.[store]))) {
    throw new Error("Movement confirmation requires every business store");
  }
  const indexes = Object.fromEntries(
    expectedStores.map((store) => [
      store,
      indexStore(freshStores[store], store)
    ])
  );
  const deletions = [];
  const rejected = [];

  for (const plan of plans.moves) {
    const key = identityKey(plan.canonical_job_id);
    const source = indexes[plan.source_sheet]?.get(key);
    if (!source) {
      // A repeated scheduler run after a successful delete is a no-op.
      continue;
    }
    const sourceUnchanged =
      stateGuardMatches(source) &&
      source.state_guard === plan.source_state_guard &&
      source.record_version === plan.source_record_version &&
      source.pipeline_status === plan.source_status &&
      source.user_action === plan.source_action &&
      String(source.notes || "") === String(plan.source_notes || "");
    if (!sourceUnchanged) {
      rejected.push({
        canonical_job_id: plan.canonical_job_id,
        reason: "stale_source"
      });
      continue;
    }
    const destination = indexes[plan.destination]?.get(key);
    if (
      !validExistingDestination(
        plan.source_record,
        destination,
        plan.destination,
        plan.route_reason,
        schema
      )
    ) {
      rejected.push({
        canonical_job_id: plan.canonical_job_id,
        reason: "destination_unconfirmed"
      });
      continue;
    }
    deletions.push({
      row_number: source.row_number,
      canonical_job_id: source.canonical_job_id,
      source_sheet: plan.source_sheet,
      destination: plan.destination
    });
  }

  deletions.sort(
    (left, right) =>
      left.source_sheet.localeCompare(right.source_sheet) ||
      right.row_number - left.row_number
  );
  return { deletions, rejected };
}

function applyOutcomeUpdate(
  appliedRecord,
  outcome,
  expectedStateGuard,
  schema,
  now = new Date().toISOString()
) {
  if (appliedRecord.state_guard !== expectedStateGuard) {
    throw new Error("Outcome update rejected stale Applied Jobs state");
  }
  if (!schema.outcomes.includes(outcome)) {
    throw new Error("Outcome update contains an unsupported value");
  }
  const updated = {
    ...appliedRecord,
    outcome,
    outcome_recorded_value: outcome,
    outcome_at: outcome ? now : "",
    record_version: appliedRecord.record_version + 1,
    updated_at: now
  };
  updated.state_guard = stateGuard(updated);
  const errors = validateRecordStoreContract(
    updated,
    "Applied Jobs",
    schema
  );
  if (errors.length > 0) {
    throw new Error(`Outcome update failed contract validation: ${sanitize(errors.join("; "))}`);
  }
  return updated;
}

function planOutcomeUpdates(
  appliedRows,
  schema,
  now = new Date().toISOString()
) {
  indexStore(appliedRows, "Applied Jobs");
  const updates = [];
  const rejected = [];
  for (const record of appliedRows) {
    const errors = validateRecordStoreContract(
      record,
      "Applied Jobs",
      schema
    );
    if (errors.length > 0) {
      rejected.push({
        canonical_job_id: String(record?.canonical_job_id || ""),
        reason: "invalid_applied_record",
        summary: sanitize(errors.join("; "))
      });
      continue;
    }
    if (
      String(record.outcome || "") ===
      String(record.outcome_recorded_value || "")
    ) {
      continue;
    }
    updates.push(
      applyOutcomeUpdate(
        record,
        String(record.outcome || ""),
        record.state_guard,
        schema,
        now
      )
    );
  }
  return { updates, rejected };
}

const writes = destinationWrites(
  $('Keep Winning Movement Claims').first().json.movement
);
return writes.to_review.length
  ? writes.to_review.map((row) => ({ json: row }))
  : [{ json: { _noop: true } }];

function parseHttpUrl(value, { baseOrigin = "" } = {}) {
  let input = String(value ?? "").trim();
  if (!input) return null;

  if (input.startsWith("/")) {
    const base = parseHttpUrl(baseOrigin);
    if (!base) return null;
    input = `${base.protocol}//${base.hostname}${base.port ? `:${base.port}` : ""}${input}`;
  }

  if (/[\u0000-\u0020\u007f\\]/.test(input)) return null;
  const match = input.match(
    /^(https?):\/\/([^/?#]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i
  );
  if (!match) return null;

  const protocol = `${match[1].toLowerCase()}:`;
  const authority = match[2];
  if (!authority || authority.includes("@") || authority.includes("[")) return null;

  const colonIndex = authority.lastIndexOf(":");
  let hostname = authority;
  let port = "";
  if (colonIndex >= 0) {
    if (authority.indexOf(":") !== colonIndex) return null;
    hostname = authority.slice(0, colonIndex);
    port = authority.slice(colonIndex + 1);
    if (!/^\d{1,5}$/.test(port)) return null;
    const portNumber = Number(port);
    if (portNumber < 1 || portNumber > 65535) return null;
  }

  hostname = hostname.toLowerCase();
  if (
    hostname.length > 253 ||
    hostname.split(".").some(
      (label) =>
        !label ||
        label.length > 63 ||
        !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label)
    )
  ) {
    return null;
  }

  const pathname = match[3] || "/";
  const search = match[4] || "";
  const hash = match[5] || "";
  return {
    protocol,
    hostname,
    port,
    pathname,
    search,
    hash,
    username: "",
    password: "",
    href: `${protocol}//${hostname}${port ? `:${port}` : ""}${pathname}${search}${hash}`
  };
}

function normalizeCanonicalUrl(value) {
  const parsed = parseHttpUrl(value, {
    baseOrigin: "https://www.onlinejobs.ph"
  });
  if (!parsed) return "";
  if (parsed.port && parsed.port !== "443") return "";
  const hostname =
    parsed.hostname === "www.onlinejobs.ph"
      ? "onlinejobs.ph"
      : parsed.hostname;
  if (hostname !== "onlinejobs.ph") return "";
  const pathname = parsed.pathname.replace(/\/+/g, "/").replace(/\/$/, "");
  if (!/^\/jobseekers\/job\/[^/]+$/i.test(pathname)) return "";
  return `https://${hostname}${pathname}`;
}

function extractOnlineJobsId(url) {
  const canonicalUrl = normalizeCanonicalUrl(url);
  if (!canonicalUrl) return "";
  const match = canonicalUrl.match(/\/jobseekers\/job\/[^/]*?(\d+)$/i);
  return match?.[1] ?? "";
}

function canonicalJobId(record) {
  const source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  const sourceJobId = String(record.source_job_id || extractOnlineJobsId(record.canonical_url || record.job_url) || "").trim();
  if (sourceJobId) return `${source}:${sourceJobId}`;
  const canonicalUrl = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  if (!canonicalUrl) return "";
  let hash = 2166136261;
  for (let index = 0; index < canonicalUrl.length; index += 1) {
    hash ^= canonicalUrl.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  const digest = (hash >>> 0).toString(16).padStart(8, "0");
  return `${source}:url:${digest}`;
}

function stableContractValue(value) {
  if (Array.isArray(value)) return value.map(stableContractValue);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, stableContractValue(value[key])])
    );
  }
  return value;
}

function contractDigest(value) {
  const serialized = JSON.stringify(stableContractValue(value));
  const input = new TextEncoder().encode(serialized);
  const paddedLength = Math.ceil((input.length + 9) / 64) * 64;
  const bytes = new Uint8Array(paddedLength);
  bytes.set(input);
  bytes[input.length] = 0x80;
  const bitLength = input.length * 8;
  const lengthView = new DataView(bytes.buffer);
  lengthView.setUint32(paddedLength - 8, Math.floor(bitLength / 0x100000000));
  lengthView.setUint32(paddedLength - 4, bitLength >>> 0);
  const constants = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
    0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
    0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
    0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
    0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
    0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
  ];
  const rotateRight = (value, amount) =>
    (value >>> amount) | (value << (32 - amount));
  const state = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
  ];
  const schedule = new Uint32Array(64);
  for (let offset = 0; offset < paddedLength; offset += 64) {
    const view = new DataView(bytes.buffer, offset, 64);
    for (let index = 0; index < 16; index += 1) {
      schedule[index] = view.getUint32(index * 4);
    }
    for (let index = 16; index < 64; index += 1) {
      const previous15 = schedule[index - 15];
      const previous2 = schedule[index - 2];
      const sigma0 =
        rotateRight(previous15, 7) ^
        rotateRight(previous15, 18) ^
        (previous15 >>> 3);
      const sigma1 =
        rotateRight(previous2, 17) ^
        rotateRight(previous2, 19) ^
        (previous2 >>> 10);
      schedule[index] =
        (schedule[index - 16] + sigma0 + schedule[index - 7] + sigma1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = state;
    for (let index = 0; index < 64; index += 1) {
      const upper1 = rotateRight(e, 6) ^ rotateRight(e, 11) ^ rotateRight(e, 25);
      const choice = (e & f) ^ (~e & g);
      const temporary1 =
        (h + upper1 + choice + constants[index] + schedule[index]) >>> 0;
      const upper0 = rotateRight(a, 2) ^ rotateRight(a, 13) ^ rotateRight(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const temporary2 = (upper0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + temporary1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temporary1 + temporary2) >>> 0;
    }
    state[0] = (state[0] + a) >>> 0;
    state[1] = (state[1] + b) >>> 0;
    state[2] = (state[2] + c) >>> 0;
    state[3] = (state[3] + d) >>> 0;
    state[4] = (state[4] + e) >>> 0;
    state[5] = (state[5] + f) >>> 0;
    state[6] = (state[6] + g) >>> 0;
    state[7] = (state[7] + h) >>> 0;
  }
  return state
    .map((word) => word.toString(16).padStart(8, "0"))
    .join("");
}

/**
 * Binds a human review approval to the exact application strategy that was
 * visible at review time. Operator notes and timestamps are intentionally not
 * included: neither is authoritative evidence for the generated message.
 */
function applicationReviewGuard(record) {
  return `review-v1:${contractDigest({
    application_instructions: record?.application_instructions ?? [],
    screening_questions: record?.screening_questions ?? [],
    requirement_coverage: record?.requirement_coverage ?? [],
    application_message_plan: record?.application_message_plan ?? [],
    selected_proof_refs: record?.selected_proof_refs ?? [],
    application_warnings: record?.application_warnings ?? [],
    application_pack_status: record?.application_pack_status ?? "",
    application_pack_version: record?.application_pack_version ?? "",
    application_pack_profile_version:
      record?.application_pack_profile_version ?? "",
    application_pack_policy_version:
      record?.application_pack_policy_version ?? "",
    coverage_contract_version: record?.coverage_contract_version ?? "",
    message_plan_version: record?.message_plan_version ?? ""
  })}`;
}

/**
 * Identifies the material review case without volatile timestamps or operator
 * notes. The same employer requirements, coverage, pack policy, and bounded
 * decision context therefore produce the same case across retries.
 */
function reviewCaseId(record) {
  return `review-case-v1:${contractDigest({
    application_review_guard: applicationReviewGuard(record),
    decision_reason: record?.decision_reason ?? "",
    required_input: record?.required_input ?? "",
    profile_version: record?.profile_version ?? "",
    policy_version: record?.policy_version ?? ""
  })}`;
}

/**
 * Binds preparation work to stable inputs. Generated output, retry counters,
 * timestamps, and operator notes are deliberately excluded so scheduled runs
 * cannot manufacture new work from unchanged inputs.
 */
function preparationInputGuard(record) {
  return `prep-v1:${contractDigest({
    canonical_job_id: record?.canonical_job_id ?? canonicalJobId(record ?? {}),
    job_description: record?.job_description ?? "",
    review_case_id: record?.review_case_id ?? "",
    review_decision: record?.review_decision ?? "",
    // The persisted approval guard is an input authorization. Recomputing an
    // application guard from the current pack would make this digest depend on
    // generated preparation output and invalidate it after a legitimate run.
    review_approval_guard: record?.review_approval_guard ?? "",
    profile_version: record?.profile_version ?? "",
    policy_version: record?.policy_version ?? ""
  })}`;
}

function normalizeUserAction(action, schema) {
  const value = String(action ?? "").trim();
  return schema?.legacy_user_action_mapping?.[value] ?? value;
}

/**
 * Operator-owned Sheet columns are intentionally excluded from the persisted
 * digest. A Google Sheets edit cannot atomically refresh `state_guard`, so
 * guarding these values would make every legitimate action or note look like
 * system-state corruption. Workflows validate the values against the owning
 * store and compare them explicitly at their commit boundaries instead.
 */
const OPERATOR_EDITABLE_STATE_FIELDS = ["user_action", "outcome", "notes"];
const ASYNC_DISCOVERY_STATE_FIELDS = [
  "last_seen_at",
  "matched_keywords",
  "updated_at"
];
const STATE_GUARD_EXCLUDED_FIELDS = [
  "state_guard",
  ...OPERATOR_EDITABLE_STATE_FIELDS,
  ...ASYNC_DISCOVERY_STATE_FIELDS
];

const STATE_GUARD_FIELDS = [
  "source", "source_job_id", "canonical_job_id", "record_version",
  "canonical_url", "job_title", "company", "job_description", "salary_text",
  "posted_at", "discovered_at",
  "source_availability", "pipeline_status", "decision_reason",
  "required_input", "review_case_id", "review_case_version",
  "review_decision", "review_decided_at", "review_approved_at",
  "review_approval_note", "review_approval_guard", "qualification_score",
  "opportunity_score",
  "ranking_confidence", "match_reasons", "requirement_gaps", "profile_version",
  "policy_version", "evaluated_at", "processing_stage", "processing_token",
  "processing_started_at", "attempt_count", "next_retry_at", "error_category",
  "error_summary", "generated_message", "message_validation_status",
  "message_profile_version", "message_policy_version", "generated_at",
  "application_instructions", "screening_questions", "requirement_coverage",
  "application_message_plan", "selected_proof_refs", "application_warnings",
  "application_pack_status", "application_pack_version",
  "application_pack_profile_version", "application_pack_policy_version",
  "coverage_contract_version", "message_plan_version",
  "application_pack_generated_at", "prep_status", "preparation_version",
  "preparation_input_guard", "preparation_updated_at", "alert_status",
  "alert_idempotency_key",
  "alert_claim_token", "alert_attempt_count", "alert_last_attempt_at",
  "alert_next_retry_at", "alert_sent_at", "alert_provider_reference",
  "alert_error_category", "alert_error_summary", "applied_at", "archived_at",
  "archive_reason", "outcome_recorded_value", "outcome_at",
  "created_at"
];

// Compatibility is intentionally limited to the immediately preceding
// persisted contract. It lets the guarded workflows claim a freshly reread v3
// row and rewrite it under v4; it does not make old workflow definitions
// compatible with new lifecycle state.
const LEGACY_STATE_GUARD_FIELDS_V3 = STATE_GUARD_FIELDS.filter(
  (field) =>
    ![
      "review_case_id",
      "review_case_version",
      "review_decision",
      "review_decided_at",
      "prep_status",
      "preparation_version",
      "preparation_input_guard",
      "preparation_updated_at"
    ].includes(field)
);

function stateGuardForFields(record, fields) {
  const canonicalId = String(record.canonical_job_id || canonicalJobId(record) || "");
  if (!canonicalId) return "";
  const guardedRecord = Object.fromEntries(
    fields.map((field) => [field, record?.[field] ?? ""])
  );
  return `${canonicalId}|${contractDigest(guardedRecord)}`;
}

function stateGuard(record) {
  // A missing top-level field becomes a blank Sheet cell on persistence.
  // Canonicalizing it here keeps digests stable across that round trip.
  return stateGuardForFields(record, STATE_GUARD_FIELDS);
}

function legacyStateGuardV3(record) {
  return stateGuardForFields(record, LEGACY_STATE_GUARD_FIELDS_V3);
}

function stateGuardMatches(record) {
  const persisted = String(record?.state_guard || "");
  if (!persisted) return false;
  if (persisted === stateGuard(record)) return true;
  const hasV4LifecycleState =
    Boolean(
      record?.review_case_id ||
        record?.review_case_version ||
        record?.review_decision ||
        record?.review_decided_at ||
        record?.preparation_input_guard ||
        record?.preparation_updated_at
    ) ||
    Number(record?.preparation_version || 0) > 0 ||
    !["", "preparation_error"].includes(String(record?.prep_status || ""));
  return !hasV4LifecycleState && persisted === legacyStateGuardV3(record);
}

/**
 * Recognizes only the v3 Scraped Jobs review action produced by the retired
 * approval loop. The raw legacy spelling is retained in memory by
 * normalizeLegacyRecord; it is never a persisted v4 field. A new Proceed or
 * Reject value, or any row that already contains v4 lifecycle state, cannot
 * use this compatibility route.
 */
function isGuardedLegacyReviewAction(record, store, schema) {
  const legacyAction = String(
    record?.compatibility_legacy_user_action || ""
  ).trim();
  const expectedAction = schema?.legacy_user_action_mapping?.[legacyAction];
  const persisted = String(record?.state_guard || "");
  return Boolean(
    store === "Scraped Jobs" &&
      record?.pipeline_status === "review_needed" &&
      ["Approve", "Deny"].includes(legacyAction) &&
      ["Proceed", "Reject"].includes(expectedAction) &&
      record?.user_action === expectedAction &&
      persisted &&
      persisted !== stateGuard(record) &&
      persisted === legacyStateGuardV3(record) &&
      stateGuardMatches(record)
  );
}

function rankingPriorityValue(record) {
  if (
    typeof record?.opportunity_score === "number" &&
    Number.isFinite(record.opportunity_score)
  ) {
    return {
      value: record.opportunity_score,
      source: "opportunity_score"
    };
  }
  if (typeof record?.match_score === "number" && Number.isFinite(record.match_score)) {
    return {
      value: record.match_score,
      source: "legacy_match_score"
    };
  }
  return { value: 0, source: "missing" };
}

function compareRankingPriority(left, right) {
  const scoreOrder =
    rankingPriorityValue(right).value - rankingPriorityValue(left).value;
  if (scoreOrder !== 0) return scoreOrder;
  const confidenceOrder =
    ({ high: 3, medium: 2, low: 1 }[right.ranking_confidence] ?? 0) -
    ({ high: 3, medium: 2, low: 1 }[left.ranking_confidence] ?? 0);
  if (confidenceOrder !== 0) return confidenceOrder;
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.NEGATIVE_INFINITY;
  };
  const rightPosted = timestamp(right.posted_at);
  const leftPosted = timestamp(left.posted_at);
  if (rightPosted !== leftPosted) return rightPosted - leftPosted;
  const rightCreated = timestamp(right.created_at);
  const leftCreated = timestamp(left.created_at);
  if (rightCreated !== leftCreated) return rightCreated - leftCreated;
  return String(left.canonical_job_id || "").localeCompare(
    String(right.canonical_job_id || "")
  );
}

function parseList(value) {
  if (Array.isArray(value)) return value.filter(Boolean);
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed.filter(Boolean);
  } catch {
    // Legacy sheets may use comma-separated values.
  }
  return String(value)
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);
}

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : value;
  } catch {
    return value;
  }
}

function normalizeRuleValue(value, rule) {
  if (!rule || value === "" || value === undefined || value === null) return value ?? "";
  if (rule.type === "number" || rule.type === "integer") {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : value;
  }
  if (rule.type === "string") return String(value).trim();
  return value;
}

function mergeOutcomeEvents(...collections) {
  const events = new Map();
  for (const collection of collections) {
    if (!Array.isArray(collection)) continue;
    for (const event of collection) {
      if (!event || typeof event !== "object" || Array.isArray(event)) continue;
      const id = String(event.id || "").trim();
      if (!id || events.has(id)) continue;
      events.set(id, { ...event, id });
    }
  }
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.POSITIVE_INFINITY;
  };
  return [...events.values()].sort(
    (left, right) =>
      timestamp(left.at) - timestamp(right.at) ||
      String(left.id).localeCompare(String(right.id))
  );
}

function normalizeLegacyRecord(input, schema, now = new Date().toISOString()) {
  const record = { ...input };
  for (const [legacy, canonical] of Object.entries(schema.legacy_header_mapping ?? {})) {
    if (record[canonical] === undefined && record[legacy] !== undefined) {
      record[canonical] = record[legacy];
    }
  }

  const legacyStatus = String(record.pipeline_status || "").trim().toLowerCase();
  record.pipeline_status =
    schema.legacy_status_mapping?.[legacyStatus] ||
    (schema.pipeline_statuses.includes(legacyStatus) ? legacyStatus : "new");
  const rawUserAction = String(record.user_action || "").trim();
  record.user_action = normalizeUserAction(rawUserAction, schema);
  record.compatibility_legacy_user_action =
    record.user_action !== rawUserAction ? rawUserAction : "";
  record.source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  record.canonical_url = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  record.source_job_id = String(record.source_job_id || extractOnlineJobsId(record.canonical_url) || "");
  record.canonical_job_id = String(record.canonical_job_id || canonicalJobId(record));
  for (const field of schema.string_list_fields ?? ["matched_keywords"]) {
    record[field] = parseList(record[field]);
  }
  for (const field of schema.json_array_fields ?? []) {
    record[field] = parseJsonArray(record[field]);
  }
  for (const [field, rule] of Object.entries(schema.field_rules ?? {})) {
    record[field] = normalizeRuleValue(record[field], rule);
  }
  record.attempt_count = Number.isFinite(Number(record.attempt_count))
    ? Number(record.attempt_count)
    : 0;
  record.record_version = Number.isInteger(Number(record.record_version)) && Number(record.record_version) > 0
    ? Number(record.record_version)
    : 1;
  record.alert_attempt_count = Number.isFinite(Number(record.alert_attempt_count))
    ? Number(record.alert_attempt_count)
    : 0;
  record.preparation_version =
    Number.isInteger(Number(record.preparation_version)) &&
    Number(record.preparation_version) >= 0
      ? Number(record.preparation_version)
      : 0;
  record.created_at = record.created_at || now;
  record.updated_at = record.updated_at || now;
  record.source_availability = record.source_availability || "active";
  record.profile_version =
    record.profile_version ||
    (schema.schema_version === 1 ? "legacy/unknown" : "");
  record.message_profile_version =
    record.message_profile_version ||
    (schema.schema_version === 1 && record.generated_message
      ? "legacy/unknown"
      : "");
  record.outcome = record.outcome || "";
  record.outcome_recorded_value = record.outcome_recorded_value || "";
  record.user_action = record.user_action || "";
  record.review_case_id = record.review_case_id || "";
  record.review_case_version = record.review_case_version || "";
  record.review_decision = record.review_decision || "";
  record.prep_status =
    record.prep_status ||
    (record.pipeline_status === "ready_to_apply" ? "preparation_error" : "");
  record.preparation_input_guard = record.preparation_input_guard || "";
  record.review_approval_note = record.review_approval_note || "";
  record.review_approval_guard = record.review_approval_guard || "";
  record.alert_claim_token = record.alert_claim_token || "";
  record.state_guard = record.state_guard || stateGuard(record);
  return record;
}

function validateRecordContract(record, schema) {
  const errors = [];
  const fields = new Set(schema?.fields ?? []);
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) {
      errors.push(`field rule references unknown field: ${field}`);
      continue;
    }
    const value = record?.[field];
    const missing = value === "" || value === undefined || value === null;
    if (missing) {
      if (rule.nullable === false) errors.push(`${field} is required`);
      continue;
    }
    if (rule.type === "enum") {
      if (!rule.values?.includes(value)) errors.push(`${field} has unsupported value: ${value}`);
      continue;
    }
    if (rule.type === "string") {
      if (typeof value !== "string") {
        errors.push(`${field} must be a string`);
        continue;
      }
      if (
        rule.maximum_length !== undefined &&
        value.length > rule.maximum_length
      ) {
        errors.push(`${field} exceeds its maximum length`);
      }
      if (rule.pattern && !new RegExp(rule.pattern).test(value)) {
        errors.push(`${field} has an unsupported format`);
      }
      continue;
    }
    const numeric = typeof value === "number" ? value : Number.NaN;
    if (!Number.isFinite(numeric)) {
      errors.push(`${field} must be a ${rule.type}`);
      continue;
    }
    if (rule.type === "integer" && !Number.isInteger(numeric)) {
      errors.push(`${field} must be an integer`);
    }
    if (rule.minimum !== undefined && numeric < rule.minimum) {
      errors.push(`${field} must be at least ${rule.minimum}`);
    }
    if (rule.maximum !== undefined && numeric > rule.maximum) {
      errors.push(`${field} must be at most ${rule.maximum}`);
    }
  }
  for (const field of schema?.string_list_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be an array`);
  }
  for (const field of schema?.json_array_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be a JSON array`);
    const maximum = schema?.json_field_maximum_characters?.[field];
    if (value !== undefined && Number.isInteger(maximum)) {
      try {
        if (JSON.stringify(value).length > maximum) {
          errors.push(`${field} exceeds ${maximum} serialized characters`);
        }
      } catch {
        errors.push(`${field} must be JSON serializable`);
      }
    }
  }
  if (Array.isArray(record?.outcome_events)) {
    const seen = new Set();
    const allowedTypes = new Set([
      "no_response",
      "replied",
      "interview",
      "offer",
      "rejected",
      "correction"
    ]);
    for (const [index, event] of record.outcome_events.entries()) {
      if (!event || typeof event !== "object" || Array.isArray(event)) {
        errors.push(`outcome_events[${index}] must be an object`);
        continue;
      }
      const id = String(event.id || "");
      if (!id || id.length > 256) {
        errors.push(`outcome_events[${index}].id is invalid`);
      } else if (seen.has(id)) {
        errors.push(`outcome_events contains duplicate id: ${id}`);
      } else {
        seen.add(id);
      }
      if (!allowedTypes.has(event.type)) {
        errors.push(`outcome_events[${index}].type is invalid`);
      }
      if (
        typeof event.at !== "string" ||
        !Number.isFinite(Date.parse(event.at))
      ) {
        errors.push(`outcome_events[${index}].at is invalid`);
      }
      for (const field of ["previous_outcome", "corrected_outcome"]) {
        if (
          event[field] !== undefined &&
          !["", "no_response", "replied", "interview", "offer", "rejected"].includes(
            event[field]
          )
        ) {
          errors.push(`outcome_events[${index}].${field} is invalid`);
        }
      }
    }
  }
  for (const field of schema?.timestamp_fields ?? []) {
    const value = record?.[field];
    if (value === "" || value === undefined || value === null) continue;
    if (typeof value !== "string" || !Number.isFinite(Date.parse(value))) {
      errors.push(`${field} must be a valid timestamp`);
    }
  }
  const canonicalUrl = normalizeCanonicalUrl(record?.canonical_url);
  const expectedIdentity = canonicalJobId(record ?? {});
  if (!canonicalUrl) errors.push("canonical_url is invalid");
  if (!String(record?.source_job_id || "").trim()) {
    errors.push("source_job_id is required");
  }
  if (!expectedIdentity || record?.canonical_job_id !== expectedIdentity) {
    errors.push("canonical_job_id does not match the canonical source identity");
  }
  const allowedActions =
    schema?.actions_by_status?.[record?.pipeline_status] ?? [];
  if (!allowedActions.includes(record?.user_action ?? "")) {
    errors.push("user_action is not supported for pipeline_status");
  }
  const processingToken = String(record?.processing_token || "").trim();
  const processingStage = String(record?.processing_stage || "").trim();
  const processingStartedAt = String(record?.processing_started_at || "").trim();
  if (
    processingToken &&
    (!["evaluation", "generation"].includes(processingStage) ||
      !Number.isFinite(Date.parse(processingStartedAt)))
  ) {
    errors.push(
      "processing_token requires an evaluation/generation stage and valid start time"
    );
  }
  if (!processingToken && processingStartedAt) {
    errors.push("processing_started_at requires processing_token");
  }
  if (record?.pipeline_status === "processing" && !processingToken) {
    errors.push("processing status requires processing_token");
  }
  const alertClaimToken = String(record?.alert_claim_token || "").trim();
  if (record?.alert_status === "sending" && !alertClaimToken) {
    errors.push("sending alert status requires alert_claim_token");
  }
  if (record?.alert_status !== "sending" && alertClaimToken) {
    errors.push("alert_claim_token is only valid while sending");
  }
  const unsafeChecklist =
    /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f\u200b-\u200d\u202a-\u202e\u2060\u2066-\u2069\ufeff]/u;
  const requiredInput = String(record?.required_input || "");
  if (
    ["needs_input", "external_steps"].includes(record?.prep_status) &&
    !requiredInput.trim()
  ) {
    errors.push(`${record.prep_status} requires bounded required_input`);
  }
  if (requiredInput && unsafeChecklist.test(requiredInput)) {
    errors.push("required_input contains unsafe control characters");
  }
  const reviewCaseIdValue = String(record?.review_case_id || "");
  const reviewCaseVersion = String(record?.review_case_version || "");
  const reviewDecision = String(record?.review_decision || "");
  const reviewDecidedAt = String(record?.review_decided_at || "");
  if (Boolean(reviewCaseIdValue) !== Boolean(reviewCaseVersion)) {
    errors.push("review_case_id and review_case_version must be set together");
  }
  if (reviewDecision && (!reviewCaseIdValue || !reviewDecidedAt)) {
    errors.push("review_decision requires a review case and decision timestamp");
  }
  if (!reviewDecision && reviewDecidedAt) {
    errors.push("review_decided_at requires review_decision");
  }
  const prepStatus = String(record?.prep_status || "");
  const preparationVersion = Number(record?.preparation_version || 0);
  const preparationGuard = String(record?.preparation_input_guard || "");
  const preparationUpdatedAt = String(record?.preparation_updated_at || "");
  if (record?.pipeline_status === "ready_to_apply" && !prepStatus) {
    errors.push("ready_to_apply requires prep_status");
  }
  if (prepStatus && record?.pipeline_status !== "ready_to_apply") {
    errors.push("prep_status is only valid for ready_to_apply records");
  }
  const legacyPreparationError =
    prepStatus === "preparation_error" && preparationVersion === 0;
  if (prepStatus && !legacyPreparationError) {
    if (!Number.isInteger(preparationVersion) || preparationVersion < 1) {
      errors.push("active preparation state requires preparation_version");
    }
    if (!preparationGuard || !preparationUpdatedAt) {
      errors.push(
        "active preparation state requires an input guard and update timestamp"
      );
    }
  }
  if (prepStatus === "message_ready") {
    for (const [field, value] of Object.entries({
      application_pack_status: record?.application_pack_status,
      generated_message: record?.generated_message,
      message_validation_status: record?.message_validation_status,
      message_profile_version: record?.message_profile_version,
      message_policy_version: record?.message_policy_version,
      application_pack_version: record?.application_pack_version,
      application_pack_profile_version:
        record?.application_pack_profile_version,
      application_pack_policy_version:
        record?.application_pack_policy_version
    })) {
      if (!String(value || "").trim()) {
        errors.push(`message_ready requires ${field}`);
      }
    }
    if (record?.application_pack_status !== "ready") {
      errors.push("message_ready requires a ready application pack");
    }
    if (record?.message_validation_status !== "valid") {
      errors.push("message_ready requires a valid generated message");
    }
  }
  return errors;
}

function validateRecordStoreContract(record, store, schema) {
  const errors = validateRecordContract(record, schema);
  const normalizedStore = String(store || "").trim();
  if (!(schema?.business_stores ?? []).includes(normalizedStore)) {
    errors.push(`record store is not authoritative: ${normalizedStore || "(blank)"}`);
    return errors;
  }
  const allowedActions =
    schema?.actions_by_store_status?.[normalizedStore]?.[
      record?.pipeline_status
    ];
  if (!Array.isArray(allowedActions)) {
    errors.push(
      `${normalizedStore} does not own pipeline_status ${
        record?.pipeline_status || "(blank)"
      }`
    );
  } else if (
    !allowedActions.includes(record?.user_action ?? "") &&
    !isGuardedLegacyReviewAction(record, normalizedStore, schema)
  ) {
    errors.push(
      `user_action is not supported for ${normalizedStore}/${
        record?.pipeline_status || "(blank)"
      }`
    );
  }
  return errors;
}

function applyValidatedRecordUpdate(record, updates, schema) {
  const candidate = { ...record, ...updates };
  const errors = validateRecordContract(candidate, schema);
  if (errors.length > 0) {
    throw new Error(`Invalid record update: ${errors.join("; ")}`);
  }
  return candidate;
}

function validatePipelineSchema(schema) {
  const errors = [];
  if (schema?.schema_version !== 4) errors.push("schema_version must be 4");
  if (!Array.isArray(schema?.fields) || schema.fields.length === 0) errors.push("fields are required");
  if (!Array.isArray(schema?.pipeline_statuses) || schema.pipeline_statuses.length === 0) {
    errors.push("pipeline_statuses are required");
  }
  const duplicateFields = schema?.fields?.filter((field, index, all) => all.indexOf(field) !== index) ?? [];
  if (duplicateFields.length > 0) errors.push(`duplicate fields: ${[...new Set(duplicateFields)].join(", ")}`);
  const fields = new Set(schema?.fields ?? []);
  for (const collection of ["string_list_fields", "json_array_fields", "timestamp_fields"]) {
    if (!Array.isArray(schema?.[collection])) {
      errors.push(`${collection} must be an array`);
      continue;
    }
    for (const field of schema[collection]) {
      if (!fields.has(field)) errors.push(`${collection} references unknown field: ${field}`);
    }
  }
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) errors.push(`field rule references unknown field: ${field}`);
    if (!["number", "integer", "enum", "string"].includes(rule?.type)) {
      errors.push(`field rule has unsupported type for ${field}`);
    }
    if (rule?.type === "enum" && (!Array.isArray(rule.values) || rule.values.length === 0)) {
      errors.push(`enum field rule requires values for ${field}`);
    }
    if (rule?.type === "string" && rule.pattern) {
      try {
        new RegExp(rule.pattern);
      } catch {
        errors.push(`string field rule has invalid pattern for ${field}`);
      }
    }
  }
  const jsonFieldLimits = schema?.json_field_maximum_characters;
  if (!jsonFieldLimits || typeof jsonFieldLimits !== "object" || Array.isArray(jsonFieldLimits)) {
    errors.push("json_field_maximum_characters must be an object");
  } else {
    for (const field of schema?.json_array_fields ?? []) {
      if (!Number.isInteger(jsonFieldLimits[field]) || jsonFieldLimits[field] < 1) {
        errors.push(`json field maximum is invalid for ${field}`);
      }
    }
    for (const field of Object.keys(jsonFieldLimits)) {
      if (!(schema?.json_array_fields ?? []).includes(field)) {
        errors.push(`json field maximum references non-JSON field: ${field}`);
      }
    }
  }

  const statuses = new Set(schema?.pipeline_statuses ?? []);
  const businessResults = new Set(schema?.business_results ?? []);
  const operationalConditions = new Set(schema?.operational_conditions ?? []);
  if (businessResults.size !== 3 ||
      !["ready_to_apply", "review_needed", "skip"].every((status) => businessResults.has(status))) {
    errors.push("business_results must contain only ready_to_apply, review_needed, and skip");
  }
  if ([...businessResults].some((status) => operationalConditions.has(status))) {
    errors.push("business results and operational conditions must be disjoint");
  }
  if (
    [...businessResults, ...operationalConditions].some(
      (status) => !statuses.has(status)
    ) ||
    statuses.size !== businessResults.size + operationalConditions.size
  ) {
    errors.push("pipeline_statuses must be exactly the business results and operational conditions");
  }
  const actions = new Set(schema?.user_actions ?? []);
  if (
    actions.size !== 5 ||
    !["", "I Applied", "Skip", "Proceed", "Reject"].every((action) =>
      actions.has(action)
    )
  ) {
    errors.push("user_actions must contain only the supported operator actions");
  }
  if (
    JSON.stringify(schema?.legacy_user_action_mapping) !==
    JSON.stringify({ Approve: "Proceed", Deny: "Reject" })
  ) {
    errors.push("legacy_user_action_mapping must normalize Approve and Deny");
  }
  const preparationStatuses = new Set(schema?.preparation_statuses ?? []);
  const expectedPreparationStatuses = [
    "",
    "pending",
    "preparing",
    "message_ready",
    "needs_input",
    "external_steps",
    "repair_pending",
    "preparation_error"
  ];
  if (
    preparationStatuses.size !== expectedPreparationStatuses.length ||
    !expectedPreparationStatuses.every((status) =>
      preparationStatuses.has(status)
    )
  ) {
    errors.push("preparation_statuses must contain the supported lifecycle");
  }
  for (const status of expectedPreparationStatuses) {
    const destinations = schema?.preparation_transitions?.[status];
    if (!Array.isArray(destinations) || destinations.length === 0) {
      errors.push(
        `missing preparation transitions for status: ${status || "(blank)"}`
      );
    } else if (
      destinations.some((value) => !preparationStatuses.has(value))
    ) {
      errors.push(
        `preparation transition contains an unknown status: ${
          status || "(blank)"
        }`
      );
    }
  }
  for (const [from, destinations] of Object.entries(schema?.transitions ?? {})) {
    if (!statuses.has(from)) errors.push(`transition source is not a status: ${from}`);
    for (const to of destinations) {
      if (!statuses.has(to)) errors.push(`transition destination is not a status: ${to}`);
    }
  }
  for (const status of statuses) {
    if (!(status in (schema?.transitions ?? {}))) errors.push(`missing transitions for status: ${status}`);
    const supportedActions = schema?.actions_by_status?.[status];
    if (!Array.isArray(supportedActions) || supportedActions.length === 0) {
      errors.push(`missing actions_by_status for status: ${status}`);
    } else if (supportedActions.some((action) => !actions.has(action))) {
      errors.push(`actions_by_status contains an unsupported action for status: ${status}`);
    }
  }
  const expectedStores = [
    "Scraped Jobs",
    "To Review",
    "To Apply",
    "Applied Jobs",
    "Archive"
  ];
  if (
    JSON.stringify(schema?.business_stores) !== JSON.stringify(expectedStores)
  ) {
    errors.push(
      "business_stores must contain the five segmented stores in canonical order"
    );
  }
  const expectedAuthoritativeStores = {
    scraped: "Scraped Jobs",
    review: "To Review",
    apply: "To Apply",
    applied: "Applied Jobs",
    archived: "Archive",
    claims: "_System"
  };
  if (
    JSON.stringify(schema?.authoritative_stores) !==
    JSON.stringify(expectedAuthoritativeStores)
  ) {
    errors.push("authoritative_stores must match the segmented storage contract");
  }
  for (const store of expectedStores) {
    const statusRules = schema?.actions_by_store_status?.[store];
    if (!statusRules || typeof statusRules !== "object") {
      errors.push(`missing actions_by_store_status for store: ${store}`);
      continue;
    }
    for (const [status, storeActions] of Object.entries(statusRules)) {
      if (!statuses.has(status)) {
        errors.push(
          `actions_by_store_status references unknown status for ${store}: ${status}`
        );
        continue;
      }
      if (!Array.isArray(storeActions) || storeActions.length === 0) {
        errors.push(
          `actions_by_store_status requires actions for ${store}/${status}`
        );
        continue;
      }
      const globallyAllowed = new Set(schema?.actions_by_status?.[status] ?? []);
      for (const action of storeActions) {
        if (!actions.has(action) || !globallyAllowed.has(action)) {
          errors.push(
            `actions_by_store_status contains unsupported action for ${store}/${status}`
          );
        }
      }
    }
  }
  return errors;
}

function validateUniqueIdentityAcrossStores(stores, schema, now = new Date().toISOString()) {
  const errors = [];
  const identities = new Map();
  for (const [store, rows] of Object.entries(stores ?? {})) {
    if (!Array.isArray(rows)) {
      errors.push(`${store} rows must be an array`);
      continue;
    }
    for (const [index, raw] of rows.entries()) {
      const record = normalizeLegacyRecord(raw, schema, now);
      const identity = String(record.canonical_job_id || "")
        .normalize("NFKC")
        .toLocaleLowerCase("en-US");
      if (!identity) {
        errors.push(`${store} row ${index + 2} has invalid identity`);
        continue;
      }
      const previous = identities.get(identity);
      if (previous) {
        errors.push(
          `duplicate canonical identity at ${previous.store} row ${previous.row} and ${store} row ${index + 2}`
        );
      } else {
        identities.set(identity, { store, row: index + 2 });
      }
    }
  }
  return errors;
}

function canTransition(schema, from, to) {
  return (schema.transitions?.[from] ?? []).includes(to);
}

function canTransitionPreparation(schema, from, to) {
  return (schema.preparation_transitions?.[from ?? ""] ?? []).includes(to ?? "");
}

function transitionRecord(record, to, schema, now = new Date().toISOString()) {
  const from = record.pipeline_status;
  if (!canTransition(schema, from, to)) {
    throw new Error(`Invalid pipeline transition: ${from} -> ${to}`);
  }
  const next = {
    ...record,
    pipeline_status: to,
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function isStaleClaim(record, nowMs, leaseMs) {
  if (!record.processing_token || !record.processing_started_at) return true;
  const startedAt = Date.parse(record.processing_started_at);
  return !Number.isFinite(startedAt) || nowMs - startedAt >= leaseMs;
}

function processingCommitGuard(token) {
  const value = String(token || "").trim();
  return value ? `commit:${value}` : "";
}

function claimRecord(record, { stage, token, now, leaseMs }) {
  const nowMs = Date.parse(now);
  if (!stage || !token || !Number.isFinite(nowMs) || !Number.isFinite(leaseMs) || leaseMs < 1) {
    throw new Error("stage, token, valid now, and positive leaseMs are required");
  }
  if (record.processing_token && !isStaleClaim(record, nowMs, leaseMs)) {
    return { claimed: false, record };
  }
  const claimedRecord = {
    ...record,
    processing_stage: stage,
    processing_token: token,
    processing_commit_guard: processingCommitGuard(token),
    processing_started_at: now,
    updated_at: now
  };
  return {
    claimed: true,
    record: { ...claimedRecord, state_guard: stateGuard(claimedRecord) }
  };
}

function releaseClaim(record, token, now = new Date().toISOString()) {
  if (record.processing_token && record.processing_token !== token) {
    throw new Error("processing token mismatch");
  }
  const next = {
    ...record,
    processing_stage: "",
    processing_token: "",
    processing_started_at: "",
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function createProcessingClaim(record, executionId, now, leaseMs) {
  const token = `${executionId}:${record.canonical_job_id}:${record.work_stage}`;
  return {
    canonical_job_id: record.canonical_job_id,
    processing_stage: record.work_stage,
    processing_token: token,
    created_at: now,
    expires_at: new Date(Date.parse(now) + leaseMs).toISOString()
  };
}

function chooseWinningClaims(proposedRecords, allClaims, now = new Date().toISOString()) {
  const claimKey = (record) =>
    `${String(record?.canonical_job_id || "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US")}:${String(
      record?.processing_stage || record?.work_stage || ""
    ).trim()}`;
  const nowMs = Date.parse(now);
  const expectedLeaseMsByKey = new Map();
  for (const record of proposedRecords) {
    const claimCreatedAt = Date.parse(
      record?.claim_created_at ?? record?.created_at
    );
    const claimExpiresAt = Date.parse(
      record?.claim_expires_at ?? record?.expires_at
    );
    const leaseMs = claimExpiresAt - claimCreatedAt;
    if (Number.isFinite(leaseMs) && leaseMs > 0) {
      expectedLeaseMsByKey.set(claimKey(record), leaseMs);
    }
  }
  const rowNumberCounts = new Map();
  for (const claim of allClaims) {
    const rowNumber = Number(claim?.row_number);
    if (!Number.isInteger(rowNumber) || rowNumber < 2) continue;
    rowNumberCounts.set(
      rowNumber,
      (rowNumberCounts.get(rowNumber) || 0) + 1
    );
  }
  const validClaims = allClaims.filter((claim) => {
    const createdAt = Date.parse(claim.created_at);
    const expiresAt = Date.parse(claim.expires_at);
    const rowNumber = Number(claim.row_number);
    const expectedLeaseMs = expectedLeaseMsByKey.get(claimKey(claim));
    return (
      claim.canonical_job_id &&
      claim.processing_stage &&
      claim.processing_token &&
      Number.isFinite(createdAt) &&
      Number.isFinite(expiresAt) &&
      createdAt <= nowMs &&
      expiresAt > createdAt &&
      expiresAt > nowMs &&
      (!Number.isFinite(expectedLeaseMs) ||
        expiresAt - createdAt <= expectedLeaseMs) &&
      Number.isInteger(rowNumber) &&
      rowNumber >= 2 &&
      rowNumberCounts.get(rowNumber) === 1
    );
  });
  const winners = new Map();
  for (const claim of validClaims) {
    const key = claimKey(claim);
    const current = winners.get(key);
    const claimRow = Number(claim.row_number);
    if (!current || claimRow < Number(current.row_number)) {
      winners.set(key, claim);
    }
  }
  const emitted = new Set();
  return proposedRecords.filter((record) => {
    const key = claimKey(record);
    if (
      emitted.has(key) ||
      winners.get(key)?.processing_token !== record.processing_token
    ) {
      return false;
    }
    emitted.add(key);
    return true;
  });
}


const PROFILE_VERSION_PATTERN = /^(?:\d{4}-\d{2}-\d{2}|sheet\/[a-f0-9]{16})$/;
const UNRESOLVED_PLACEHOLDER_PATTERN =
  /\[(?:add|insert|month|year|tbd|todo|unknown|not provided)\b[^\]]*\]/i;

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function collectStrings(value, output = []) {
  if (typeof value === "string") {
    output.push(value);
  } else if (Array.isArray(value)) {
    for (const entry of value) collectStrings(entry, output);
  } else if (isPlainObject(value)) {
    for (const entry of Object.values(value)) collectStrings(entry, output);
  }
  return output;
}

function findDuplicates(values) {
  const seen = new Set();
  const duplicates = new Set();
  for (const value of values) {
    const normalized = String(value).trim().toLowerCase();
    if (seen.has(normalized)) duplicates.add(normalized);
    seen.add(normalized);
  }
  return [...duplicates];
}

function validateHttpsUrl(value, field, errors) {
  const url = parseHttpUrl(value);
  if (!url) {
    errors.push(`${field} must be a valid URL`);
  } else if (url.protocol !== "https:") {
    errors.push(`${field} must use https`);
  }
}

function approvedCandidateUrls(profile) {
  const contactLinks = Object.values(profile?.candidate?.links ?? {});
  const projectLinks = (profile?.projects ?? []).map((project) => project.url).filter(Boolean);
  return [...new Set([...contactLinks, ...projectLinks])];
}

function approvedSkillNames(profile) {
  return [
    ...new Set(
      Object.values(profile?.skills ?? {})
        .flat()
        .map((skill) => String(skill).trim())
        .filter(Boolean)
    )
  ];
}

function approvedProjectNames(profile) {
  return (profile?.projects ?? []).map((project) => project.name);
}

function profileEvidenceText(profile) {
  return collectStrings(profile).join("\n");
}

function validateCandidateProfile(profile) {
  const errors = [];

  if (!isPlainObject(profile)) return ["profile must be an object"];
  if (profile.schema_version !== 1) errors.push("schema_version must be 1");
  if (!PROFILE_VERSION_PATTERN.test(profile.profile_version ?? "")) {
    errors.push("profile_version must use YYYY-MM-DD or sheet/<context-hash>");
  }
  if (!profile.candidate?.name) errors.push("candidate.name is required");
  if (!profile.candidate?.email) errors.push("candidate.email is required");
  if (!isPlainObject(profile.candidate?.links)) errors.push("candidate.links is required");
  if (!profile.summary) errors.push("summary is required");
  if (!isPlainObject(profile.skills) || Object.keys(profile.skills).length === 0) {
    errors.push("skills are required");
  }
  if (!Array.isArray(profile.experience) || profile.experience.length === 0) {
    errors.push("experience is required");
  }
  if (!Array.isArray(profile.projects) || profile.projects.length === 0) {
    errors.push("projects are required");
  }

  for (const [key, value] of Object.entries(profile.candidate?.links ?? {})) {
    validateHttpsUrl(value, `candidate.links.${key}`, errors);
  }
  for (const project of profile.projects ?? []) {
    if (!project.id || !project.name) errors.push("every project requires id and name");
    if (project.url) validateHttpsUrl(project.url, `projects.${project.id || "unknown"}.url`, errors);
    const technologyDuplicates = findDuplicates(project.technologies ?? []);
    if (technologyDuplicates.length > 0) {
      errors.push(
        `duplicate project technologies for ${project.id || "unknown"}: ${technologyDuplicates.join(", ")}`
      );
    }
  }

  const projectIdDuplicates = findDuplicates((profile.projects ?? []).map((project) => project.id));
  if (projectIdDuplicates.length > 0) errors.push(`duplicate project ids: ${projectIdDuplicates.join(", ")}`);

  const skills = approvedSkillNames(profile);
  const skillDuplicates = findDuplicates(Object.values(profile.skills ?? {}).flat());
  if (skillDuplicates.length > 0) errors.push(`duplicate skills: ${skillDuplicates.join(", ")}`);
  if (skills.length === 0) errors.push("at least one skill is required");

  const profileText = profileEvidenceText(profile);
  if (UNRESOLVED_PLACEHOLDER_PATTERN.test(profileText)) {
    errors.push("resume placeholders are not allowed");
  }

  return errors;
}

function validateApplicationPolicy(policy, profile) {
  const errors = [];
  if (!isPlainObject(policy)) return ["policy must be an object"];
  if (policy.schema_version !== 1) errors.push("policy schema_version must be 1");
  if (!PROFILE_VERSION_PATTERN.test(policy.policy_version ?? "")) {
    errors.push("policy_version must use YYYY-MM-DD or sheet/<context-hash>");
  }
  if (policy.candidate_profile_version !== profile?.profile_version) {
    errors.push("policy candidate_profile_version must match the candidate profile");
  }
  if (policy.manual_submission_required !== true) {
    errors.push("manual_submission_required must be true");
  }
  if (!Number.isInteger(policy.max_body_words) || policy.max_body_words < 1) {
    errors.push("max_body_words must be a positive integer");
  }

  const linkKeys = new Set(Object.keys(profile?.candidate?.links ?? {}));
  for (const key of policy.approved_candidate_url_keys ?? []) {
    if (!linkKeys.has(key)) errors.push(`unsupported approved_candidate_url_key: ${key}`);
  }

  const projectIds = new Set((profile?.projects ?? []).map((project) => project.id));
  for (const projectId of policy.approved_project_ids ?? []) {
    if (!projectIds.has(projectId)) errors.push(`unsupported approved_project_id: ${projectId}`);
  }

  return errors;
}

function assertValidProfileConfiguration(profile, policy) {
  const errors = [
    ...validateCandidateProfile(profile),
    ...validateApplicationPolicy(policy, profile)
  ];
  if (errors.length > 0) {
    throw new Error(`Invalid candidate configuration:\n- ${errors.join("\n- ")}`);
  }
  return true;
}


const SENIORITY_PATTERN =
  /\b(?:senior|sr\.?|lead|principal|staff|architect|head of|director|tech lead|engineering lead)\b|(?:5|6|7|8|9|10)\+?\s*(?:years?|yrs?)/i;
const MAX_RANKING_TEXT_LENGTH = 50000;

// Message validation remains fail-closed even if the ranking policy changes.
const UNSUPPORTED_TECHNOLOGIES = [
  "Angular",
  "Expo",
  "GoHighLevel",
  "Kubernetes",
  "LangChain",
  "Laravel",
  "PHP",
  "React Native",
  "Ruby",
  "Ruby on Rails",
  "Shopify",
  "Svelte",
  "Vue",
  "WordPress"
];

const SKILL_ALIASES = {
  "ASP.NET Core MVC": ["asp.net core", ".net core", "asp net core"],
  AWS: ["aws", "amazon web services"],
  "C#": ["c#", "c sharp"],
  "CI/CD": ["ci/cd", "continuous integration", "continuous delivery"],
  "Express.js": ["express.js", "express js", "express"],
  Flutter: ["flutter"],
  "GitHub Actions": ["github actions"],
  "Google Sheets API": ["google sheets api", "google sheets"],
  JavaScript: ["javascript", "js"],
  Mapbox: ["mapbox"],
  "Next.js": ["next.js", "nextjs", "next js"],
  "Node.js": ["node.js", "nodejs", "node js"],
  "OpenAI API": ["openai api", "openai"],
  PayMongo: ["paymongo"],
  PostgreSQL: ["postgresql", "postgres", "postgre sql"],
  React: ["react"],
  "REST APIs": ["rest api", "restful api", "api integration"],
  Supabase: ["supabase"],
  "Tailwind CSS": ["tailwind css", "tailwind"],
  TypeScript: ["typescript", "ts"],
  Vitest: ["vitest"],
  Docker: ["docker"],
  Drizzle: ["drizzle"],
  MongoDB: ["mongodb", "mongo db"],
  MySQL: ["mysql"],
