    providerStatus: 0,
    providerClassification: 'retryable_rejection',
    errorCategory: 'provider_retryable',
    nextRetryAt: retryable
      ? new Date(Date.parse(now) + ALERT_POLICY.retry.backoff_ms).toISOString()
