function normalizedSheetTitle(range) {
  const text = String(range || "").trim();
  const separator = text.indexOf("!");
  if (separator < 1) return "";
  const raw = text.slice(0, separator);
  if (raw.startsWith("'") && raw.endsWith("'")) {
    return raw.slice(1, -1).replace(/''/g, "'");
  }
  return raw;
}

function nonBlankRow(values) {
  return Array.isArray(values) && values.some((value) => {
    if (value === null || value === undefined) return false;
    return String(value).trim() !== "";
  });
}

function assertDefinitions(definitions) {
  if (!Array.isArray(definitions) || definitions.length === 0) {
    throw new Error("Batch Sheet definitions must be a non-empty array");
  }
  const names = new Set();
  for (const definition of definitions) {
    const name = String(definition?.name || "");
    if (!name || names.has(name)) {
      throw new Error("Batch Sheet definitions contain a missing or duplicate title");
    }
    if (
      !Array.isArray(definition?.fields) ||
      definition.fields.length === 0 ||
      new Set(definition.fields).size !== definition.fields.length
    ) {
      throw new Error(`${name} has an invalid field contract`);
    }
    names.add(name);
  }
}

function parseBatchSheetRows(response, definitions) {
  assertDefinitions(definitions);
  const valueRanges = response?.valueRanges;
  if (!Array.isArray(valueRanges)) {
    throw new Error("Google Sheets batch response is missing valueRanges");
  }
  const byTitle = new Map();
  for (const valueRange of valueRanges) {
    const title = normalizedSheetTitle(valueRange?.range);
    if (!title || byTitle.has(title)) {
      throw new Error("Google Sheets batch response contains an ambiguous range");
    }
    byTitle.set(title, valueRange);
  }

  const result = {};
  for (const definition of definitions) {
    const valueRange = byTitle.get(definition.name);
    if (!valueRange) {
      throw new Error(`Google Sheets batch response is missing ${definition.name}`);
    }
    const values = Array.isArray(valueRange.values) ? valueRange.values : [];
    if (values.length === 0) {
      throw new Error(`${definition.name} is missing its header row`);
    }
    const headers = Array.isArray(values[0])
      ? values[0].map((value) => String(value || "").trim())
      : [];
    if (JSON.stringify(headers) !== JSON.stringify(definition.fields)) {
      throw new Error(`${definition.name} headers do not match the configured contract`);
    }
    result[definition.name] = values.slice(1).flatMap((row, index) => {
      if (!nonBlankRow(row)) return [];
      const record = Object.fromEntries(
        definition.fields.map((field, column) => [field, row?.[column] ?? ""])
      );
      return [{ ...record, row_number: index + 2 }];
    });
  }
  return result;
}

function googleSheetsBatchRanges(sheetNames) {
  if (!Array.isArray(sheetNames) || sheetNames.length === 0) {
    throw new Error("At least one Sheet range is required");
  }
  const seen = new Set();
  return sheetNames.map((name) => {
    const title = String(name || "");
    if (!title || seen.has(title)) {
      throw new Error("Sheet ranges contain a missing or duplicate title");
    }
    seen.add(title);
    return `'${title.replace(/'/g, "''")}'`;
  });
}

function parseHttpUrl(value, { baseOrigin = "" } = {}) {
  let input = String(value ?? "").trim();
  if (!input) return null;

  if (input.startsWith("/")) {
    const base = parseHttpUrl(baseOrigin);
    if (!base) return null;
    input = `${base.protocol}//${base.hostname}${base.port ? `:${base.port}` : ""}${input}`;
  }

  if (/[\u0000-\u0020\u007f\\]/.test(input)) return null;
  const match = input.match(
    /^(https?):\/\/([^/?#]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i
  );
  if (!match) return null;

  const protocol = `${match[1].toLowerCase()}:`;
  const authority = match[2];
  if (!authority || authority.includes("@") || authority.includes("[")) return null;

  const colonIndex = authority.lastIndexOf(":");
  let hostname = authority;
  let port = "";
  if (colonIndex >= 0) {
    if (authority.indexOf(":") !== colonIndex) return null;
    hostname = authority.slice(0, colonIndex);
    port = authority.slice(colonIndex + 1);
    if (!/^\d{1,5}$/.test(port)) return null;
    const portNumber = Number(port);
    if (portNumber < 1 || portNumber > 65535) return null;
  }

  hostname = hostname.toLowerCase();
  if (
    hostname.length > 253 ||
    hostname.split(".").some(
      (label) =>
        !label ||
        label.length > 63 ||
        !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label)
    )
  ) {
    return null;
  }

  const pathname = match[3] || "/";
  const search = match[4] || "";
  const hash = match[5] || "";
  return {
    protocol,
    hostname,
    port,
    pathname,
    search,
    hash,
    username: "",
    password: "",
    href: `${protocol}//${hostname}${port ? `:${port}` : ""}${pathname}${search}${hash}`
  };
}

function normalizeCanonicalUrl(value) {
  const parsed = parseHttpUrl(value, {
    baseOrigin: "https://www.onlinejobs.ph"
  });
  if (!parsed) return "";
  if (parsed.port && parsed.port !== "443") return "";
  const hostname =
    parsed.hostname === "www.onlinejobs.ph"
      ? "onlinejobs.ph"
      : parsed.hostname;
  if (hostname !== "onlinejobs.ph") return "";
  const pathname = parsed.pathname.replace(/\/+/g, "/").replace(/\/$/, "");
  if (!/^\/jobseekers\/job\/[^/]+$/i.test(pathname)) return "";
  return `https://${hostname}${pathname}`;
}

function extractOnlineJobsId(url) {
  const canonicalUrl = normalizeCanonicalUrl(url);
  if (!canonicalUrl) return "";
  const match = canonicalUrl.match(/\/jobseekers\/job\/[^/]*?(\d+)$/i);
  return match?.[1] ?? "";
}

function canonicalJobId(record) {
  const source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  const sourceJobId = String(record.source_job_id || extractOnlineJobsId(record.canonical_url || record.job_url) || "").trim();
  if (sourceJobId) return `${source}:${sourceJobId}`;
  const canonicalUrl = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  if (!canonicalUrl) return "";
  let hash = 2166136261;
  for (let index = 0; index < canonicalUrl.length; index += 1) {
    hash ^= canonicalUrl.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  const digest = (hash >>> 0).toString(16).padStart(8, "0");
  return `${source}:url:${digest}`;
}

function stableContractValue(value) {
  if (Array.isArray(value)) return value.map(stableContractValue);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, stableContractValue(value[key])])
    );
  }
  return value;
}

function contractDigest(value) {
